window.KRONOLOJI_SINIR_NOKTA2 = [{"t":"1051-07-05","devlet":"papalik","taraflar":["benevento-papalik","papalik"],"b":"Benevento halkı şehri Papa IX. Leo'ya teslim etti; papalık Benevento'ya girdi (papalik, benevento-papalik)","tur":"toprak-kazanc","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","benevento-papalik","papalik"],"yer_id":"Benevento","gun":"5 Temmuz 1051 (teslim Nisan 1051; Papa şehre 5 Temmuz'da girdi)","d":"Düşmanlarından bunalan Beneventolular Nisan 1051'de şehri papalık otoritesine bıraktı; Leo IX 5 Temmuz 1051'de şehre girdi. Catholic Encyclopedia ayrıca III. Henry'nin şehri 1053'te Bamberg haracı karşılığında papaya devrettiğini, Normanların ardından yeniden işgal ettiğini yazar; Civitate (Haziran 1053) sonrası Pandulf papalığın vasalı olarak döndü. 1053 için gün verilmiyor. Bu olayda ilgili yerleşimler: Benevento.","kaynak":"Catholic Encyclopedia, 'Archdiocese of Benevento' (newadvent/catholic.com); Pandulf III of Benevento (Vikipedi, yalnız ikincil teyit)","sinif":"D"},{"t":"1076-12-13","devlet":"apulya-dukaligi","taraflar":["salerno-prensligi","apulya-dukaligi"],"b":"Salerno şehri Robert Guiscard'a teslim oldu; Gisulf II kaleye çekildi (salerno-prensligi, apulya-dukaligi)","tur":"toprak-kayip","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","salerno-prensligi","apulya-dukaligi"],"yer_id":"Salerno","gun":"13 Aralık 1076","d":"Yaz 1076'da başlayan kuşatmanın ardından Salerno şehri 13 Aralık 1076'da Robert Guiscard'a teslim oldu; Prens II. Gisulf ve adamları kaleye çekildi, kale Mayıs 1077'de düştü. Böylece İtalya'nın son Lombard devleti Salerno Prensliği Apulya Dükalığı'na katıldı. Bu olayda ilgili yerleşimler: Salerno.","kaynak":"Gisulf II of Salerno (Vikipedi) ve List of princes of Salerno; ikincil, gün teyidi yalnız bu kaynaklarda; Robert Guiscard biyografisi Aralık 1076","sinif":"D"},{"t":"1128-01-01","devlet":"sicilya-kralligi","taraflar":["apulya-dukaligi","sicilya-kralligi"],"b":"Papa II. Honorius, Benevento'da Roger'i Apulia Dükü olarak atadı; Apulia dukalığı (Salerno, Melfi dahil) Sicilya Kontu Roger'in eline geçti","tur":"antlasma","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","apulya-dukaligi","sicilya-kralligi"],"yer_id":"Salerno","gun":"Ağustos 1128 (gün kaynakta yok)","d":"II. Guillaume'un Temmuz 1127'de çocuksuz ölmesi üzerine Roger Hauteville mirasını talep etti; papalık karşı koalisyonu başarısız olunca Ağustos 1128'de Honorius onu Benevento'da Apulia Dükü atadı, Eylül 1129'da Napoli ve Capua dahil başkaları tarafından tanındı. Kaynak Salerno ve Melfi'yi bu olayda adıyla anmaz; yıl uyuşur, ay Ağustos'tur. Bu olayda ilgili yerleşimler: Melfi, Salerno.","kaynak":"Dizionario Biografico degli Italiani (Treccani), 'Ruggero II, re di Sicilia' — «Il 22 agosto 1128, presso Benevento, Ruggero fu investito del Ducato di Puglia, Calabria e Sicilia dal papa,»","sinif":"D"},{"t":"1162-01-01","devlet":"aragon","taraflar":["barselona-kontlugu","aragon"],"b":"Ramon Berenguer IV'ün 1162 ölümüyle oğlu Alfons Barselona Kontluğu'nu ve Aragon Krallığı'nı miras aldı; Petronilla 1164'te Aragon tacından feragat etti","tur":"birlesme","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","barselona-kontlugu","aragon"],"yer_id":"Vic (Ausona / Osona)","gun":"1162 (ölüm ve vasiyet); Petronilla'nın feragat belgesi 1164 (18 Haziran, kaynaklar 18 Temmuz da der)","d":"Ramon Berenguer IV 1162'de öldü, vasiyeti Huesca'da okundu ve oğlu Alfons hem Aragon Krallığı'nı hem Barselona Kontluğu'nu aldı; Petronilla'nın feragati sonraki yıl(lar)da belgelendi. Vic/Osona'ya özgü bir 1164 olayı bulunamadı; bu birleşme Vic'in bağlı olduğu Barselona kontluğu ile Aragon'un tek hükümdarda birleşmesidir. Bu olayda ilgili yerleşimler: Vic (Ausona / Osona).","kaynak":"Gran Enciclopèdia Catalana, Alfons I de Catalunya, https://www.enciclopedia.cat/gran-enciclopedia-catalana/alfons-i-de-catalunya ; Ramon Berenguer IV, https://www.enciclopedia.cat/gran-enciclopedia-catalana/ramon-berenguer-iv-de-barcelona","sinif":"D"},{"t":"1189-10-03","devlet":"kamakura","taraflar":["oshu-fujiwara","kamakura"],"b":"Minamoto no Yoritomo Oshu Fujiwara'yi yok etti, Hiraizumi'ye girdi","tur":"son","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","oshu-fujiwara","kamakura"],"yer_id":"Hiraizumi (Ōshū Fujiwara başkenti)","gun":"3 Ekim 1189","d":"Yoritomo 1 Eylul 1189'da Oshu seferine cikti; Yasuhira 2 Ekim'de sehri yakarak kacti, Yoritomo ertesi gun Hiraizumi'ye girdi. Yasuhira 14 Ekim 1189'da Nienosaku'da (Mutsu) oldurulmustur. Bu olayda ilgili yerleşimler: Hiraizumi (Ōshū Fujiwara başkenti).","kaynak":"山川 日本史小辞典 改訂新版, «奥州合戦» (kotobank.jp/word/奥州合戦-3132137) — «8月には…逃げる泰衡を追って22日，藤原氏の本拠地平泉…にいたった。»","sinif":"D"},{"t":"1203-01-01","devlet":"fransa","taraflar":["anjou-kontlugu","fransa"],"b":"Fransa Kralı II. Philippe Auguste Anjou Kontluğu'nu (Saumur kalesi dahil) Plantagenet hükümdarı John'dan aldı","tur":"toprak-kazanc","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","anjou-kontlugu","fransa"],"yer_id":"Saumur","gun":"1203 (Saumur), Anjou'nun genel fethi 1204","d":"Philippe Auguste Saumur kalesini 1203'te ele geçirdi; Angers ve bölge 1204'te Fransa'ya katıldı, Chinon 23 Haziran 1205'te düştü. Kaynaklar yalnızca yıl verir, gün bulunamadı. Bu olayda ilgili yerleşimler: Saumur.","kaynak":"https://great-castles.com/saumur.html (Saumur 1203); Angers 1204 için müze/turizm sayfası; akademik kaynağa ulaşılamadı, zayıf","sinif":"D"},{"t":"1205-01-01","devlet":"gurlu","taraflar":["sena","gurlu"],"b":"Bahtiyar Halacî'nin Nadia'yı alması: Sena Devleti'nin Nadia ve Bengal'deki toprakları Gurlular'a geçti (Somapura/Paharpur dahil Sena kuzey Bengal'i sonraki fetihle)","tur":"toprak-kazanc","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","sena","gurlu"],"yer_id":"Nadia (Navadvipa/Nabadwip)","gun":"1204 sonu - 1205 başı (kesin gün bilinmiyor)","d":"Gurlu komutanı Muhammed Bahtiyar Halacî küçük bir süvari birliğiyle Sena kralı Lakşmanasena'nın başkenti Nadia'ya baskın yaptı; kral kaçtı ve Bengal'in doğusuna çekildi. Banglapedia seferin 1204 kışında başlayıp Nadia'nın 1205 başında düştüğünü yazar; Vikipedi 1202-1205 aralığını tartışmalı gösterir. Paharpur (Somapura) için ayrı tarih bulunamadı, aynı fetih zincirine bağlandı. Bu olayda ilgili yerleşimler: Nadia (Navadvipa/Nabadwip), Somapura Mahavihara (Paharpur).","kaynak":"Banglapedia (Asiatic Society of Bangladesh), «Bakhtiyar Khalji» ve «Nadia» maddeleri; TDV, «Bahtiyar Halacî» (yönlendirme maddesi) — «Bakhtiyar Khalji inaugurated Muslim rule in Bengal by conquering Nadia in early 1205 AD.»","sinif":"D"},{"t":"1206-03-15","devlet":"delhi-sultanligi","taraflar":["gurlu","delhi-sultanligi"],"b":"Mu’izzüddin Muhammed Gûrî’nin öldürülmesiyle Gurlu Hindistan toprakları (Bihar Şerif, Vikramaşîla, Somapura, Mahoba, Nadia, Sambhar) Delhi Sultanlığı’na geçti","tur":"son","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","gurlu","delhi-sultanligi"],"yer_id":"Nadia (Navadvipa/Nabadwip)","gun":"15 Mart 1206","d":"Mu'izzüddin Muhammed Gurî 15 Mart 1206'da Indus kıyısında Damyak'ta suikastla öldü; çocuğu olmadığından Hindistan valisi Kutbüddin Aybek Lahor'da hükümdarlığı üstlenerek Delhi Sultanlığı'nın temelini attı. Hindistan'daki Gurlu fetihlerinin tamamı bu devirle sultanlığa kaldı. Bu olayda ilgili yerleşimler: Bihar Şerif (Odantapuri), Mahoba, Nadia (Navadvipa/Nabadwip), Sambhar (Sakambhari), Somapura Mahavihara (Paharpur), Vikramaşîla (Antichak).","kaynak":"TDV İslâm Ansiklopedisi, «Gurlular» (islamansiklopedisi.org.tr/gurlular) — «Demyek’te kurulan ordugâhta namaz kıldığı sırada bir İsmâilî fedaisi tarafından öldürüldü (602/1206).»","sinif":"D"},{"t":"1230-09-24","devlet":"kastilya","taraflar":["leon-kralligi","kastilya"],"b":"IX. Alfonso'nun ölümüyle Leon Krallığı (Zamora, Astorga, Mérida) Kastilya Kralı III. Fernando'ya geçti, iki krallık birleşti","tur":"birlesme","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","leon-kralligi","kastilya"],"yer_id":"Zamora","gun":"24 Eylül 1230","d":"Leon Kralı IX. Alfonso 24 Eylül 1230'da öldü; vasiyeti kızlarına verse de Kastilya Kralı III. Fernando Leon tahtını fiilen aldı ve Kastilya ile Leon kalıcı olarak birleşti. Kız kardeşler Sancha ve Dulce 11 Aralık 1230'da Benavente anlaşmasıyla haklarından para karşılığı vazgeçti. Yer listesindeki Zamora, Astorga ve Mérida Leon Krallığı'na aitti. Bu olayda ilgili yerleşimler: Astorga (Asturica), Mârida (Mérida), Zamora.","kaynak":"Enciclopedia Italiana (Treccani), 'Ferdinando III il Santo, re di Castiglia e di León' — «Poi, alla morte di Alfonso IX (1230), F. ebbe anche il regno di León»","sinif":"D"},{"t":"1262-01-01","devlet":"izlanda-norvec-danimarka","taraflar":["izlanda-serbest-devleti","izlanda-norvec-danimarka"],"b":"İzlanda reisleri Norveç Kralı IV. Hákon'a bağlılık yemini etti; İzlanda Özgür Devleti (Þingvellir/Skálholt) Norveç tacına bağlandı","tur":"vassal","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","izlanda-serbest-devleti","izlanda-norvec-danimarka"],"yer_id":"Þingvellir (Thingvellir, Althing)","gun":"1262 (gün bilinmiyor; antlaşma süreci 1262-1264)","d":"Sturlung Çağı iç çatışmaları sonunda İzlandalı reisler 1262'de Norveç kralını tanıdı (Gamli sáttmáli / Gissurarsáttmáli); süreç 1264'e kadar sürdü. Sözleşme metninin sonraki yüzyıllarda yeniden yazıldığı tartışmalıdır. Bu olayda ilgili yerleşimler: Skálholt, Þingvellir (Thingvellir, Althing).","kaynak":"Lex.dk, 'gamli sáttmáli' https://lex.dk/gamli_s%C3%A1ttm%C3%A1li ; Saga (2011) https://timarit.is/page/7005689","sinif":"D"},{"t":"1266-07-02","devlet":"iskocya","taraflar":["man-ve-adalar-krallik","iskocya"],"b":"Perth Antlaşması: Norveç, Man Adası ve Hebridler'i İskoçya'ya bıraktı","tur":"antlasma","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","man-ve-adalar-krallik","iskocya"],"yer_id":"Peel (Man)","gun":"2 Temmuz 1266","d":"Norveç Kralı VI. Magnus, Man Adası ve Batı Adaları'nın egemenliğini 4000 mark peşin ve yıllık 100 mark karşılığında III. Alexander'a devretti; Orkney ve Shetland Norveç'te kaldı. Bu olayda ilgili yerleşimler: Castletown (Man), Iona (Hebridler), Peel (Man).","kaynak":"Encyclopedia.com (Oxford Companion), 'Perth, treaty of' — «On 2 July 1266 Magnus IV of Norway, Haakon's successor, signed the treaty of Perth with Alexander III of Scotland.»","sinif":"D"},{"t":"1268-10-29","devlet":"almanya","taraflar":["schwaben-dukaligi","almanya"],"b":"Son Hohenstaufen Conradin Napoli'de idam edildi; Schwaben Dukalığı'nın Hohenstaufen hanedanı sona erdi (Hohenstaufen Kalesi/Schwaben'in Almanya'ya devri)","tur":"son","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","schwaben-dukaligi","almanya"],"yer_id":"Hohenstaufen Kalesi (Göppingen, Schwaben)","gun":"29 Ekim 1268","d":"Tagliacozzo yenilgisinden (23 Ağustos 1268) sonra yakalanan Conradin, Anjou'lu Charles'ın isteğiyle Napoli'de idam edildi; Hohenstaufen erkek soyu tükendi. Dukalığın akıbeti kaynaklarda açık değil; Almanya'ya (krallık/imparatorluk topraklarına) geçiş çıkarımdır. Bu olayda ilgili yerleşimler: Hohenstaufen Kalesi (Göppingen, Schwaben).","kaynak":"Schaff, History of the Christian Church V https://ccel.org/ccel/schaff/hcc5.ii.viii.iv.html ; https://www.executedtoday.com/tag/conradin/","sinif":"D"},{"t":"1283-10-03","devlet":"ingiltere","taraflar":["gwynedd","ingiltere"],"b":"Gwynedd'in son hükümdarı Dafydd ap Gruffydd Shrewsbury'de idam edildi; Gwynedd (Aberffraw, Garth Celyn) İngiltere Kralı I. Edward'a geçti","tur":"toprak-kayip","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","gwynedd","ingiltere"],"yer_id":"Aberffraw","gun":"3 Ekim 1283","d":"Castell y Bere'nin 25 Nisan 1283'te düşmesi ve Haziran 1283'te Dafydd'in yakalanmasının ardından Dafydd, 29 Eylül 1283 sonrası toplanan Shrewsbury Parlamentosu'nda yargılanıp 3 Ekim 1283'te idam edildi; bağımsız Gwynedd sona erdi. Toprakları 3 Mart 1284 tarihli Rhuddlan Statüsü ile Anglesey, Caernarfon, Merioneth ve Flint şerifliklerine bölünerek İngiliz yönetimine bağlandı. Bu olayda ilgili yerleşimler: Aberffraw, Garth Celyn (Abergwyngregyn).","kaynak":"Dictionary of Welsh Biography, 'Dafydd ap Gruffydd (died 1283), prince of Gwynedd' (biography.wales/article/s-DAFY-APG-1283.html) — «3 October 1283, David III, on account of his broken allegiance to England's king, suffered a traitor's death.»","sinif":"D"},{"t":"1292-01-01","devlet":"lan-na","taraflar":["hariphunchai","lan-na"],"b":"Mangrai Hariphunchai'yi (Lamphun) fethedip Lan Na'ya kattı","tur":"toprak-kazanc","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","hariphunchai","lan-na"],"yer_id":"Lamphun (Haripuñjaya)","gun":"1292 (gün bilinmiyor; kaynaklarda 1281/1291/1292 farkı var)","d":"Kral Mangrai, Haripuñjaya'ya ajan Ai Fa'yı sokarak devleti içten çürüttü ve şehri aldı; son hükümdar Yi Ba güneye, Lampang'a kaçtı. Şehir Lan Na'ya katıldı, Mangrai 1296'da Chiang Mai'yi kurdu. Çoğu anlatı 1292 verir, bazıları 1291 ya da 1281. Bu olayda ilgili yerleşimler: Lamphun (Haripuñjaya).","kaynak":"https://en.wikipedia.org/wiki/Haripu%C3%B1jaya ve https://en.wikipedia.org/wiki/Mangrai (tek dayanak değil); akademik karşılık: D. K. Wyatt, Thailand: A Short History (Yale UP, 2003) - bu oturumda metni açılıp doğrulanmadı, Britannica 403 verdi","sinif":"D"},{"t":"1333-07-04","devlet":"kenmu","taraflar":["kamakura","kenmu"],"b":"Kamakura kuşatması sona erdi: Nitta Yoshisada Kamakura'yı aldı, Hojo Takatoki intihar etti, Kamakura bakufu yıkılıp yerini Kenmu yönetimine bıraktı","tur":"son","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","kamakura","kenmu"],"yer_id":"Kamakura","gun":"4 Temmuz 1333","d":"30 Haziran-4 Temmuz 1333 Kamakura kuşatmasında Nitta Yoshisada Tōshō-ji'de sığınan Hojo ailesini yendi; son naip Takatoki ve yakınları intihar etti, Kamakura bakufu sona erdi. Genkō Savaşı'nın son büyük muharebesiydi; ülke Go-Daigo'nun Kenmu Restorasyonu'na geçti. Bu olayda ilgili yerleşimler: Aizu-Wakamatsu, Funai (Ōita), Gifu, Hakata (Fukuoka), Himeji, Kagoşima, Kamakura, Kumamoto, Kyoto, Nara, Niigata, Odawara, Okayama, Osaka, Sakai, Sunpu (Şizuoka), Tsuşima (İzuhara).","kaynak":"https://www.historyofwar.org/articles/siege_kamakura.html (Siege of Kamakura, 30 June-4 July 1333); Hōkai-ji / Tōshō-ji kayıtları","sinif":"D"},{"t":"1336-12-10","devlet":"muromachi","taraflar":["kenmu","muromachi"],"b":"Ashikaga Takauji'nin Kenmu Shikimoku'yu ilanıyla Muromachi bakufu fiilen kuruldu; Kenmu yönetimi sona erdi","tur":"kurulus","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","kenmu","muromachi"],"yer_id":"Kyoto","gun":"Kenmu 3. yıl 11. ay 7. gün (ay takvimi) = Aralık 1336 başı (Jülyen 10 Aralık 1336)","d":"Takauji, Kyoto'da Go-Daigo güçlerini yendikten sonra 17 maddelik Kenmu Shikimoku ile yeni askerî yönetimin ilkelerini bildirdi; Muromachi bakufunun fiilî kuruluşu bu tarih sayılır, resmî şogunluk unvanı 1338'dedir. Atlasın 7 Kasım tarihi ay takvimindeki '11. ay 7. gün'ün Miladî sanılmasından doğmuş görünüyor. Bu olayda ilgili yerleşimler: Aizu-Wakamatsu, Funai (Ōita), Gifu, Hakata (Fukuoka), Himeji, Kagoşima, Kamakura, Kumamoto, Kyoto, Nara, Niigata, Odawara, Okayama, Osaka, Sakai, Sunpu (Şizuoka), Tsuşima (İzuhara).","kaynak":"Nihon Daihyakka Zensho / Kotobank 'Kenmu Shikimoku' (kotobank.jp/word/建武式目); NDL Search kaydı","sinif":"D"},{"t":"1338-01-01","devlet":"bengal-sultanligi","taraflar":["delhi-sultanligi","bengal-sultanligi"],"b":"Delhi Sultanlığı'nın Bengal valisi komutanı Fahreddin Mübarek Şah Sonargaon'da bağımsızlık ilan etti; Bengal Sultanlığı doğdu (Somapura ve Nadia bölgeleri)","tur":"isyan","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","delhi-sultanligi","bengal-sultanligi"],"yer_id":"Nadia (Navadvipa/Nabadwip)","gun":"1338 (gün bilinmiyor)","d":"Sonargaon valisi Bahram Han'ın ölümünden sonra silahdarı Fahreddin Mübarek Şah 1338'de bağımsız sultan oldu; Lakhnauti (Gauda) ve Satgaon'da da Delhi'den kopuk sultanlar çıktı. Bengal'in bu ilk bağımsız sultanlığı Banglapedia'ya göre 1338'de başlar; Nadia/Paharpur'un hangi hanedanın elinde olduğu 1342 İlyas Şah birleşmesine kadar dağınık kalır. Bu olayda ilgili yerleşimler: Nadia (Navadvipa/Nabadwip), Somapura Mahavihara (Paharpur).","kaynak":"https://en.banglapedia.org/index.php/Fakhruddin_Mubarak_Shah ; https://en.banglapedia.org/index.php/Sonargaon","sinif":"D"},{"t":"1399-10-19","devlet":"ingiltere","taraflar":["iskocya","ingiltere"],"b":"Henry IV Man Adasi'ni Henry Percy'ye (Northumberland) lordluk olarak verdi (Peel, Castletown)","tur":"toprak-kazanc","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","iskocya","ingiltere"],"yer_id":"Peel (Man)","gun":"19 Ekim 1399","d":"Henry IV, 19 Ekim 1399'da Man Adasi'ni Ingiliz Tacina bagli bir lordluk olarak Henry Percy'ye verdi; tapu William le Scrope'un elinden alinan topraklar olarak anildi. Bu kaynaklarda Iskocya'dan Ingiltere'ye 1399'da bir devir yoktur: olay Ingiliz Tacinin ada uzerindeki tasarrufudur; zincirdeki iskocya->ingiltere devri bu kaynaklarla dogrulanamadi. Bu olayda ilgili yerleşimler: Castletown (Man), Peel (Man).","kaynak":"Calendar of the Patent Rolls preserved in the Public Record Office (The National Archives), Henry IV, vol. I: 1399-1401, London 1903, s. 27 ve aynı yılın asıl kaydı: 19 Ekim 1399, Westminster, Henry de Percy, earl of Northumberland'a 'island, castle, peel and lordship of Man' bağışı (https://archive.org/details/calendarpatentr16offigoog) ; Manx Society vol. 29 (https://isle-of-man.com/manxnotebook/manxsoc/msvol29/p025.htm); Manx Notebook, Percy lordlugu (https://www.isle-of-man.com/manxnotebook/people/lords/john1.htm); ikincil: https://en.wikipedia.org/wiki/Henry_Percy,_1st_Earl_of_Northumberland","sinif":"D"},{"t":"1433-04-12","devlet":"burgonya","taraflar":["hollanda-kontlugu","burgonya"],"b":"Lahey Antlasmasi: Jacoba Hollanda ve Zeeland haklarini Burgonya Dükü Philip'e birakti (Haarlem, Dordrecht)","tur":"antlasma","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","hollanda-kontlugu","burgonya"],"yer_id":"Haarlem","gun":"12 Nisan 1433","d":"Jacoba (Jacqueline) 1433 Nisan'inda Hollanda, Zeeland ve Hainaut uzerindeki haklarini Burgonya Dükü Philip'e birakti; Philip, 1432 evliliginin 1428 Delft Antlasmasi'ni ihlal ettigini one surmustu. Gun, Vikipedi'nin Lahey Antlasmasi maddesine gore 12 Nisan; Nisan ayi Universalis ve Deutsche Biographie ile uyumlu. Haarlem ve Dordrecht kaynaklarda ayri anilmiyor, Hollanda kontlugu topraklari butun olarak devredildi. Bu olayda ilgili yerleşimler: Dordrecht, Haarlem.","kaynak":"Neue Deutsche Biographie 10 (1974) ve Allgemeine Deutsche Biographie, 'Jakobäa von Bayern' (deutsche-biographie.de/sfz36913.html) — «ihre Länder bei Erhalt einer Rente abzutreten (12.4.1433)»","sinif":"D"},{"t":"1479-01-19","devlet":"ispanya","taraflar":["aragon","kastilya","ispanya"],"b":"II. Ferdinand'ın Aragon tahtına geçmesiyle Aragon (Vic/Osona) Kastilya ile kişisel birlikte birleşti","tur":"birlesme","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","aragon","kastilya","ispanya"],"yer_id":"Vic (Ausona / Osona)","gun":"19 Ocak 1479","d":"II. Juan'ın 19 Ocak 1479'da Barselona'da ölümüyle Ferdinand Aragon kralı oldu; Isabella ile iki taç aynı hükümdarlar altında birleşti. Krallıklar hukuken ayrı kaldı (Nueva Planta 1707-1716). Bu olayda ilgili yerleşimler: Vic (Ausona / Osona). Ek ilgili yerleşimler: Astorga (Asturica), Medînetüsselâm (Medinaceli), Mârida (Mérida), Zamora.","kaynak":"Britannica 1911, John II of Aragon (en.wikisource.org/wiki/1911_Encyclopædia_Britannica/John_II_of_Aragon); gün: DBE (Real Academia de la Historia), 'Juan II de Aragón y de Navarra': «Barcelona, 19.I.1479» (https://dbe.rah.es/biografias/10845/juan-ii-de-aragon-y-de-navarra); Gran Enciclopèdia Catalana, 'Joan II de Catalunya-Aragó' aynı","sinif":"D"},{"t":"1482-03-27","devlet":"habsburg-hollandasi","taraflar":["burgonya","habsburg-hollandasi"],"b":"Burgonya Düşesi Maria'nın ölümüyle Haarlem ve Dordrecht'in de içinde olduğu Hollanda Burgonya mirası oğlu Philip'e, vasi Maximilian yönetiminde Habsburglara geçti","tur":"siyaset","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","burgonya","habsburg-hollandasi"],"yer_id":"Haarlem","gun":"27 Mart 1482","d":"Maria 27 Mart 1482'de atından düşerek öldü; mirası oğlu Philip'e (Yakışıklı) kaldı, Maximilian vasi oldu. Burgonya Mirası Savaşı'nı 23 Aralık 1482 Arras Antlaşması sonlandırdı; Flandre Maximilian'da kaldı. Bu olayda ilgili yerleşimler: Dordrecht, Haarlem.","kaynak":"Neue Deutsche Biographie 16 (1990) ve ADB, 'Maria von Burgund' (deutsche-biographie.de/sfz58282.html) — «M. starb schon am 27. März 1482, erst 25 Jahre alt, in Brügge»","sinif":"D"},{"t":"1495-07-21","devlet":"wurttemberg","taraflar":["almanya","wurttemberg"],"b":"Worms Reichstag'ında Württemberg Kontluğu dükalığa yükseltildi; Eberhard ilk dük oldu (Hohenstaufen Kalesi çevresi Württemberg'e bağlı)","tur":"siyaset","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","almanya","wurttemberg"],"yer_id":"Hohenstaufen Kalesi (Göppingen, Schwaben)","gun":"21 Temmuz 1495","d":"Kral/İmparator I. Maximilian, Worms Reichstag'ında Württemberg Kontu Eberhard'ı (Sakallı) Württemberg Dükü ilan etti. Bu, Kutsal Roma-Germen İmparatorluğu içinde Württemberg'in dukalık statüsünü kuran belgedir; Hohenstaufen Kalesi'nin bulunduğu Göppingen çevresi bu devletin toprağındadır. Kale özelinde ayrı bir devir belgesi bulunamadı, madde dükalık ilanına dayanır. Bu olayda ilgili yerleşimler: Hohenstaufen Kalesi (Göppingen, Schwaben).","kaynak":"Neue Deutsche Biographie 4 (1959), 'Eberhard im Bart' (deutsche-biographie.de/sfz56796.html) — «während des Wormser Reichstags am 21.7.1495 zum Herzog von Württemberg»","sinif":"D"},{"t":"1498-01-01","devlet":"saksonya","taraflar":["frizya-ozgurlugu","saksonya","almanya"],"b":"I. Maximilian, Saksonya Dükü Albrecht'i Frizya'nın kalıtsal potestatı atadı (Stavoren dahil Frizya Özgürlüğü Saksonya'ya devredildi)","tur":"siyaset","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","frizya-ozgurlugu","saksonya","almanya"],"yer_id":"Stavoren (Starum)","gun":"1498 (gün bulunamadı)","d":"Maximilian, Hollanda'daki hizmetlerinin bedeli olarak Saksonlu Albrecht'i 1498'de Frizya'nın kalıtsal valisi (potestat) atadı; Albrecht bölgeyi silahla boyun eğdirmek zorundaydı. Stavoren'e özgü ayrı bir belge bulunamadı; devir Frizya genelindeki bu atamaya dayanır. Gün kaynaklarda verilmediğinden 01-01 yazıldı. Bu olayda ilgili yerleşimler: Stavoren (Starum).","kaynak":"Albert III, Duke of Saxony; Lordship of Frisia; Potestaat of Friesland (Vikipedi, yalnız destek; birincil/akademik kaynak yeniden doğrulanmalı)","sinif":"D"},{"t":"1515-01-01","devlet":"habsburg-hollandasi","taraflar":["saksonya","habsburg-hollandasi"],"b":"Saksonlu Georg Frizya haklarını Habsburg Burgundy'li Charles'a (V. Karl) sattı; Stavoren Habsburg Hollandası'na geçti","tur":"toprak-kayip","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","saksonya","habsburg-hollandasi"],"yer_id":"Stavoren (Starum)","gun":"Mayıs 1515 (gün bulunamadı)","d":"Savaşın yükü altında yalnız birkaç kent elinde kalan Saksonya Dükü Georg, Frizya üzerindeki haklarını 1515'te (kaynaklara göre Mayıs) torunu Maximilian'ın varisi Charles'a yaklaşık 100.000 florine devretti. Gün bilinmediğinden 01-01 yazıldı. Bu olayda ilgili yerleşimler: Stavoren (Starum).","kaynak":"Lordship of Frisia; Guelders Wars; George, Duke of Saxony (Vikipedi, yalnız destek; birincil/akademik kaynak yeniden doğrulanmalı)","sinif":"D"},{"t":"1558-04-02","devlet":"toungoo","taraflar":["lan-na","toungoo"],"b":"Bayinnaung Chiang Mai'yi aldi; Mekuti teslim oldu, Lan Na (Lamphun dahil) Toungoo'ya vasal oldu","tur":"toprak-kayip","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","lan-na","toungoo"],"yer_id":"Lamphun (Haripuñjaya)","gun":"2 Nisan 1558","d":"Bayinnaung'un casusu Chiang Mai'nin zayif oldugunu bildirince Toungoo ordusu kenti yaklasik uc gunde, az direnisle aldi. Kral Mekuti 2 Nisan 1558'de teslim oldu ve vasal olarak yerinde birakildi (1564'te azledildi). Lamphun'un ayrica anildigi kaynak bulunamadi; Lan Na'nin butunu etkilendi. Bu olayda ilgili yerleşimler: Lamphun (Haripuñjaya).","kaynak":"https://en.wikipedia.org/wiki/Mangrai_dynasty ; https://www.ebsco.com/research-starters/history/burmese-laotian-wars/ ; Wikipedia Mekuti (2 Nisan tarihi tek kaynakta; Setthathirath maddesi istila yilini 1556 verir)","sinif":"D"},{"t":"1573-01-01","devlet":"azuchi-momoyama","taraflar":["muromachi","azuchi-momoyama"],"b":"Nobunaga, Makishima'da Ashikaga Yoshiaki'yi surgun ederek Muromachi bakufusunu fiilen sona erdirdi (Azuchi-Momoyama donemi baslangici)","tur":"son","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","muromachi","azuchi-momoyama"],"yer_id":"Kyoto","gun":"1573","d":"1573'te Oda Nobunaga, Makishima Kalesi'ndeki son Ashikaga shogunu Yoshiaki'yi yenip Kyoto disina surdu; gelenege gore Muromachi bakufusunun sonudur, Yoshiaki unvanindan resmen vazgecmedi. Bu olayda ilgili yerleşimler: Kyoto.","kaynak":"TDV İslâm Ansiklopedisi, 'Japonya' — «1573’te Muramachi devri kapandı ve yerine Azuchi-Momoyama dönemi (1573-1603) başladı.»","sinif":"D"},{"t":"1576-07-12","devlet":"babur-imparatorlugu","taraflar":["bengal-sultanligi","babur-imparatorlugu"],"b":"Rajmahal Savasi: Babur Imparatorlugu (Akbar) Karrani Bengal Sultanligi'ni yendi; Nadia ve Paharpur bolgesi Mugal yonetimine gecti","tur":"toprak-kazanc","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","bengal-sultanligi","babur-imparatorlugu"],"yer_id":"Nadia (Navadvipa/Nabadwip)","gun":"12 Temmuz 1576","d":"Han Cihan (Husain Quli Beg) komutasindaki Mugal ordusu Rajmahal'da Davud Han Karrani'yi yendi; Davud yakalanip idam edildi ve Bengal'deki bagimsiz Muslüman saltanat sona erdi. Eyaletin Mugal imparatorluguna tam katilimi sonraki yillarda tamamlandi. Bu olayda ilgili yerleşimler: Nadia (Navadvipa/Nabadwip), Somapura Mahavihara (Paharpur).","kaynak":"Banglapedia (Asiatic Society of Bangladesh), 'Rajmahal, The Battle of' (en.banglapedia.org/index.php/Rajmahal,_The_battle_of) — «The reinforced Mughals encountered the Afghans at Rajmahal on 12 July 1576 (15 Rabi II 984 AH).»","sinif":"D"},{"t":"1581-07-26","devlet":"hollanda","taraflar":["habsburg-hollandasi","hollanda","ispanya"],"b":"Vazgeçme Belgesi: Haarlem, Dordrecht, Stavoren ve Arnhem'in içinde bulunduğu Birleşik Eyaletler II. Felipe'nin hükümdarlığını reddetti","tur":"bolunme","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","habsburg-hollandasi","hollanda","ispanya"],"yer_id":"Haarlem","gun":"26 Temmuz 1581","d":"Generalstaaten, Utrecht Birliği'ne katılan eyaletlerin II. Felipe'ye bağlılık yeminini kaldıran Vazgeçme Belgesi'ni (Plakkaat van Verlatinghe) 26 Temmuz 1581'de ilan etti. Böylece Holland, Zeeland, Utrecht ve Gelderland'ın kuzey bölümleri Habsburg yönetiminden çıktı. Bu olayda ilgili yerleşimler: Arnhem, Dordrecht, Haarlem, Stavoren (Starum).","kaynak":"Tweede Kamer (Hollanda Temsilciler Meclisi), «Act of Abjuration» https://www.houseofrepresentatives.nl/node/297 — «By adopting the Act of Abjuration, on 26 July 1581»","sinif":"D"},{"t":"1603-03-24","devlet":"edo-bakufu","taraflar":["azuchi-momoyama","edo-bakufu"],"b":"Tokugawa Ieyasu şogun ilan edildi, Edo Bakufu kuruldu (Azuchi-Momoyama düzeninin sonu)","tur":"kurulus","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","azuchi-momoyama","edo-bakufu"],"yer_id":"Edo (Tokyo)","gun":"24 Mart 1603 (Keichō 8, 2. ay 12. gün)","d":"İmparator Go-Yōzei, Tokugawa Ieyasu'ya Keichō 8'in 2. ayının 12. gününde Seii Taishōgun unvanını verdi; bu tarih Gregoryen takvimde 24 Mart 1603'e denk gelir. Edo Bakufu böylece kuruldu. Arama kaynakları yalnız Japon takvim gününü (2/12) verdi, Gregoryen çevrim hesapla yapıldı. Bu olayda ilgili yerleşimler: Aizu-Wakamatsu, Edo (Tokyo), Fukui, Funai (Ōita), Gifu, Hakata (Fukuoka), Hakodate, Himeji, Hiroşima, Kagoşima, Kamakura, Kanazawa, Kumamoto, Kyoto, Kōchi, Matsumae, Matsuyama, Morioka, Nagazaki, Nara, Niigata, Odawara, Okayama, Sakai, Sendai, Sunpu (Şizuoka), Tsuşima (İzuhara), Yamaguchi.","kaynak":"TDV 'Japonya' yıl teyidi — «Minamoto’nun Tokugava soyundan gelen Ieyashu 1603’te şogun tayin edildi ve Yedo’da (Tokyo) Togukava hükümetini kurdu.»","sinif":"D"},{"t":"1607-07-18","devlet":"fransa","taraflar":["foix-kontlugu","fransa"],"b":"IV. Henri'nin fermanıyla Foix Kontluğu ve Tarascon-sur-Ariège dahil kişisel mülkleri Fransa tacına bağlandı","tur":"birlesme","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","foix-kontlugu","fransa"],"yer_id":"Foix","gun":"18 Temmuz 1607 (Temmuz 1607 fermanı)","d":"IV. Henri Temmuz 1607 tarihli fermanla Béarn, Aşağı Navarra, Foix kontluğu, Albret ve diğer şahsi mülklerini kraliyet domaine'ine kattı. Gün yalnız ikincil kaynakta (18 Temmuz) geçer; fermanın metni teyit edilmedi. Bu olayda ilgili yerleşimler: Foix, Tarascon-sur-Ariège.","kaynak":"https://franco.wiki/fr/1607_en_France.html ; https://areq.net/lang/fr/Comt%C3%A9_de_Foix.html","sinif":"D"},{"t":"1642-01-01","devlet":"tibet-ganden-phodrang","taraflar":["tibet","tibet-ganden-phodrang"],"b":"Tsang krallığının Güşi Han'ın Hoşut Moğolları eliyle yıkılması ve Lhasa merkezli Ganden Phodrang yönetiminin kurulması; Sakya Manastırı çevresi yeni yönetime bağlandı","tur":"siyaset","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","tibet","tibet-ganden-phodrang"],"yer_id":"Sakya Manastırı (Sakya)","gun":"1642 (gün bilinmiyor)","d":"1642'de Güşi Han Tsang hükümdarını yenip Tibet'in on üç myriarşisini 5. Dalay Lama'ya sundu; Lhasa merkezli Ganden Phodrang hükümeti böylece kuruldu. Sakya okulu Tsang-Ü çekişmesinin dışında kalmıştı ve Tsang'ın yenilgisinden sonra bu yeni yönetim çatısı altında kaldı. Kaynaklar yalnız yılı verir; tören günü (13 Nisan 1642 anılır) zayıf dayanaklıdır, bu yüzden YYYY-01-01 yazıldı. Bu olayda ilgili yerleşimler: Sakya Manastırı (Sakya).","kaynak":"The Treasury of Lives, 17th Century historical period, https://treasuryoflives.org/historical-period/17th-Century ; Sakya History, University of Virginia Tibetan Mandala, https://texts.mandala.library.virginia.edu/node/48081","sinif":"D"},{"t":"1642-08-26","devlet":"hollanda-formosa","taraflar":["ispanyol-formosa","hollanda-formosa"],"b":"Hollanda, Keelung'daki İspanyol San Salvador Kalesi'ni ele geçirdi; İspanyol Formosa sona erdi","tur":"toprak-kayip","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","ispanyol-formosa","hollanda-formosa"],"yer_id":"San Salvador Kalesi, Heping Adasi (Keelung)","gun":"26 Ağustos 1642","d":"Hollanda Doğu Hindistan Şirketi kuvvetleri 19-26 Ağustos 1642 arasında Keelung'daki San Salvador Kalesi'ni kuşattı; İspanyol garnizonu 26 Ağustos'ta teslim oldu. Böylece Hollandalılar adanın tamamına egemen oldu ve kale Fort Noord Holland adıyla yeniden inşa edildi. Bu olayda ilgili yerleşimler: San Salvador Kalesi, Heping Adasi (Keelung).","kaynak":"Taipei Times, Aug. 21 to Aug. 27, https://taipeitimes.com/News/feat/archives/2017/08/20/2003676833 ; Archaeology magazine, https://archaeology.org/?p=8292","sinif":"D"},{"t":"1662-02-01","devlet":"tungning","taraflar":["hollanda-formosa","tungning"],"b":"Zeelandia Kalesi'nde Hollanda valisi Coyett, Koxinga'ya teslim oldu; Hollanda Formosa'sı Tungning'e geçti","tur":"antlasma","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","hollanda-formosa","tungning"],"yer_id":"Zeelandia Kalesi (Anping, Tainan)","gun":"1 Şubat 1662","d":"Zeelandia Kalesi 12 Ocak 1662'de yeniden bombalandı; erzak tükenip takviye gelmeyince Coyett teslim şartlarını görüştü ve teslim 1 Şubat 1662'de tamamlandı. Hollandalılar kişisel eşyalarıyla ayrılabildi, Şirket malı kaldı; son personel 17 Şubat'ta adadan ayrıldı. Keelung bölümü için bkz. zincir_t_hatasi. Bu olayda ilgili yerleşimler: San Salvador Kalesi, Heping Adasi (Keelung), Zeelandia Kalesi (Anping, Tainan).","kaynak":"Jeremiah Jenne, February 1, 1662: Koxinga takes Taiwan, https://jeremiahjenne.com/the-archives/2018/1/31/february-1-1662-koxinga-takes-taiwan ; Siege of Fort Zeelandia (Wikipedia, ikincil)","sinif":"D"},{"t":"1683-10-03","devlet":"qing-hanedani","taraflar":["tungning","qing-hanedani"],"b":"Shi Lang Tayvan'a ulaşıp Zheng Keshuang ve Liu Guoxuan'ın teslimini aldı; Tungning Çing'e geçti","tur":"toprak-kazanc","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","tungning","qing-hanedani"],"yer_id":"Zeelandia Kalesi (Anping, Tainan)","gun":"3 Ekim 1683","d":"Shi Lang'ın filosu Temmuz 1683'te Penghu'da Tungning donanmasını yendi; 5 Eylül'de Zheng Keshuang'ın teslim teklifi alındı, 3 Ekim 1683'te Shi Lang Tayvan'a varıp Liu Guoxuan ve Zheng Keshuang'ın teslimini resmen aldı. Adanın Fujian eyaletine üç ilçeli prefektörlük olarak bağlanması 1684'te oldu. Zincirdeki 5 Ekim, 3 Ekim'e 2 gün uzaktır. Bu olayda ilgili yerleşimler: San Salvador Kalesi, Heping Adasi (Keelung), Zeelandia Kalesi (Anping, Tainan).","kaynak":"Taiwan under Qing rule (Wikipedia, ikincil), https://en.wikipedia.org/wiki/Taiwan_under_Qing_rule ; EBSCO Research Starters, Zheng pirates, https://www.ebsco.com/research-starters/history/zheng-pirates/","sinif":"D"},{"t":"1694-02-06","devlet":"portekiz-brezilyasi","taraflar":["palmares","portekiz-brezilyasi"],"b":"Portekiz kuvvetleri Palmares'in merkezi Cerca do Macaco'yu yıktı; Palmares krallığı sona erdi","tur":"toprak-kazanc","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","palmares","portekiz-brezilyasi"],"yer_id":"Serra da Barriga (Cerca do Macaco, Palmares)","gun":"6 Şubat 1694","d":"Domingos Jorge Velho ve Bernardo Vieira de Melo komutasındaki topçulu ve yerli destekli Portekiz-Brezilya seferi, 42 günlük kuşatmanın ardından 6 Şubat 1694'te Palmares'in merkezi Cerca do Macaco'yu yok etti. Zumbi kaçıp direndi ve 20 Kasım 1695'te öldürüldü. Cerca do Macaco maddesi Ocak 1694 diyen farklı bir anlatım içerir; 6 Şubat daha yaygındır. Bu olayda ilgili yerleşimler: Serra da Barriga (Cerca do Macaco, Palmares).","kaynak":"Fundação Cultural Palmares (gov.br/palmares/pt-br/assuntos/noticias/324-anos-da-queda-do-mocambo-dos-macacos-2013-serra-da-barriga) — «Em fevereiro de 1694, o mocambo dos Macacos foi atacado pelo bandeirante Domingos Jorge Velho»","sinif":"D"},{"t":"1707-05-12","devlet":"ingiltere","taraflar":["iskocya","ingiltere"],"b":"Birlesme Yasalari yururluge girdi: Iskocya Krallign Ingiltere ile birlesip Buyuk Britanya Krallign'ni kurdu (Dumbarton, Iona dahil butun Iskocya)","tur":"birlesme","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","iskocya","ingiltere"],"yer_id":"Iona (Hebridler)","gun":"GREGORYEN 12 Mayıs 1707 (CLAUDE.md Takvim, Emre 4 Kasım 2026; UMIT EK-julyen-oneri) — kaynak günü 1 Mayıs 1707 Jülyen/eski üslup · eski not: 1 Mayis 1707","d":"Ingiltere (1706) ve Iskocya (1707) parlamentolarinin Birlesme Yasalari 1 Mayis 1707'de yururluge girdi; iki krallik tek Buyuk Britanya Krallign'nda birlesti, iki parlamento Westminster'daki tek parlamentoyla degisti. Boylece Iskocya'nin butun topraklari (Dumbarton, Iona vb.) ortak devletin parcasi oldu. Bu olayda ilgili yerleşimler: Dumbarton (Alt Clut), Iona (Hebridler).","kaynak":"Britannica, Act of Union (https://www.britannica.com/print/article/614670); Acts of Union 1707, Wikipedia (yardimci)","sinif":"D"},{"t":"1713-04-11","devlet":"fransa","taraflar":["orange-prensligi","fransa"],"b":"Utrecht'te Prusya Fransa'ya Orange Prensligi'ni (Orange) birakti","tur":"antlasma","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","orange-prensligi","fransa"],"yer_id":"Orange (Arausio)","gun":"11 Nisan 1713","d":"Utrecht baris antlasmalari dizisinde Fransa-Prusya antlasmasi (Fransa-Britanya ile ayni 11 Nisan 1713 gunu) uyarinca Prusya Krali Orange Prensligi'ndeki haklarindan vazgecti, prenslik Fransa'ya katildi; Prusya prens unvanini korudu, karsiliginda Neuchatel ve Guney Gelderland'i aldi. Nassau varisleri bunu tanimadi (1732 Taksim Antlasmasi). Bu olayda ilgili yerleşimler: Orange (Arausio).","kaynak":"Encyclopedia.com, «Utrecht, Peace of (1713)» https://www.encyclopedia.com:443/history/modern-europe/treaties-and-alliances/peace-utrecht — «on 11 April signed treaties ending their participation in the war.»","sinif":"D"},{"t":"1717-01-01","devlet":"bengal-nevabligi","taraflar":["babur-imparatorlugu","bengal-nevabligi"],"b":"Babur Imparatoru Ferruhsiyer Murshid Quli Han'i Bengal subadari yapti; Bengal fiilen ozerk Nevablik oldu (Paharpur, Nadia)","tur":"siyaset","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","babur-imparatorlugu","bengal-nevabligi"],"yer_id":"Nadia (Navadvipa/Nabadwip)","gun":"1717 (ay-gun bilinmiyor; kaynaklarda Agustos/Eylul 1717)","d":"Murshid Quli Han 1717'de Bengal subadarligina yukseltildi; boylece Bengal'de, Delhi'ye haraci sunan fiilen ozerk Nevablik donemi basladi. Yil kaynaklarda tutarli, ay-gun anlasmazdir (Agustos/Eylul); gun yazilmadi. Bu olayda ilgili yerleşimler: Nadia (Navadvipa/Nabadwip), Somapura Mahavihara (Paharpur).","kaynak":"Banglapedia, 'Subahdar' (en.banglapedia.org/index.php/Subahdar) — «During the period, virtual ruler of the subah was Murshid Quli Khan, the founder of the nawabi regime.»","sinif":"D"},{"t":"1723-01-01","devlet":"asanti","taraflar":["bono-manso","asanti"],"b":"Asante Imparatorlugu Opoku Ware onderliginde Bono-Manso'yu (Techiman kuzeyi) fethetti","tur":"toprak-kayip","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","bono-manso","asanti"],"yer_id":"Bono-Manso (Techiman kuzeyi)","gun":"1722-1723 (gun bilinmiyor)","d":"Asante Asantehene Opoku Ware, Bono Devleti'nin baskenti Bono-Manso'yu 1722-1723'te ele gecirdi; Kitab Ghunja ve 1724 tarihli Hollanda Bati Hindistan Kumpanyasi mektubu bu fethi dogrular. Baskent Techiman'a tasindi, Bono Asante egemenligine girdi. Bu olayda ilgili yerleşimler: Bono-Manso (Techiman kuzeyi).","kaynak":"UNESCO, General History of Africa V: Africa from the Sixteenth to the Eighteenth Century, ed. B. A. Ogot, 1992 (PDF, sahistory.org.za/archive), Akan/Gold Coast bölümü, s.447 — ««The Asante then conquered Aowin (1715-21), Nzima (1715) ... and Wenchi (1711-14), Bono (1723-4), the Bron state (1731-40) and Gonja (1732) to the north-west.»»","sinif":"D"},{"t":"1757-06-23","devlet":"ingiliz-hindistani","taraflar":["bengal-nevabligi","ingiliz-hindistani"],"b":"Plassey Muharebesi: Bengal Nevabı Siraceddevle, Doğu Hindistan Şirketi'ne yenildi; Bengal (Nadia, Paharpur dahil) Şirket denetimine girdi","tur":"savas","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","bengal-nevabligi","ingiliz-hindistani"],"yer_id":"Nadia (Navadvipa/Nabadwip)","gun":"23 Haziran 1757","d":"Robert Clive komutasındaki Şirket kuvvetleri, Nevab Siraceddevle'yi Palashi (Plassey) yakınında yendi; Mir Cafer nevap yapıldı ve Bengal fiilen Şirket denetimine geçti. Nadia ve Paharpur gibi Bengal yerleşimleri bu devirle Nevablık'tan Şirket egemenliğine geçer. Bu olayda ilgili yerleşimler: Nadia (Navadvipa/Nabadwip), Somapura Mahavihara (Paharpur).","kaynak":"Banglapedia, 'Palashi, The Battle of' (en.banglapedia.org/index.php/Palashi,_The_Battle_of) — «Palashi, The Battle of was fought between Nawab sirajuddaula and the east india company on 23 June 1757.»","sinif":"D"},{"t":"1763-01-01","devlet":"konbaung","taraflar":["toungoo","konbaung"],"b":"Konbaung Birmanyası Lan Na'nın güneyini (Lamphun ve Chiang Mai) yeniden fethetti","tur":"toprak-kazanc","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","toungoo","konbaung"],"yer_id":"Lamphun (Haripuñjaya)","gun":"1763 (gün bilinmiyor)","d":"Alaungpaya 1757'de Chiang Mai'yi yeniden vasal yaptıysa da Lamphun, 1728/29 ayaklanmasından beri bağımsız 'Özgür Lan Na' tarafındaydı; Birman kuvvetleri Chiang Mai ve Lamphun'u ancak 1762-63 seferinde yeniden fethetti. 1752'de Konbaung Lamphun'u elinde tutmuyordu. Bu olayda ilgili yerleşimler: Lamphun (Haripuñjaya).","kaynak":"Volker Grabowsky, 'Forced Resettlement Campaigns in Northern Thailand', JSS 87 https://thesiamsociety.org/wp-content/uploads/1999/03/JSS_087_0g_Grabowsky_ForecedResettlementCampaignsInNThailand.pdf ; Kirigaya, JSS 102","sinif":"D"},{"t":"1765-05-10","devlet":"man-adasi","taraflar":["ingiltere","man-adasi"],"b":"Man Adası Satın Alma (Revestment) Yasası: Atholl Dükleri'nin Man Lordluğu egemenliği Britanya Tacı'na devredildi (Peel, Castletown)","tur":"antlasma","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","ingiltere","man-adasi"],"yer_id":"Castletown (Man)","gun":"10 Mayıs 1765","d":"Isle of Man Purchase (Revestment) Act 1765 (5 Geo. 3 c. 26) 10 Mayıs 1765'te kraliyet onayı aldı; Atholl Dükü'nün Man Lordluğu haklarını 70.000 sterline Taç'a devretti. Kraliyet bildirisi 21 Haziran 1765'te yayımlandı. Atholl ailesi malikâne hakları, piskoposluk atama hakkı, balıkçılık ve madenleri elinde tuttu. Not: zincirdeki yön (ingiltere->man-adasi) ters okunabilir; olay Man egemenliğinin Taç'a bağlanmasıdır. Bu olayda ilgili yerleşimler: Castletown (Man), Peel (Man).","kaynak":"https://en.wikipedia.org/wiki/Isle_of_Man_Purchase_Act_1765 ; https://isle-of-man.com/manxnotebook/history/revest.htm (Act of Revestment 1765) ; https://www.imuseum.im/?p=2590 (Atholl Papers: The Revestment)","sinif":"D"},{"t":"1775-01-14","devlet":"tonburi","taraflar":["konbaung","tonburi"],"b":"Taksin'in Siyam orduları Lamphun'da Birmanyalıları yendi, Chiang Mai'yi aldı; Lamphun (Haripuñjaya) Konbaung'dan Thonburi nüfuzuna geçti","tur":"savas","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","konbaung","tonburi"],"yer_id":"Lamphun (Haripuñjaya)","gun":"14 Ocak 1775","d":"Kral Taksin Aralık 1774'te kuzeye yürüdü; Chaophraya Chakri ve Surasi komutasındaki Siyam kuvvetleri Lamphun'daki Birmanya mevzilerini aştı ve 14 Ocak 1775'te Chiang Mai üzerine yürüyerek şehri Ocak 1775'te aldı. Chiang Mai'ye Phraya Wichianprakarn atandı (Siyam vasalı). Lamphun ayrıntısı yalnız Vikipedi'nin Penth'e dayanan anlatımında var; zayıf. Bu olayda ilgili yerleşimler: Lamphun (Haripuñjaya).","kaynak":"https://en.wikipedia.org/wiki/Siamese_conquest_of_Lan_Na_(1774%E2%80%931775) (Hans Penth, A Brief History of Lanna, 2001'e dayanır)","sinif":"D"},{"t":"1782-04-06","devlet":"siyam-chakri","taraflar":["tonburi","siyam-chakri"],"b":"Chaophraya Chakri Siyam tahtına çıktı (I. Rama): Thonburi devrilip Chakri hanedanı kuruldu; Lan Na/Lamphun üzerindeki Siyam üstünlüğü Chakri hanedanına geçti","tur":"siyaset","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","tonburi","siyam-chakri"],"yer_id":"Lamphun (Haripuñjaya)","gun":"6 Nisan 1782","d":"Taksin'in devrilmesinin ardından general Chaophraya Chakri (Maha Kasatsuek) 6 Nisan 1782'de kral ilan edildi ve Chakri hanedanını kurdu; resmî taç giyme 10 Haziran 1782'de oldu. Tayland'da 6 Nisan Chakri Anma Günü'dür. Lamphun'un adı kaynakta geçmez: devir, Siyam üstünlüğü altındaki Lan Na'nın hanedan değişimi olarak yazıldı. Bu olayda ilgili yerleşimler: Lamphun (Haripuñjaya).","kaynak":"https://en.wikipedia.org/wiki/Rama_I (6 Nisan 1782 saltanat başlangıcı; atıf zayıf)","sinif":"D"},{"t":"1792-09-21","devlet":"fransa-cumhuriyet","taraflar":["fransa","fransa-cumhuriyet"],"b":"Ulusal Konvansiyon krallığı kaldırdı, Fransa Cumhuriyeti kuruldu (Arles, Vienne, Saumur, Foix, Tarascon, Orange)","tur":"kurulus","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","fransa","fransa-cumhuriyet"],"yer_id":"Saumur","gun":"21 Eylül 1792","d":"Ulusal Konvansiyon ilk toplantısında monarşinin kaldırıldığını ilan etti; 22 Eylül 1792 Cumhuriyet'in I. yılının ilk günü sayıldı. Fransa'nın tüm toprakları (Güney Fransa şehirleri dahil) Birinci Cumhuriyet'e geçti. Bu olayda ilgili yerleşimler: Arles, Foix, Orange (Arausio), Saumur, Tarascon-sur-Ariège, Vienne (Isère).","kaynak":"Histoire parlementaire de la Révolution française (Buchez-Roux), «Procès-verbal de la proclamation de l'abolition de la royauté» (Wikisource aktarımı) https://fr.wikisource.org/wiki/Proc%C3%A8s-verbal_de_la_proclamation_de_l%E2%80%99abolition_de_la_royaut%C3%A9_%28dans_Histoire_parlementaire_de_la_R%C3%A9volution_fran%C3%A7aise%29 — «La Convention nationale décrète que la royauté est abolie en France.»","sinif":"D"},{"t":"1795-01-19","devlet":"batav-cumhuriyeti","taraflar":["hollanda","batav-cumhuriyeti","fransa-cumhuriyet"],"b":"Batav Cumhuriyeti ilan edildi, Hollanda Eyaletleri Cumhuriyeti sona erdi (Haarlem, Dordrecht)","tur":"kurulus","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","hollanda","batav-cumhuriyeti","fransa-cumhuriyet"],"yer_id":"Haarlem","gun":"19 Ocak 1795","d":"Fransız istilası üzerine Stadtholder V. Willem İngiltere'ye kaçtı; Fransız destekli Patriotlar 19 Ocak 1795'te Batav Cumhuriyeti'ni ilan etti. Haarlem/Dordrecht'e özgü kaynak bulunmadı, Hollanda eyaletleri geneli. Bu olayda ilgili yerleşimler: Dordrecht, Haarlem.","kaynak":"BMGN - Low Countries Historical Review, https://bmgn-lchr.nl/article/download/URN%3ANBN%3ANL%3AUI%3A10-1-104919/2709/2787 — «De Bataafse omwenteling van 19 januari 1795, die de ondergang van de oude Republiek der zeven verenigde provincies bezegelde»","sinif":"D"},{"t":"1799-04-21","devlet":"helvetik-cumhuriyeti","taraflar":["graubunden","helvetik-cumhuriyeti","fransa-cumhuriyet"],"b":"Graubünden (Rätien) Helvetik Cumhuriyeti'ne katıldı (Chur, Ilanz, Davos)","tur":"birlesme","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","graubunden","helvetik-cumhuriyeti","fransa-cumhuriyet"],"yer_id":"Chur (Coira)","gun":"21 Nisan 1799","d":"Graubünden, 1798 yazında reddettiği katılımı Fransız baskısıyla 21 Nisan 1799'da kabul ederek 'Rätien Kantonu' olarak Helvetik Cumhuriyeti'ne girdi; 1803 Arabuluculuk Yasası'na dek bağlı kaldı. Bu olayda ilgili yerleşimler: Chur (Coira), Davos, Ilanz.","kaynak":"https://hls-dhs-dss.ch/de/articles/009797/ ; https://www.gr.ch/DE/kanton/175-Jahre/Seiten/Epochen-in-Karten.aspx","sinif":"D"},{"t":"1803-02-19","devlet":"isvicre","taraflar":["helvetik-cumhuriyeti","isvicre"],"b":"Arabuluculuk Yasası ile Helvetik Cumhuriyeti kaldırıldı; Graubünden (Chur, Ilanz, Davos) eşit haklı kanton olarak İsviçre Konfederasyonu'na katıldı","tur":"birlesme","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","helvetik-cumhuriyeti","isvicre"],"yer_id":"Chur (Coira)","gun":"19 Şubat 1803","d":"Napolyon'un 19 Şubat 1803 tarihli Arabuluculuk Yasası 19 kanton kurdu; Graubünden, Aargau, Thurgau, Ticino, Vaud ve St. Gallen ile birlikte tam kanton oldu. Konfederasyon 10 Mart 1803'ten itibaren işlemeye başladı. Bu olayda ilgili yerleşimler: Chur (Coira), Davos, Ilanz. Bu yasayla Helvetik Cumhuriyeti sona erdi; Zürih, Bern, Luzern, Basel, Lozan (Vaud) ve Lugano, Bellinzona, Locarno (Tessin) 19 kantonlu İsviçre Konfederasyonu'nun parçası oldu.","kaynak":"Historisches Lexikon der Schweiz, Mediationsakte (hls-dhs-dss.ch/articles/009808); swissinfo.ch · Yer teyidi (DUNYA-1102 D(b), 3 Kasım 2026): Staatsarchiv des Kantons Zürich, 'Actum 1803' (zh.ch, staatsarchiv_zuerich_actum_1803.pdf, 2003)","sinif":"D"},{"t":"1803-02-25","devlet":"baden","taraflar":["pfalz","baden"],"b":"Reichsdeputationshauptschluss ile Pfalz Seçmenliği'nin Ren sağ yakası (Heidelberg, Mannheim) Baden'e verildi","tur":"toprak-kazanc","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","pfalz","baden"],"yer_id":"Heidelberg","gun":"25 Şubat 1803","d":"25 Şubat 1803 tarihli Reichsdeputationshauptschluss Kurpfalz'ı seçmenlik olarak sona erdirdi; sağ yaka toprakları Heidelberg ve Mannheim dahil Baden'e geçti. Karlsruhe yönetimi toprakları 1802/03 kışında fiilen almıştı. Bu olayda ilgili yerleşimler: Heidelberg, Mannheim.","kaynak":"Staatliche Schlösser und Gärten Baden-Württemberg, Schloss Mannheim: Vor 220 Jahren Frieden von Lunéville (schloesser-und-gaerten.de/fileadmin/Presse/pressemeldungen/26_mannheim/ssg_schloss-mannheim_pm_vor-220-jahren_frieden-von-luneville.pdf); BLB Karlsruhe, Hug Baden Grossherzogtum (regionalia.blb-karlsruhe.de/files/119/BLB_Hug_Baden_Grossherzogtum.pdf)","sinif":"D"},{"t":"1804-01-01","devlet":"haiti","taraflar":["saint-domingue","haiti"],"b":"Dessalines Gonaïves'te Haiti'nin bağımsızlığını ilan etti; Saint-Domingue (Cap-Français, Port-au-Prince dahil) Haiti oldu","tur":"kurulus","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","saint-domingue","haiti"],"yer_id":"Port-au-Prince","gun":"1 Ocak 1804","d":"Jean-Jacques Dessalines 1 Ocak 1804'te Gonaïves'te Bağımsızlık Bildirgesi'ni okuttu; eski Fransız Saint-Domingue Haiti adıyla bağımsız oldu. Cap-Français ve Port-au-Prince 1803'te Fransız birliklerinin çekilmesiyle ele geçirilmişti. Bu olayda ilgili yerleşimler: Cap-Français (Cap-Haïtien), Port-au-Prince.","kaynak":"Saylor Academy HIST 303, Haitian Act of Independence (resources.saylor.org/wwwresources/archived/site/wp-content/uploads/2011/08/HIST-303-4.4.6-Act-of-Independence.pdf); marxists.org Haiti 1804 belge arşivi","sinif":"D"},{"t":"1813-11-15","devlet":"hollanda","taraflar":["fransa-cumhuriyet","hollanda"],"b":"15 Kasım 1813 Hollanda ayaklanması: Amsterdam'ı izleyen Haarlem ve diğer Holland kentleri Fransız yönetimini attı; Haarlem ve Dordrecht Hollanda'ya döndü","tur":"isyan","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","fransa-cumhuriyet","hollanda"],"yer_id":"Haarlem","gun":"15 Kasım 1813","d":"Fransız garnizonunun Amsterdam'dan çekilmesinin ardından 15 Kasım 1813'te halk ayaklandı; London Gazette'e göre hareketi Haarlem, Leiden, Utrecht, Lahey, Rotterdam vb. izledi. Dordrecht için ayrı gün bulunamadı; Kasım-Aralık 1813 genel kurtuluşu içinde (zincirin 2 Aralık tarihi ±30 gün içinde). Bu olayda ilgili yerleşimler: Dordrecht, Haarlem.","kaynak":"https://www.thegazette.co.uk/London/issue/16812/page/2329/data.pdf ; https://koninkrijk1813.huygens.knaw.nl/?p=10186","sinif":"D"},{"t":"1813-11-30","devlet":"hollanda","taraflar":["fransa-cumhuriyet","hollanda","prusya"],"b":"Prens Willem Scheveningen'e çıktı, Arnhem muharebesiyle Fransız hâkimiyeti sona erdi; Arnhem ve Lahey bağımsız Hollanda'ya döndü","tur":"toprak-kazanc","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","fransa-cumhuriyet","hollanda","prusya"],"yer_id":"Lahey (Den Haag)","gun":"30 Kasım 1813","d":"30 Kasım 1813'te Prusya birlikleri Arnhem muharebesini kazandı ve aynı gün Orange Prensi Willem Scheveningen'de karaya çıktı. Lahey'de ise 20 Kasım 1813 üçlü yönetim (Triumvirate) bildirisiyle Hollanda'nın Fransız egemenliğinden kurtulduğu ilan edilmişti. Bu olayda ilgili yerleşimler: Arnhem, Lahey (Den Haag).","kaynak":"Huygens Instituut (KNAW), 'Koninkrijk in wording' İngilizce özeti (koninkrijk1813.huygens.knaw.nl) — «On 30 November 1813, the Prince landed at Scheveningen»","sinif":"D"},{"t":"1822-09-07","devlet":"brezilya-imparatorlugu","taraflar":["portekiz-brezilyasi","brezilya-imparatorlugu"],"b":"Dom Pedro Brezilya'nın Portekiz'den bağımsızlığını ilan etti (Ipiranga); São Miguel das Missões ve Serra da Barriga Brezilya İmparatorluğu'na bağlandı","tur":"kurulus","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","portekiz-brezilyasi","brezilya-imparatorlugu"],"yer_id":"Serra da Barriga (Cerca do Macaco, Palmares)","gun":"7 Eylül 1822","d":"Naip Dom Pedro 7 Eylül 1822'de Ipiranga'da Brezilya'nın Portekiz'den ayrıldığını ilan etti; 1 Aralık 1822'de imparator olarak taç giydi. Bağımsızlık günü olarak 7 Eylül geleneksel kabuldür; olayın ayrıntıları tarihçilerce tartışmalıdır. Bu olayda ilgili yerleşimler: Serra da Barriga (Cerca do Macaco, Palmares), São Miguel Arcanjo (São Miguel das Missões).","kaynak":"Infopedia, Grito do Ipiranga (https://www.infopedia.pt/artigos/$grito-do-ipiranga); Todamateria, Independência do Brasil","sinif":"D"},{"t":"1831-04-11","devlet":"uruguay-cumhuriyeti","taraflar":["charrua","uruguay-cumhuriyeti"],"b":"Uruguay ordusu Salsipuedes'te Charrúa'ları bozguna uğratarak Charrúa topraklarını Uruguay Cumhuriyeti denetimine bıraktı","tur":"toprak-kayip","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","charrua","uruguay-cumhuriyeti"],"yer_id":"Salsipuedes (Charrúa)","gun":"11 Nisan 1831","d":"Cumhurbaşkanı Fructuoso Rivera komutasındaki Uruguay ordusu 11 Nisan 1831'de Salsipuedes Deresi kıyısında Charrúa'lara saldırdı; resmî rapora göre 40 ölü, 300 esir verildi. Olay Charrúa'nın ayrı siyasi varlığını fiilen bitirdi. Bu olayda ilgili yerleşimler: Salsipuedes (Charrúa).","kaynak":"https://en.wikipedia.org/wiki/Massacre_of_Salsipuedes ; https://ojs.fhce.edu.uy/index.php/claves/article/view/2393/3367","sinif":"D"},{"t":"1853-12-11","devlet":"ingiliz-hindistani","taraflar":["nagpur-bhonsle","ingiliz-hindistani"],"b":"Nagpur Bhonsle Racası III. Raghuji'nin varissiz ölümüyle Nagpur Devleti (Chanda dahil) İngiliz Doğu Hindistan Şirketi'ne bağlandı","tur":"toprak-kazanc","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","nagpur-bhonsle","ingiliz-hindistani"],"yer_id":"Chanda (Chandrapur)","gun":"11 Aralık 1853","d":"III. Raghuji 11 Aralık 1853'te oğulsuz öldü; Dalhousie'nin 'lapse' (bağlama) doktrini uyarınca evlat edinme tanınmadı ve Nagpur toprakları Chanda bölgesiyle birlikte Britanya idaresine geçti, Nagpur Eyaleti olarak yönetildi. İdari düzenleme 1854'te sürdü (Chanda 1854'te ayrı ilçe oldu). Bu olayda ilgili yerleşimler: Chanda (Chandrapur).","kaynak":"Hunter, A Brief History of the Indian Peoples (Wikisource, sayfa 165) — «on the death of the last Raghují Bhonsla without a direct male heir, in 1853, the Nágpur Maráthá territories ... lapsed to the British»","sinif":"D"},{"t":"1860-09-03","devlet":"italya","taraflar":["papalik","italya","sardinya-piyemonte"],"b":"Papalığa bağlı Benevento enklavı Garibaldi'nin temsilcisiyle geçici hükümete geçti (sonradan Piyemonte/İtalya'ya katıldı)","tur":"toprak-kayip","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","papalik","italya","sardinya-piyemonte"],"yer_id":"Benevento","gun":"3 Eylül 1860","d":"Napoli Krallığı içindeki Papalık enklavı Benevento'da Garibaldi'nin delegesi Salvatore Rampone 3 Eylül 1860'ta geçici hükümeti ilan etti, papalık delegesi ertesi gün şehri terk etti; Garibaldi'nin 25 Ekim 1860 kararnamesiyle Benevento il merkezi oldu. Devir Mart 1861'de İtalya Krallığı'na girişten çok önce gerçekleşti. Kesin ilhak/plebisit günü bulunamadı. Bu olayda ilgili yerleşimler: Benevento.","kaynak":"Emilio Diena'ya atıfla Tesori di carta (http://tesoridicarta.blogspot.com/2019/07/lo-strano-caso-di-benevento-e-pontecorvo.html); Istoria della città di Benevento, Wikisource. Zayıf/ikincil kaynak, birincil belge doğrulanmalı","sinif":"D"},{"t":"1860-10-21","devlet":"sardinya-piyemonte","taraflar":["napoli","sardinya-piyemonte"],"b":"Napoli (İki Sicilya) kıta eyaletleri plebisitle Sardinya-Piyemonte'ye katılmayı kabul etti (Salerno, Melfi)","tur":"toprak-kazanc","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","napoli","sardinya-piyemonte"],"yer_id":"Salerno","gun":"21 Ekim 1860","d":"21 Ekim 1860 plebisitinde Napoli kıta eyaletleri 1.302.064 evet, 10.312 hayır oyuyla Vittorio Emanuele II'nin egemenliği altında birleşmeyi kabul etti (Salerno ve Melfi bu eyaletlerdedir). Sonuç 7 Kasım'da resmen kabul edildi, ilhak kararnamesi 17 Aralık 1860'ta çıktı. Bu olayda ilgili yerleşimler: Melfi, Salerno.","kaynak":"House Divided (Dickinson College) özeti, Wambaugh, A Monograph on Plebiscites (1920), s.641-645; Omniatlas 'Europe 1860: Fall of the Two Sicilies'","sinif":"D"},{"t":"1865-05-04","devlet":"abd","taraflar":["konfedere-devletler","abd"],"b":"Konfedere hükümet dağıldı: Jefferson Davis'in Washington (Georgia)'daki son kabine toplantısı; Richmond ve Montgomery'li Konfedere toprakları ABD'ye döndü","tur":"son","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","konfedere-devletler","abd"],"yer_id":"Richmond (Virjinya)","gun":"4-5 Mayıs 1865","d":"Richmond 3 Nisan 1865'te düştü, Lee 9 Nisan'da teslim oldu; Davis'in Washington (Georgia) kasabasındaki son kabine toplantısında Konfedere hükümet fiilen dağıtıldı (anıt levhası 4 Mayıs, bir kaynak 5 Mayıs der). Davis 10 Mayıs'ta yakalandı. Bu olayda ilgili yerleşimler: Cuscowilla (Micanopy yakını, Alachua Savanı), Montgomery, Richmond (Virjinya).","kaynak":"New Georgia Encyclopedia, Capture of Jefferson Davis (https://www.georgiaencyclopedia.org/articles/history-archaeology/capture-jefferson-davis); Read the Plaque, Bank of State of Georgia (https://readtheplaque.com/plaque/bank-of-state-of-georgia)","sinif":"D"},{"t":"1867-01-04","devlet":"rusya","taraflar":["megrelya-prensligi","rusya"],"b":"Megrelya (Odişi) Prensliği'ne Rusya son verdi, Prens I. Niko Dadiani tahttan çekilip Zugdidi ve Megrelya doğrudan Rusya'ya katıldı","tur":"son","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","megrelya-prensligi","rusya"],"yer_id":"Zugdidi (Megrelya/Odişi merkezi)","gun":"4 Ocak 1867","d":"Megrelya 1803'ten beri Rusya himayesindeydi; 1857'de Rus geçici idaresi altına girdi (Kırım Savaşı sonrası), ancak prenslik 1867'de Niko I Dadiani'nin tahttan feragati ve Rusya'nın ilhakıyla kaldırıldı; Niko'ya Rus İmparatorluğu prensi unvanı verildi. Sonraki yıl (1868) haklarından resmen vazgeçti. Gün kaynaklarda 4 Ocak 1867 olarak veriliyor; kesin gün için ek birincil kaynak gerekir. Bu olayda ilgili yerleşimler: Zugdidi (Megrelya/Odişi merkezi).","kaynak":"Wikipedia 'Principality of Mingrelia' ve 'Niko I Dadiani'; Royal Ark, https://www.royalark.net/Georgia/mingrel7.htm (iki kaynaklı, akademik teyit eksik)","sinif":"D"},{"t":"1868-01-03","devlet":"meiji-japonya","taraflar":["edo-bakufu","meiji-japonya"],"b":"Meiji Restorasyonu: Edo bakufu'nun yerine imparatorluk yönetimi ilan edildi","tur":"siyaset","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","edo-bakufu","meiji-japonya"],"yer_id":"Kyoto","gun":"3 Ocak 1868","d":"Kyoto sarayında ilan edilen 'imparatorluk yönetiminin restorasyonu' fermanıyla Tokugawa şogunluğu (Edo bakufu) kaldırıldı ve siyasi otorite Meiji İmparatoru'na geçti. Bu olayda ilgili yerleşimler: Aizu-Wakamatsu, Edo (Tokyo), Etorofu (Shana / Kurilsk), Fukui, Funai (Ōita), Gifu, Hakata (Fukuoka), Hakodate, Himeji, Hirosaki, Hiroşima, Kagoşima, Kamakura, Kanazawa, Kumamoto, Kunashiri (Furukamappu / Yuzhno-Kurilsk), Kyoto, Kōchi, Matsue, Matsumae, Matsuyama, Morioka, Nagazaki, Nagoya, Nara, Niigata, Odawara, Okayama, Osaka, Sakai, Sendai, Sunpu (Şizuoka), Tsuşima (İzuhara), Yamaguchi.","kaynak":"Nihon Daihyakka Zensho (Nipponica), kotobank.jp/word/明治維新-156395 — «1867年12月9日に王政復古の宮中クーデターが行われ、幕府は廃止され、天皇政権が樹立されたのである。» · Yer teyidi (DUNYA-1102 D(b), 3 Kasım 2026): Nihon Daihyakka Zensho (Nipponica), '明治維新' (kotobank.jp/word/明治維新-156395) ; kotobank '戊辰戦争' (https://kotobank.jp/word/戊辰戦争-133002): Kaitei Shinpan Sekai Daihyakka Jiten; Seisen-ban Nihon Kokugo Daijiten","sinif":"D"},{"t":"1879-04-04","devlet":"arjantin-cumhuriyeti","taraflar":["ranquel","arjantin-cumhuriyeti"],"b":"Racedo'nun 3. Seferi Birliği Sarmiento'dan Ranquel ülkesine yürüdü: Leubucó işgali, Ranquel egemenliğinin sonu","tur":"isgal","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","ranquel","arjantin-cumhuriyeti"],"yer_id":"Leubucó (Leuvucó, La Pampa)","gun":"4 Nisan 1879","d":"Albay Eduardo Racedo komutasındaki 3. Seferi Birlik 1879 Nisan'ında Fuerte Sarmiento'dan Ranquel topraklarına (Mariano Rosas, Epumer, Baigorrita yurtları, Leubucó) girdi; Nisan-Ağustos 1879'da esirler Pitral Lauquen kampında toplandı. Kesin tek bir teslim günü bulunamadı; seferin başlangıç günü esas alındı. Bu olayda ilgili yerleşimler: Leubucó (Leuvucó, La Pampa).","kaynak":"Zeballos, La guerra al malón, Böl. 17 (es.wikisource.org); Pérez Zavala, 'El campamento Pitral Lauquen: ranqueles prisioneros de la 3a División Expedicionaria (1879)', CLACSO","sinif":"D"},{"t":"1895-04-17","devlet":"japon-tayvani","taraflar":["qing-hanedani","japon-tayvani"],"b":"Şimonoseki Antlaşması ile Qing Hanedanı Tayvan'ı ve Penghu'yu Japonya'ya devretti (Zeelandia ve San Salvador kaleleri dahil)","tur":"antlasma","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","qing-hanedani","japon-tayvani"],"yer_id":"Zeelandia Kalesi (Anping, Tainan)","gun":"17 Nisan 1895","d":"Çin-Japon Savaşı'nı bitiren Şimonoseki Antlaşması 17 Nisan 1895'te imzalandı; Tayvan ve Penghu (Pescadores) Japonya'ya bırakıldı. Antlaşma 8 Mayıs 1895'te yürürlüğe girdi ve Japonya Tayvan'ın ilk genel valisini 10 Mayıs'ta atadı. Bu olayda ilgili yerleşimler: San Salvador Kalesi, Heping Adasi (Keelung), Zeelandia Kalesi (Anping, Tainan). Bu olayla Taipei, Kaohsiung, Taichung, Yilan, Hualien ve Taitung (Formosa adası) Japonya'ya geçti.","kaynak":"Treaty of Shimonoseki, 17 Nisan 1895 (antlaşma metni): https://pages.ucsd.edu/~dkjordan/tw/Simonoseki.html ; New World Encyclopedia: https://www.newworldencyclopedia.org/entry/Treaty_of_Shimonoseki · Yer teyidi (DUNYA-1102 D(b), 3 Kasım 2026): Şimonoseki Antlaşması metni, md. 2(b) (en.wikisource.org/wiki/Treaty_of_Shimonoseki — birincil metin neşri; açıldı, okundu) · Takekoshi, Japanese Rule in Formosa (1907) s. 83 (archive.org japaneseruleinf00takegoog) cessionu doğruluyor","sinif":"D"},{"t":"1896-01-20","devlet":"ingiliz-altin-kiyisi","taraflar":["asanti","ingiliz-altin-kiyisi"],"b":"İngilizler Kumasi'ye girip Asante Kralı Prempeh I'i teslim aldı; Asante Altın Sahil İngiliz yönetimine geçti (Bono-Manso dahil Asante toprakları)","tur":"toprak-kayip","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","asanti","ingiliz-altin-kiyisi"],"yer_id":"Bono-Manso (Techiman kuzeyi)","gun":"20 Ocak 1896","d":"Sir Francis Scott komutasındaki İngiliz kuvveti 17 Ocak 1896'da direnişsiz Kumasi'ye girdi; Prempeh I 20 Ocak'ta Altın Sahil valisi Maxwell'e boyun eğdi, tutuklanıp Cape Coast'a götürüldü ve koruma antlaşması imzalatıldı. Asante fiilen Altın Sahil kolonisinin denetimine girdi. Not: Bono-Manso'nun doğrudan anıldığı kaynak bulunamadı; devir Asante bütünü üzerindendir. Bu olayda ilgili yerleşimler: Bono-Manso (Techiman kuzeyi).","kaynak":"Anglo-Ashanti War of 1893-1896: https://www.globalsecurity.org/military/world/war/anglo-ashanti-1893.htm ; E. Africa/Manhyia: https://www.eaumf.org/ejm-blog/2018/1/17/january-17-1896-sir-francis-scott-enters-kumasi-with-british-and-west-indian-troops ; https://manhyiaarchives.org/royal-history/history-of-asante-union/41-asante-kings-of-the-twentieth-century-nana-prempeh-1-1888-1931-k-m-a-c","sinif":"D"},{"t":"1899-03-31","devlet":"abd","taraflar":["filipin-malolos-cumhuriyeti","abd"],"b":"ABD kuvvetleri Birinci Filipin Cumhuriyeti'nin başkenti Malolos'u ele geçirdi","tur":"isgal","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","filipin-malolos-cumhuriyeti","abd"],"yer_id":"Malolos","gun":"31 Mart 1899","d":"25 Mart 1899'da başlayan kuzey taarruzunun ardından General MacArthur komutasındaki Amerikan birlikleri 31 Mart 1899'da Malolos'u aldı; Filipin hükümeti 29 Mart'ta San Isidro'ya çekilmişti. Şehir geri çekilen Filipinli kuvvetlerce kısmen yakılmıştı. Bu olayda ilgili yerleşimler: Malolos.","kaynak":"Inquirer, The collapse of Malolos, March 31, 1899: https://usa.inquirer.net/145631/the-collapse-of-malolos-march-31-1899 ; Gen. Otis dispatch, SC Historic Newspapers 5 Nisan 1899: https://historicnewspapers.sc.edu/lccn/sn84026907/1899-04-05/ed-1/seq-1/","sinif":"D"},{"t":"1901-07-04","devlet":"amerikan-filipinleri","taraflar":["abd","amerikan-filipinleri"],"b":"Filipinler'de askerî yönetim sona erdi, Taft sivil vali oldu; Malolos'un bağlı olduğu bölge Amerikan Filipinleri sivil hükümetine geçti","tur":"siyaset","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","abd","amerikan-filipinleri"],"yer_id":"Malolos","gun":"4 Temmuz 1901","d":"Başkan McKinley'in 21 Haziran 1901 tarihli yürütme emri, Filipinler'de sivil işlerdeki yürütme yetkisini askerî validen Filipin Komisyonu başkanına devretti; William H. Taft 4 Temmuz 1901'de ilk sivil vali olarak yemin etti. Askerî yetki isyanın sürdüğü bölgelerde kaldı. Bu olayda ilgili yerleşimler: Malolos.","kaynak":"Executive Order, 21 Haziran 1901, American Presidency Project: https://www.presidency.ucsb.edu/documents/executive-order-122 ; Library of Congress Country Studies: https://countrystudies.us/philippines/16.htm","sinif":"D"},{"t":"1911-01-01","devlet":"ingiliz-nijerya","taraflar":["nri","ingiliz-nijerya"],"b":"Nri (Agukwu Nri) ve Igbo-Ukwu çevresi İngiliz Nijerya yönetimine girdi; Nri ritüel otoritesi çözüldü","tur":"toprak-kayip","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","nri","ingiliz-nijerya"],"yer_id":"Nri (Agukwu Nri)","gun":"1911","d":"İngilizler 1907'den itibaren Nri dinî-siyasî otoritesini yıkmaya çalıştı; Eze Nri Obalike Awka mahkemesine çağrılıp çevre kasabaları bağlayan yasakları kaldırmaya zorlandı. 1911'de 'warrant chief' sistemiyle Nri'nin kalıntı hiyerarşisi bitti ve bölge Güney Nijerya yönetimine katıldı. Gün bilinmiyor; 1914 birleşmesinden önceki bu devir yıl düzeyinde kaynaklanmıştır. Bu olayda ilgili yerleşimler: Igbo-Ukwu, Nri (Agukwu Nri).","kaynak":"Kingdom of Nri (Vikipedi, ikincil; akademik kaynak: Onwuejeogwu, An Igbo Civilization: Nri Kingdom and Hegemony, 1981 - doğrudan doğrulanamadı); Seshat polity 668 https://seshat-db.com/core/polity/668","sinif":"D"},{"t":"1917-03-15","devlet":"rusya-gecici-hukumet","taraflar":["rusya","rusya-gecici-hukumet"],"b":"II. Nikolay tahttan çekildi, Rusya yönetimi Geçici Hükümet'e geçti (Mitau, Goldingen, Ani, Mestia, Zugdidi dahil)","tur":"siyaset","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","rusya","rusya-gecici-hukumet"],"yer_id":"Zugdidi (Megrelya/Odişi merkezi)","gun":"15 Mart 1917","d":"II. Nikolay 15 Mart 1917'de (eski takvimle 2 Mart) Pskov'da tahttan çekildi; tahtı devrettiği Grandük Mihail ertesi gün yetkiyi Kurucu Meclis'e bıraktı ve iktidar Duma Geçici Komitesi'nin kurduğu Geçici Hükümet'te kaldı. Kuzey Kafkasya/Transkafkasya (Ani, Svaneti, Megrelya) Özel Transkafkasya Komitesi eliyle Geçici Hükümet'e bağlandı; Kurlandiya (Mitau, Goldingen) 1915'ten beri Alman işgalindeydi, devir hukukî-nominaldir. Bu olayda ilgili yerleşimler: Ani, Goldingen (Kuldīga), Mestia (Svaneti), Mitau (Jelgava), Zugdidi (Megrelya/Odişi merkezi). Bu olayla Rus İmparatorluğu'nun bütün toprakları (St. Petersburg, Moskova, Minsk, Kişinev, Tallinn dahil) Rusya Geçici Hükümeti'ne geçti.","kaynak":"Abdication of Nicholas II, https://www.prlib.ru/en/node/683263 ; https://alphahistory.com/russianrevolution/abdication-of-nicholas-ii-1917/ ; Özel Transkafkasya Komitesi (Mart 1917) · Yer teyidi (DUNYA-1102 D(b), 3 Kasım 2026): M.M. Safonov, '«Манифест подписан. Передача задержана снятием дубликата». Документальные свидетельства', Вестник архивиста, №3, 2015, s. 8 vd. (https://spbiiran.ru/wp-content/uploads/2024/03/safonov-m-manifesto-signed.-delivery-detained-2015.pdf) — ayrıca aynı makalede Nikolay'ın 2 Mart günlüğü: «передал подписанный и переделанный манифест». Maddenin prlib.ru bağlantısı bot denetimi yüzünden açılamadı; alphahistory.com dayanak olamaz.","sinif":"D"},{"t":"1917-03-31","devlet":"abd","taraflar":["danimarka-bati-hint","abd","danimarka"],"b":"Danimarka Batı Hint Adaları (Charlotte Amalie/St. Thomas, Christiansted/St. Croix) ABD'ye devredildi","tur":"toprak-kazanc","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","danimarka-bati-hint","abd","danimarka"],"yer_id":"Taphus / Charlotte Amalie (St. Thomas)","gun":"31 Mart 1917","d":"4 Ağustos 1916 antlaşması uyarınca Danimarka adaları 25 milyon dolar altın karşılığında ABD'ye bıraktı; onaylar 17 Ocak 1917'de teati edildi, ödeme ve fiilî devir 31 Mart 1917'de gerçekleşti. Adalar Virgin Islands adıyla Deniz Bakanlığı yönetimine girdi. Bu olayda ilgili yerleşimler: Christiansted (St. Croix), Taphus / Charlotte Amalie (St. Thomas).","kaynak":"US Dept. of State circular, 2 Nisan 1917, FRUS 1917 https://history.state.gov/historicaldocuments/frus1917/d887 ; https://history.state.gov/historicaldocuments/frus1917/d889","sinif":"D"},{"t":"1917-11-28","devlet":"transkafkasya","taraflar":["rusya-gecici-hukumet","transkafkasya","sovyet-rusya"],"b":"Transkafkasya Komiserliği kuruldu: Özel Transkafkasya Komitesi'nin yerini aldı, Ani, Mestia ve Zugdidi çevresi Transkafkasya yönetimine geçti","tur":"kurulus","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","rusya-gecici-hukumet","transkafkasya","sovyet-rusya"],"yer_id":"Zugdidi (Megrelya/Odişi merkezi)","gun":"Kasım 1917 (kaynaklara göre 11 veya 28 Kasım)","d":"Ekim Devrimi'nden sonra Tiflis'te Özel Transkafkasya Komitesi'nin yerine, Mensheviklerden Nikolay Çheidze başkanlığında Transkafkasya Komiserliği kuruldu; Bolşevik Rusya tanınmadı. Kaynaklar kuruluş gününü farklı veriyor (11 Kasım; Kazemzadeh'e göre 28 Kasım 1917 yeni takvim); her ikisi de zincirin 7 Kasım tarihinin 30 gün içinde. Bu olayda ilgili yerleşimler: Ani, Mestia (Svaneti), Zugdidi (Megrelya/Odişi merkezi).","kaynak":"Special Transcaucasian Committee / Transcaucasian Democratic Federative Republic (Vikipedi, ikincil); Kazemzadeh, The Struggle for Transcaucasia 1917-1921 (doğrudan doğrulanamadı)","sinif":"D"},{"t":"1918-11-22","devlet":"almanya","taraflar":["baden","almanya"],"b":"Baden Büyük Dükü II. Friedrich tahttan çekildi; Baden (Heidelberg, Mannheim, Baden-Baden, Karlsruhe, Durlach) cumhuriyet olarak Almanya içinde kaldı","tur":"son","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","baden","almanya"],"yer_id":"Heidelberg","gun":"22 Kasım 1918","d":"Baden Özgür Halk Cumhuriyeti 14 Kasım 1918'de kurulmuş, II. Friedrich 13 Kasım'da hükûmet yetkilerinden vazgeçmiş ve 22 Kasım 1918'de resmen tahttan çekilmiştir. Baden Alman Devrimi içinde cumhuriyet oldu. Bu olayda ilgili yerleşimler: Baden-Baden, Durlach (Karlsruhe), Heidelberg, Karlsruhe, Mannheim.","kaynak":"Schloss Bruchsal, Monarşinin sonu https://www.schloss-bruchsal.de/en/interesting-amusing/collections/the-end-of-the-monarchy ; https://en.wikipedia.org/wiki/1919_Baden_state_election","sinif":"D"},{"t":"1918-11-30","devlet":"almanya","taraflar":["wurttemberg","almanya"],"b":"Württemberg Kralı II. Wilhelm tahttan çekildi; Württemberg (Hohenstaufen Kalesi/Göppingen dahil) cumhuriyet olarak Almanya içinde kaldı","tur":"son","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","wurttemberg","almanya"],"yer_id":"Hohenstaufen Kalesi (Göppingen, Schwaben)","gun":"30 Kasım 1918","d":"Württemberg Kralı II. Wilhelm 30 Kasım 1918'de tahttan çekildi; Alman Devrimi'nde tahttan çekilen son Alman hükümdarıdır ve krallık Özgür Halk Devleti'ne dönüştü. Bu olayda ilgili yerleşimler: Hohenstaufen Kalesi (Göppingen, Schwaben). Bu tahttan çekilmeyle Stuttgart (Württemberg) cumhuriyet olarak Almanya içinde kaldı.","kaynak":"Yer teyidi (DUNYA-1102 D(b), 3 Kasım 2026): Archivportal-D 'In Focus - Change of System' https://cms.archivportal-d.de/en/node/6016 ; dzieje.pl / IPN sergisi 'Powstanie Wielkopolskie 1918–1919' https://dzieje.pl/node/134774 · önceki kaynak yasak listede, değiştirildi: Archivportal-D, 'In Focus - Change of System' (https://www.archivportal-d.de/en/node/6016): 'On November 30, 1918, the monarch of Württemberg, King Wilhelm II' tahttan çekildi — belge Landesarchiv Bad","sinif":"D"},{"t":"1918-12-01","devlet":"izlanda","taraflar":["izlanda-norvec-danimarka","izlanda"],"b":"Danimarka-İzlanda Birlik Yasası yürürlüğe girdi: İzlanda (Þingvellir, Skálholt) egemen İzlanda Krallığı oldu","tur":"kurulus","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","izlanda-norvec-danimarka","izlanda"],"yer_id":"Þingvellir (Thingvellir, Althing)","gun":"1 Aralık 1918","d":"1 Aralık 1918'de yürürlüğe giren Birlik Yasası İzlanda'yı Danimarka ile kral şahsında birleşen egemen bir devlet yaptı; dış işleri ve savunmayı Danimarka İzlanda adına yürüttü. Krallık 17 Haziran 1944'te cumhuriyete dönüştü. Bu olayda ilgili yerleşimler: Skálholt, Þingvellir (Thingvellir, Althing). Bu yasayla Reykjavík ve Akureyri (İzlanda) egemen İzlanda Krallığı'na geçti.","kaynak":"Yer teyidi (DUNYA-1102 D(b), 3 Kasım 2026): Agnes Arnórsdóttir, 'History of Iceland, 1840s to the Second World War', nordics.info (Aarhus Üniversitesi) · önceki kaynak yasak listede, değiştirildi: Britannica, 'Act of Union (Iceland, 1918)' (https://www.britannica.com/topic/Act-of-Union-Iceland-1918): 'On December 1, 1918, Iceland became a separate state under the Danish crown' ; https://en.wiki","sinif":"D"},{"t":"1922-03-12","devlet":"zakafkasya-sfsc","taraflar":["sovyet-rusya","zakafkasya-sfsc"],"b":"Gürcistan, Ermenistan ve Azerbaycan Sovyet cumhuriyetleri Zakafkasya Federasyonu'nu kurar; Svaneti ve Megrelya (Mestia, Zugdidi) federasyona bağlanır","tur":"birlesme","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","sovyet-rusya","zakafkasya-sfsc"],"yer_id":"Zugdidi (Megrelya/Odişi merkezi)","gun":"12 Mart 1922","d":"Gürcistan, Ermenistan ve Azerbaycan SSC'leri 12 Mart 1922'de Zakafkasya Federasyonu anlaşmasını imzaladı; federasyon 30 Aralık 1922'de SSCB'nin kurucu üyesi Zakafkasya SFSC olarak yeniden düzenlendi. Gürcistan toprakları bu çatı altında yönetildi. Bu olayda ilgili yerleşimler: Mestia (Svaneti), Zugdidi (Megrelya/Odişi merkezi).","kaynak":"https://en.wikipedia.org/wiki/Transcaucasian_Socialist_Federative_Soviet_Republic ; Library of Congress Country Studies, Georgia: Soviet rule (yardımcı kaynak; birincil doğrulama sınırlı)","sinif":"D"},{"t":"1934-10-10","devlet":"cin-cumhuriyeti","taraflar":["cin-sovyet-cumhuriyeti","cin-cumhuriyeti"],"b":"Çin Sovyet Cumhuriyeti Ruijin'i boşaltmaya başlar (Uzun Yürüyüş); Ruijin Çin Cumhuriyeti (Kuomintang) denetimine geçer","tur":"toprak-kayip","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","cin-sovyet-cumhuriyeti","cin-cumhuriyeti"],"yer_id":"Ruijin (Jiangxi)","gun":"10 Ekim 1934","d":"Çin Komünist Partisi, Çan Kay-şek'in beşinci kuşatma harekâtı karşısında 10 Ekim 1934'te Ruijin'deki Jiangxi Sovyeti'ni terk etme kararını uyguladı; ordu 16 Ekim'de kuşatmayı yarıp batıya yürüdü. Kuomintang kuvvetlerinin Ruijin'e fiilen girişinin tam günü doğrulanamadı. Bu olayda ilgili yerleşimler: Ruijin (Jiangxi).","kaynak":"LoC China Country Study (countrystudies.us/china/21.htm) — «The epic Long March ... which began in October 1934»","sinif":"D"},{"t":"1935-11-15","devlet":"filipin-commonwealth","taraflar":["amerikan-filipinleri","filipin-commonwealth"],"b":"Filipin Commonwealth'i kurulur; Malolos dahil Amerikan Filipinleri özerk Commonwealth'e dönüşür","tur":"kurulus","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","amerikan-filipinleri","filipin-commonwealth"],"yer_id":"Malolos","gun":"15 Kasım 1935","d":"Tydings-McDuffie Yasası (1934) uyarınca hazırlanan anayasa 1935'te onaylandı; Filipin Commonwealth'i 15 Kasım 1935'te Manuel Quezon'un göreve başlamasıyla kuruldu. On yıllık geçiş sonrası bağımsızlık öngörülüyordu. Bu olayda ilgili yerleşimler: Malolos. Bu dönüşümle bütün takımada — Manila, Cebu, Iloilo, Vigan, Zamboanga, Jolo, Kotabato, Legazpi, Puerto Princesa vd. — özerk Filipin Commonwealth'ine geçti.","kaynak":"Office of the Historian, U.S. Department of State, Milestones: Philippines (history.state.gov/milestones/1921-1936/philippines) ; Library of Congress Country Studies, Philippines · Yer teyidi (DUNYA-1102 D(b), 3 Kasım 2026): Office of the Historian, Milestones 1899-1913 'The Philippine-American War, 1899-1902' (history.state.gov/milestones/1899-1913/war)","sinif":"D"},{"t":"1945-04-28","devlet":"italya","taraflar":["salo-cumhuriyeti","italya"],"b":"Mussolini yakalanıp idam edildi; Salo Cumhuriyeti (İtalyan Sosyal Cumhuriyeti) çöktü, Salo İtalya Krallığı/İtalya denetimine geçti","tur":"son","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","salo-cumhuriyeti","italya"],"yer_id":"Salo","gun":"28 Nisan 1945","d":"25 Nisan 1945 genel ayaklanma sonrası RSI çözüldü; Mussolini 28 Nisan'da partizanlarca öldürüldü, Alman kuvvetleri 29 Nisan'da Caserta'da teslim oldu (2 Mayıs'ta yürürlük), RSI savunma bakanı Graziani 1 Mayıs'ta kalan güçlere silah bırakmayı emretti. Bu olayda ilgili yerleşimler: Salo. Salò Cumhuriyeti'nin çöküşüyle Milano, Torino, Cenova, Venedik, Verona, Bolonya ve öteki kuzey İtalya şehirleri İtalya'ya döndü.","kaynak":"Italian Social Republic (ozet, kaynak ek dogrulama: Surrender at Caserta, Avalon Project https://avalon.law.yale.edu/wwii/gs9.asp ); Il Post, La nascita della Repubblica di Salo https://www.ilpost.it/2013/09/23/repubblica-di-salo/ · Yer teyidi (DUNYA-1102 D(b), 3 Kasım 2026): archontology.org Italian Social Republic polity, https://archontology.org/nations/italy/italian_social_republic/01_polity.php","sinif":"D"},{"t":"1945-08-17","devlet":"cin-cumhuriyeti","taraflar":["mancukuo","cin-cumhuriyeti","sovyet-rusya"],"b":"Mancukuo sona erdi: Pu Yi tahttan çekildi, Sovyet Kızıl Ordusu Hsinking'i (Changchun) aldı ve bölge Çin Cumhuriyeti'ne iade edilecek biçimde Çin'e bağlandı","tur":"son","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","mancukuo","cin-cumhuriyeti","sovyet-rusya"],"yer_id":"Hsinking (Changchun)","gun":"17 Ağustos 1945","d":"Mançukuo'nun dağılması (解体) 17 Ağustos 1945'te ilan edildi (Nihon Daihyakka, Yamakawa); Pu Yi'nin tahttan çekilmesini kaynaklar 16-18 Ağustos arasında verir (Danıştay başkanı Zang Shiyi 17 Ağustos'ta duyurdu); Kızıl Ordu 20 Ağustos 1945 dolayında Changchun'a girdi. 14 Ağustos 1945 Çin-Sovyet Dostluk ve İttifak Antlaşması bölgeyi Çin'e iade çerçevesini kurdu. Gün farkı ±30 gün içindedir. Bu olayda ilgili yerleşimler: Hsinking (Changchun).","kaynak":"Nihon Daihyakka Zensho (Nipponica) ve Yamakawa Nihonshi Sho-jiten, kotobank.jp/word/満州国-137955 — «日本の無条件降伏後の8月17日に「解体」が宣言された。 / 8月17日満州国は解体を宣言した。»","sinif":"D"},{"t":"1945-08-18","devlet":"sovyet-rusya","taraflar":["sovyet-rusya","cin-cumhuriyeti"],"b":"Sovyet hava indirme birliği Harbin'e indi; Kızıl Ordu'nun Harbin işgali başladı","tur":"isgal","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","isgal","konu-askeri","sovyet-rusya","cin-cumhuriyeti"],"yer_id":"Harbin","gun":"18 Ağustos 1945 (BSE)","d":"Kwantung Ordusu'nun teslimi duyurulurken Mareşal Vasilevski büyük şehirlerin özel birliklerle tutulmasını emretti; 18 Ağustos'ta Harbin'e hava indirme birliği indirildi. 20 Ağustos'ta 1. Uzakdoğu Cephesi'nin ileri müfrezeleri ve Amur Filosu gemileriyle 15. Ordu şehre ulaştı. Sovyet varlığı 14 Ağustos 1945 Çin-Sovyet antlaşması çerçevesinde geçici askerî işgaldi; Harbin 25 Nisan 1946'ya dek Sovyet işgalinde kaldı. Bu olayda ilgili yerleşimler: Harbin.","kaynak":"BSE 3. bs. 'Маньчжурская операция 1945' (N. V. Eronin; https://booksite.ru/fulltext/1/001/008/073/571.htm): «18 августа в Харбине, а 19 августа в Гирине, Чанчуне, Мукдене были высажены воздушные десанты», «20 августа 15-я армия фронта заняла Харбин»; Glantz, August Storm: The Soviet 1945 Strategic Offensive in Manchuria (Leavenworth Papers 7, Combat Studies Institute, 1983), 1. Uzakdoğu Cephesi bölümü","sinif":"isg"},{"t":"1945-08-19","devlet":"sovyet-rusya","taraflar":["sovyet-rusya","cin-cumhuriyeti"],"b":"Kızıl Ordu Mukden, Cilin, Tsitsihar ve Sansing'i aldı; Puyi Mukden havaalanında esir düştü","tur":"isgal","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","isgal","konu-askeri","sovyet-rusya","cin-cumhuriyeti"],"yer_id":"Mukden (Şenyang)","gun":"19 Ağustos 1945 (BSE; Glantz; Jilin kronolojisi)","d":"19 Ağustos'ta Mukden, Cilin ve Changchun'a Sovyet hava indirme birlikleri indirildi; Japonya'ya kaçmaya çalışan Puyi Mukden havaalanında esir alındı. Aynı gün Transbaykal Cephesi'nin 36. Ordusu Tsitsihar'ı aldı, Amur Filosu'nun taşıdığı 632. Tüfek Alayı Sansing'i 15. Ordu adına ele geçirdi. 6. Muhafız Tank Ordusu Mukden'e 21 Ağustos'ta girdi. Sovyet varlığı Çin-Sovyet antlaşması çerçevesinde geçici askerî işgaldi. Bu olayda ilgili yerleşimler: Mukden (Şenyang), Cilin (Jilin), Qiqihar, Sanxing (Yilan).","kaynak":"BSE 3. bs. 'Маньчжурская операция 1945' (https://booksite.ru/fulltext/1/001/008/073/571.htm): «19 августа в Гирине, Чанчуне, Мукдене были высажены воздушные десанты»; Glantz, August Storm (Leavenworth Papers 7, 1983): «The army occupied its ultimate objective of Tsitsihar on 19 August», «On 19 August this force secured Sansing for 15th Army», «On 21 August 6th Guards Tank Army units occupied both Changchun and Mukden, two days after the arrival of Soviet air-landed detachments»; 吉林省编年纪事 1931-1945 (Jilin Eyalet Kütüphanesi, https://www.jilinlib.cn/szzy/jlsbnjs/201101/P020110118730825407783.pdf): «8月19日：苏军空降长春、吉林等地。溥仪在沈阳机场被苏军俘虏»; Yamakawa Nihonshi Shō-jiten 「溥儀」: «45年8月19日瀋陽でソ連軍に逮捕され» (https://kotobank.jp/word/溥儀-15041)","sinif":"isg"},{"t":"1945-08-20","devlet":"sovyet-rusya","taraflar":["sovyet-rusya","cin-cumhuriyeti"],"b":"Aihun istihkâm bölgesi Kızıl Ordu'ya teslim oldu; Sovyet ileri müfrezeleri 20-21 Ağustos'ta Nencheng (Mergen) ve Peian'ı aldı","tur":"isgal","onem":2,"dunya":1,"kapsam":"dis","etiket":["sinir","isgal","konu-askeri","sovyet-rusya","cin-cumhuriyeti"],"yer_id":"Aigun","gun":"20 Ağustos 1945 (Glantz); Nencheng/Peian 20-21 Ağustos","d":"2. Uzakdoğu Cephesi'nin 2. Kızıl Bayrak Ordusu 11 Ağustos'ta Amur'u geçip Aihun ve Sunwu istihkâm bölgelerini kuşattı. Aihun mevzii 20 Ağustos'a dek direndi ve o gün kalan 4.520 Japon askeri teslim oldu. Ordunun ileri müfrezeleri 20 ve 21 Ağustos'ta Nencheng (Mergen) ile Peian'ı aldı. Bu olayda ilgili yerleşimler: Aigun, Mergen (Nenjiang).","kaynak":"Glantz, August Storm: The Soviet 1945 Strategic Offensive in Manchuria (Leavenworth Papers 7, 1983): «The Aihun position continued resistance ... until 20 August, when the remaining Japanese force of 4,520 men surrendered», «On 20 and 21 August they secured Nencheng and Peian»","sinif":"isg"},{"t":"1946-03-12","devlet":"sovyet-rusya","taraflar":["sovyet-rusya","cin-cumhuriyeti"],"b":"Sovyet ordusu Mukden'i boşalttı","tur":"isgal","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","isgal","konu-askeri","sovyet-rusya","cin-cumhuriyeti"],"yer_id":"Mukden (Şenyang)","gun":"12 Mart 1946 (Keesing's; Jilin kronolojisi)","d":"Sovyet birlikleri 11 Mart 1946'da Çin Changchun Demiryolu boyunca kuzeye çekilmeye başladı ve 12 Mart'ta Mukden'i tümüyle boşalttı. Çin Komünistlerinin çekilme sırasında şehri alma girişimi sokak çatışmasıyla püskürtüldü; Merkezî Hükûmet birlikleri 13 Mart'ta şehre girdi. Bu olayda ilgili yerleşimler: Mukden (Şenyang).","kaynak":"Keesing's Contemporary Archives, Haziran 1946, 'China — Soviet Evacuation of Manchuria' (https://web.stanford.edu/group/tomzgroup/pmwiki/uploads/2704-1946-06-ks-a-ajg.pdf): «Soviet forces evacuated Mukden on March 12»; 吉林省编年纪事 1946 (https://www.jilinlib.cn/szzy/jlsbnjs/201101/P020110118730824947128.pdf): «3月11日：苏军开始沿中长铁路北撤回国，12日全部撤离沈阳。13日，国民党军队进占沈阳»","sinif":"isg"},{"t":"1946-04-14","devlet":"sovyet-rusya","taraflar":["sovyet-rusya","cin-cumhuriyeti"],"b":"Sovyet ordusu Changchun ve Cilin'den çekildi","tur":"isgal","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","isgal","konu-askeri","sovyet-rusya","cin-cumhuriyeti"],"yer_id":"Cilin (Jilin)","gun":"14 Nisan 1946 (Jilin kronolojisi; Keesing's Changchun için)","d":"Sovyet birlikleri 14 Nisan 1946'da Changchun'dan ve aynı gün Cilin şehrinden çekildi. Cilin'e Çin Komünist kuvvetleri girdi; Changchun'a saldıran Komünistler şehri 18 Nisan'da ele geçirdi. Bu olayda ilgili yerleşimler: Cilin (Jilin).","kaynak":"吉林省编年纪事 1946 (Jilin Eyalet Kütüphanesi, https://www.jilinlib.cn/szzy/jlsbnjs/201101/P020110118730824947128.pdf), 4月14日 maddesi: «14日，苏军自长春撤离完毕», «是日：苏军自吉林市撤离回国。吉辽部队进驻吉林市»; Keesing's Contemporary Archives, Haziran 1946: «withdrew on April 14 from Changchun»; FRUS 1946 c. IX d. 368 (Sovyet çekilme PLANI, https://history.state.gov/historicaldocuments/frus1946v09/d368): «Soviet city troops at Chi-lin will complete withdrawal from the 13th to 16th, April»","sinif":"isg"},{"t":"1946-04-25","devlet":"sovyet-rusya","taraflar":["sovyet-rusya","cin-cumhuriyeti"],"b":"Sovyet ordusu Harbin'den çekildi; Tsitsihar da aynı günlerde boşaltıldı","tur":"isgal","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","isgal","konu-askeri","sovyet-rusya","cin-cumhuriyeti"],"yer_id":"Harbin","gun":"25 Nisan 1946 (FRUS; Shen Zhihua) — Tsitsihar için gün yaklaşık","d":"Sovyet birlikleri 25 Nisan 1946'da Harbin'i boşalttı; Çin Komünist kuvvetleri şehre karşı koyulmadan girdi. Sovyet temsilcileri Nisan başında Harbin ile Tsitsihar'dan 25 Nisan'da çekileceklerini bildirmişti; Komünistler Tsitsihar'ı 24-28 Nisan arasında (kaynaklar ayrışır) denetime aldı. Bu olayda ilgili yerleşimler: Harbin, Qiqihar.","kaynak":"FRUS 1946 c. IX d. 497 (SWNCC 291/1, 1 Haziran 1946; https://history.state.gov/historicaldocuments/frus1946v09/d497): «Harbin was occupied by the Communists without opposition on April 25, the date of the Soviet evacuation»; Shen Zhihua (沈志华), 「斯大林与中国内战的起源（1945-1946）」 (https://www.aisixiang.com/data/24676.html): «苏军将于15日和25日分别撤离长春和哈尔滨、齐齐哈尔», «哈市苏军已定于25日撤离»","sinif":"isg"},{"odak_yer":["Moskova"],"t":"1946-05-03","devlet":"sovyet-rusya","taraflar":["sovyet-rusya","cin-cumhuriyeti"],"b":"Sovyetler Kuzeydoğu Çin'den (Port Arthur hariç) çekilmenin tamamlandığını ilân etti","tur":"isgal","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","isgal","konu-askeri","sovyet-rusya","cin-cumhuriyeti"],"yer":"Mançurya (Kuzeydoğu Çin)","gun":"3 Mayıs 1946 (Shen Zhihua; ÇSBA)","d":"Sovyet ordusu 3 Mayıs 1946'da Kuzeydoğu Çin'den çekilmenin tamamlandığını ilân etti; Çin-Sovyet antlaşması uyarınca Port Arthur'da kaldı. Böylece Ağustos 1945'te başlayan Sovyet işgali Mançurya'da sona erdi. Çekilme günü ayrıca bulunamayan Aigun, Mergen ve Sansing'de işgalin sonu bu güne (üst sınır) yazıldı. Bu olayda ilgili yerleşimler: Aigun, Mergen (Nenjiang), Sanxing (Yilan).","kaynak":"Shen Zhihua (沈志华), 「斯大林与中国内战的起源（1945-1946）」 (https://www.aisixiang.com/data/24676.html): «5月3日苏军宣布全部撤离中国»; ÇSBA Yakın Tarih Enstitüsü, 「1946年春反苏运动述评」 (http://jds.cssn.cn/xscg/xslw/201605/t20160506_5249807.shtml): «5月3日，苏军宣称从东北地区撤退完毕»; Keesing's Contemporary Archives, Haziran 1946: «at the beginning of May were reported to have evacuated the whole of Manchuria except for Port Arthur»","sinif":"isg"},{"t":"1948-03-12","devlet":"hindistan-cumhuriyeti","taraflar":["bundela-orcha","hindistan-cumhuriyeti"],"b":"Orchha (Bundela) Devleti, Bundelkhand/Baghelkhand devletleriyle birlikte Vindhya Pradesh Birliği'ne katıldı ve Hindistan Birliği'ne bağlandı","tur":"birlesme","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","bundela-orcha","hindistan-cumhuriyeti"],"yer_id":"Orchha (Orcha)","gun":"12 Mart 1948","d":"Orchha, 1948'de Bundelkhand ve Baghelkhand prenslikleriyle birlikte Vindhya Pradesh Birliği'ne katıldı (birlik 12 Mart 1948'de kuruldu, 4 Nisan 1948'de açıldı); Britannica Orchha'nın 1948'de Vindhya Pradesh içinde Tikamgarh ilçesi olarak birleştiğini bildirir. Bazı kaynaklar Orchha'nın Hindistan Birliği'ne tam katılımını 1 Ocak 1950 olarak verir; bu iki aşama arasındaki fark ayrıca incelenmelidir. Bu olayda ilgili yerleşimler: Orchha (Orcha).","kaynak":"https://www.britannica.com/print/article/431282 (Orchha 1948'de Vindhya Pradesh'e katıldı); https://en.wikipedia.org/wiki/Vindhya_Pradesh (kuruluş 12.03.1948, açılış 04.04.1948; ikincil)","sinif":"D"},{"t":"1948-03-27","devlet":"pakistan","taraflar":["kalat-hanligi","pakistan"],"b":"Kalat Han'ı Ahmed Yar Han, Kalat'ı Pakistan'a bağlayan katılma belgesini imzaladı","tur":"toprak-kazanc","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","kalat-hanligi","pakistan"],"yer_id":"Kalat (Kelat)","gun":"27 Mart 1948","d":"15 Ağustos 1947'de bağımsızlığını ilan eden Kalat Hanlığı'nın Han'ı Ahmed Yar Han, 27 Mart 1948'de Pakistan'a katılma belgesini imzaladı; Genel Vali Jinnah 31 Mart'ta kabul etti. Katılımın meşruiyeti Beluç milliyetçilerince tartışmalıdır. Bu olayda ilgili yerleşimler: Kalat (Kelat).","kaynak":"https://en.wikipedia.org/wiki/Accession_of_Kalat (ikincil); https://www.dawn.com/news/amp/1704833 (Dawn); globalsecurity.org/military/world/war/balochistan-1948.htm","sinif":"D"},{"t":"1959-03-28","devlet":"cin-halk-cumhuriyeti","taraflar":["tibet-ganden-phodrang","cin-halk-cumhuriyeti"],"b":"Çin Devlet Konseyi Tibet yerel hükümetini (Ganden Phodrang) feshetti, yetkileri Tibet Özerk Bölgesi Hazırlık Komitesi'ne devretti (Sakya dahil)","tur":"toprak-kayip","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","tibet-ganden-phodrang","cin-halk-cumhuriyeti"],"yer_id":"Sakya Manastırı (Sakya)","gun":"28 Mart 1959","d":"Mart 1959 Lhasa ayaklanmasının ardından Çin Başbakanı Zhou Enlai, 28 Mart 1959 tarihli Devlet Konseyi emriyle Tibet yerel hükümetini feshetti; yetkiler Hazırlık Komitesi'ne geçti ve Panchen Lama vekil başkan oldu. Böylece Tibet'te Ganden Phodrang yönetimi fiilen sona erdi. Bu olayda ilgili yerleşimler: Sakya Manastırı (Sakya).","kaynak":"Peking Review/Concerning the question of Tibet (FLP, Peking 1959), https://michaelharrison.org.uk/wp-content/uploads/2024/01/Concerning-the-question-of-Tibet-FLP-Peking-1959.pdf ; https://www.marxists.org/reference/archive/strong-anna-louise/1959/tibetan-interviews/ch06.htm","sinif":"D"},{"t":"1975-05-16","devlet":"hindistan-cumhuriyeti","taraflar":["sikkim-krallik","hindistan-cumhuriyeti"],"b":"Sikkim Krallığı Hindistan'ın 22. eyaleti olarak birleştirildi (36. Anayasa Değişikliği, Gangtok ve Yuksom dahil)","tur":"birlesme","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","sikkim-krallik","hindistan-cumhuriyeti"],"yer_id":"Gangtok","gun":"16 Mayıs 1975","d":"14 Nisan 1975 referandumunda oyların yaklasik %97,5'i Hindistan'la birlesmeyi destekledi; Lok Sabha 23 Nisan, Rajya Sabha 15 Mayis'ta 36. Anayasa Degisikligi'ni kabul etti, baskanlik onayi 16 Mayis 1975'te verildi. Sikkim, 371F maddesiyle Hindistan'in 22. eyaleti oldu, Chogyal monarsisi kaldirildi. Bu olayda ilgili yerleşimler: Gangtok, Yuksom (Yuksam).","kaynak":"https://www.usthadian.com/sikkims-journey-to-becoming-indias-22nd-state-50-years-of-integration/ ; Hindistan Anayasasi madde 371F ve 36. Degisiklik (indiacode.nic.in)","sinif":"D"},{"t":"1565-01-05","devlet":"bicapur","taraflar":["vijayanagara","bicapur","ahmednagar","golkonda","nayak-devletleri"],"b":"Talikota (Rakşasi-Tangadi) Savaşı: Dekken sultanlıkları ittifakı Vijayanagara ordusunu bozguna uğrattı; Aliya Rama Raya öldü, Hampi yağmalandı","tur":"savas","onem":5,"dunya":3,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","vijayanagara","bicapur"],"yer_id":"Vijayanagara (Hampi)","gun":"5 Ocak 1565","d":"Bîcâpur, Ahmednagar, Golkonda ve Bîdar sultanlıklarının ittifakı Vijayanagara ordusunu Talikota (Rakşasi-Tangadi) yöresinde bozguna uğrattı; başkent Hampi beş-altı ay yağmalandı, Vijayanagara bir daha eski gücüne kavuşamadı. Bu olayda ilgili yerleşimler: Vijayanagara (Hampi), Raycur (Raichur), Kurnûl (Kurnool), Bangalor, Mangalor, Seringapatam (Şrirangapatnam), Meysûr (Mysore).","kaynak":"TDV «Hüseyin Nizamşah» (islamansiklopedisi.org.tr/huseyin-nizamsah): «kalabalık Hindu kuvvetleri bozguna uğradı (5 Ocak 1565)»; Cambridge History of India III (Haig, ch. XVII «Battle of Talikota», s.448-449): «January 5, 1565»","sinif":"D"},{"odak_yer":["Malolos"],"t":"1898-06-12","gun":"12 Haziran 1898","kesinlik":"gun","devlet":"filipin-malolos-cumhuriyeti","devletler":["filipin-malolos-cumhuriyeti","ispanyol-filipinler"],"b":"Aguinaldo Kawit'te Filipinler'in bağımsızlığını ilan etti","tur":"kurulus","onem":4,"dunya":2,"kapsam":"dis","etiket":["sinir","kurulus","konu-siyasi","filipin-malolos-cumhuriyeti","ispanyol-filipinler"],"yer_id":"Malolos","d":"Emilio Aguinaldo, 12 Haziran 1898'de Cavite el Viejo'da (bugünkü Kawit), ailesinin evinde Filipinler'in bağımsızlığını ilan etti; ilanı İspanya ve ABD tanımadı. Birinci Filipin (Malolos) Cumhuriyeti ise Ocak 1899'da kuruldu. [gün kaynakla teyit edilmeli]","kaynak":"hakemli/resmî kaynak bu turda ham OKUNAMADI (resmî Gazete robots yasağı, Senato PDF'i 403). Gün WebSearch özetlerinde (NHCP Kawit tarihî işareti, Manila Bulletin; ham okunmadı) · [gün kaynakla teyit edilmeli]","taraflar":["filipin-malolos-cumhuriyeti","ispanyol-filipinler"]}];

