// data/kronoloji_sinir_once1281_yerlesim_asya_iran.js — paketle.py İNCELTTİ: ic_not* alanları yayına gitmez (kaynak dosya değişmedi)
window.KRONOLOJI_SINIR_ONCE1281_YERLESIM_ASYA_IRAN = [{"t":"1006-01-01","devlet":"gazneli","taraflar":["gazneli"],"b":"Gazneli Mahmud Mültan’ı yedi günlük kuşatmayla aldı","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","gazneli"],"yer_id":"Multan","gun":"1006 (396 h.; yıl — gün kaynaktan alınmadı)","d":"Gazneli Mahmud Mültan’ı yedi günlük bir muhasaradan sonra zaptetti; Karmatî hâkim Ebü’l-Fütûh Dâvûd kaçtı. 1008 ve 1010’da şehir yeniden alındı. Bu olayda ilgili yerleşimler: Multan.","kaynak":"TDV multan: 'Gazneli Mahmud Mültan’ı yedi günlük bir muhasaradan sonra zaptetti (396/1006) ve İsmâilîler dışındaki halka eman verdi' · 'Bunun üzerine Gazneli Mahmud, 398’de (1008) ve … 400’de (1010) şehri zaptetti.'","sinif":"D"},{"t":"1010-01-01","devlet":"ly-hanedani","taraflar":["ly-hanedani"],"b":"Lý Thái Tổ Thăng Long’u (Hanoi) başkent seçti — Lý hâkimiyetinde şehir","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","ly-hanedani"],"yer_id":"Hanoi (Thăng Long)","gun":"1010 (yıl — Britannica; gün/ay verilmiyor)","d":"Lý hanedanının (1009-1225) kurucusu Lý Thái Tổ 1010’da Hanoi’nin bulunduğu yeri Thăng Long adıyla başkent seçti; şehir 1802’ye dek Vietnam’ın ana başkenti kaldı. Bu olayda ilgili yerleşimler: Hanoi (Thăng Long).","kaynak":"Britannica, «Hanoi»: 'In 1010 Ly Thai To, the first ruler of the Ly dynasty (1009–1225) of Vietnam, chose the site of Hanoi—then called Thang Long (“Rising Dragon”)—for his capital. Thang Long remained the main capital of Vietnam until 1802'","sinif":"D"},{"t":"1017-05-30","devlet":"gazneli","taraflar":["memuni-harezm","gazneli"],"b":"Gazneli Mahmud Hârizm’i ilhak etti — Gürgenç’te Me’mûnîler sona erdi","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","gazneli","memuni-harezm"],"yer_id":"Köhne Ürgenç (Gürgenç)","gun":"408 h. (1017) — hicrî yılın ilk günü (Jülyen 1017-05-30); gün kaynaktan alınmadı","d":"Gazneli Mahmud Hârizmşah Me’mûnî Ebü’l-Hâris Muhammed’i azledip hapsetti, Me’mûnîler’in Hârizm hâkimiyetine son verdi ve buraya kumandanı Altuntaş’ı tayin etti. Bu olayda ilgili yerleşimler: Köhne Ürgenç (Gürgenç).","kaynak":"TDV gurgenc: 'Gazneli Mahmud, 408’de (1017) Ebü’l-Hâris Muhammed b. Ali’yi azl ve hapsedip Me’mûnîler’in Hârizm’deki hâkimiyetlerine son verdi ve buraya kendi kumandanlarından Altuntaş el-Hâcib’i tayin etti.'","sinif":"D"},{"t":"1036-01-01","devlet":"ukayli","taraflar":["ukayli"],"b":"Tikrît Ukaylî Benî Makn’dan Râfi‘ b. Hüseyin’in idaresine girdi","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","ukayli"],"yer_id":"Tikrit","gun":"1036 (427 h. yılı sonları; yıl — gün kaynaktan alınmadı)","d":"427 (1036) yılı sonlarında Tikrît, Ukaylîler’den Benî Makn ailesine mensup Râfi‘ b. Hüseyin b. Makn’ın idaresine girdi. Bu olayda ilgili yerleşimler: Tikrit.","kaynak":"TDV tikrit: 'Tikrît daha sonra Ukaylîler’den Benî Makn ailesinin hâkimiyetine geçti (İbnü’l-Esîr, X, 419). 427 (1036) yılı sonlarında şehir Râfi‘ b. Hüseyin b. Makn’ın idaresine girdi.'","sinif":"D"},{"t":"1041-01-01","devlet":"dogu-karahanli","taraflar":["karahanli","bati-karahanli","dogu-karahanli"],"b":"Karahanlı Devleti ikiye ayrıldı — Buhara ve Semerkant Batı, Kâşgar ve Balasagun Doğu Karahanlılar’da kaldı","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","karahanli","bati-karahanli","dogu-karahanli"],"yer_id":"Buhara","gun":"1041 (1041-1042; yıl — gün kaynaktan alınmadı) / 1041 (1041-1042; TDV semerkant 1046 — yıl, gün kaynaktan alınmadı)","d":"Karahanlı Devleti 1041-1042’de Doğu ve Batı olarak ikiye ayrıldı; Buhara’nın da içinde bulunduğu Mâverâünnehir Batı Karahanlılar’ın payına düştü. Karahanlı Devleti’nin ikiye bölünmesinde Semerkant Batı Karahanlılar’ın payına düştü ve Nasr (Tamgaç Han) onu Batı Karahanlı Devleti’nin başşehri yaptı. Karahanlı Devleti 1041-1042’de ikiye ayrıldı; Kâşgar ve Balasagun’u içine alan doğu kısım Yûsuf Kadır Han’ın Doğu Karahanlı hâkimiyetinde kaldı. Karahanlı Devleti 1041-1042’de ikiye ayrıldı; Balasagun, Doğu Karahanlı Hükümdarı Yûsuf Kadır Han’ın hâkimiyetindeki doğu kısımda kaldı. Bu olayda ilgili yerleşimler: Buhara, Semerkant, Kaşgar, Balasagun.","kaynak":"TDV karahanlilar: 'Bu durum devletin ikiye ayrıldığı 1041-1042 yıllarına kadar sürmüştür' · 'Aynüddevle Muhammed ve kardeşi Böri Tegin İbrâhim … Mâverâünnehir’in tamamına hâkim olup burada bağımsız bir devlet kurdular (433/1041-42).' · TDV semerkant: 'devletin 1046’da ikiye bölünmesi sırasında Batı Karahanlılar’da kaldı. … Nasr (Tamgaç Han), Semerkant’ı Batı Karahanlı Devleti’nin başşehri yaptı.' · TDV hucend: 'Doğu Karahanlı Hükümdarı Yûsuf Kadır Han’ın hâkimiyetindeki Balasagun ve Kâşgar Hanlığı’nın doğusu'","sinif":"D"},{"t":"1043-01-01","devlet":"buyuk-selcuklu","taraflar":["gazneli","buyuk-selcuklu"],"b":"Çağrı Bey Hezâresb ve Gürgenç’i Selçuklu topraklarına kattı","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","gazneli","buyuk-selcuklu"],"yer_id":"Köhne Ürgenç (Gürgenç)","gun":"1043 (434 h.; yıl — gün kaynaktan alınmadı)","d":"Çağrı Bey, Tuğrul Bey’le birlikte Hârizm üzerine yürüyerek Hezâresb ve Gürgenç’i Selçuklu topraklarına kattı; Gazneli üstünlüğü sona erdi. Bu olayda ilgili yerleşimler: Köhne Ürgenç (Gürgenç).","kaynak":"TDV gurgenc: 'Çağrı Bey, 434’te (1043) Tuğrul Bey’le birlikte Hârizm üzerine yürüyerek Hezâresb ve Gürgenç’i Selçuklu topraklarına kattı.'","sinif":"D"},{"t":"1054-01-01","devlet":"buyuk-selcuklu","taraflar":["revvadi","buyuk-selcuklu"],"b":"Tuğrul Bey’e itaat eden Tebriz, Azerbaycan’da Revvâdî yönetimini bıraktı","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","revvadi","buyuk-selcuklu"],"yer_id":"Tebriz","gun":"1054 (446 h.; yıl — gün kaynaktan alınmadı)","d":"Azerbaycan’a gelen Sultan Tuğrul Bey’e Revvâdî emîri Ebû Mansûr ve bazı mahallî hükümdarlar itaatini bildirdi; Tebriz bağımsız Revvâdî yönetiminden Selçuklu hâkimiyetine geçti. Bu olayda ilgili yerleşimler: Tebriz.","kaynak":"TDV tebriz: 'Tebriz, Revvâdî Emîri Ebû Mansûr ve bazı mahallî hükümdarlarla birlikte Azerbaycan’a gelen Sultan Tuğrul Bey’e itaatini bildirdi ve Selçuklu hâkimiyetine girdi (446/1054).'","sinif":"D"},{"t":"1057-01-01","devlet":"buyuk-selcuklu","taraflar":["ukayli","buyuk-selcuklu"],"b":"Tikrît Tuğrul Bey’e teslim edildi — Ukaylî Benî Makn dönemi bitti","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","ukayli","buyuk-selcuklu"],"yer_id":"Tikrit","gun":"1057 (448 h. = 1056-57 sonrası; yıl-temsilî — gün kaynaktan alınmadı)","d":"Tuğrul Bey’in kuşatması ve Nasr b. Ali’nin ölümü üzerine nâib Ebü’l-Ganâim b. Muhallebân Tikrît’i Tuğrul Bey’e teslim etti; idareyi Ebü’l-Abbas er-Râzî aldı. Bu olayda ilgili yerleşimler: Tikrit.","kaynak":"TDV tikrit: 'Tuğrul Bey 448’de (1056-57) Bağdat’tan ayrılıp Musul’a giderken Nasr b. Ali b. Hamîs’in idaresindeki Tikrît’i bir süre kuşattı. … Ebü’l-Ganâim, halifenin veziri Reîsürrüesâ İbn Müslime ile görüştükten sonra şehri Tuğrul Bey’e teslim etti'","sinif":"D"},{"t":"1059-01-01","devlet":"revvadi","taraflar":["buyuk-selcuklu","revvadi"],"b":"Tebriz’de Revvâdî Memlân’ın isyanı — Selçuklu hâkimiyeti sona erdi","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","buyuk-selcuklu","revvadi"],"yer_id":"Tebriz","gun":"1059 (451 h.; yıl — gün/ay kaynaktan alınmadı)","d":"Revvâdîler’den Ebû Nasr Memlân isyan etti; Tuğrul Bey ertesi yıl Tebriz’i kuşattı ama alamadı. Şehir 1062’ye dek Revvâdî elinde kaldı. Bu olayda ilgili yerleşimler: Tebriz.","kaynak":"TDV tebriz: '451’de (1059) Revvâdîler’den Ebû Nasr Memlân’ın isyanı yüzünden ertesi yıl Tebriz’i kuşatan Tuğrul Bey başarılı olamadıysa da 454’te (1062) şehri yeniden Selçuklu topraklarına kattı.'","sinif":"D"},{"t":"1062-01-01","devlet":"revvadi","taraflar":["buyuk-selcuklu","revvadi"],"b":"Tuğrul Bey Tebriz’i yeniden Selçuklu topraklarına kattı","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","buyuk-selcuklu","revvadi"],"yer_id":"Tebriz","gun":"1062 (454 h.; yıl — gün kaynaktan alınmadı)","d":"Kuşatmada başarısız kalan Tuğrul Bey, 1062’de Tebriz’i Revvâdîler’den alıp yeniden Selçuklu topraklarına kattı. Bu olayda ilgili yerleşimler: Tebriz.","kaynak":"TDV tebriz: '451’de (1059) Revvâdîler’den Ebû Nasr Memlân’ın isyanı yüzünden ertesi yıl Tebriz’i kuşatan Tuğrul Bey başarılı olamadıysa da 454’te (1062) şehri yeniden Selçuklu topraklarına kattı.'","sinif":"D"},{"t":"1064-01-01","devlet":"buyuk-selcuklu","taraflar":["kars-vanand-kralligi","buyuk-selcuklu"],"b":"Kars’ta Vanand Prensi Gagik Selçuklu’ya itaat bildirdi — Kars askerî harekât olmadan Selçuklu topraklarına katıldı","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","kars-vanand-kralligi","buyuk-selcuklu"],"yer_id":"Kars","gun":"1064 (456 h.; yıl — gün kaynaktan alınmadı)","d":"Alparslan’ın Ani üzerine hareketi sırasında Kars’ta hüküm süren Vanand Prensi Gagik Selçuklu ailesine itaatini bildirdi; Kars savaşmadan Selçuklu topraklarına katıldı (sonraki sahipler tarihsiz). Bu olayda ilgili yerleşimler: Kars.","kaynak":"TDV kars: '456’da (1064) Alparslan’ın Ani üzerine hareketi esnada Kars’ta hüküm süren Vanand Prensi Gagik, Alparslan’a ve Selçuklu ailesine itaatini bildirdi. Bu suretle Kars herhangi bir askerî harekât olmadan Selçuklu topraklarına katıldı.'","sinif":"D"},{"t":"1071-01-01","devlet":"danismendli","taraflar":["bizans","danismendli"],"b":"Malazgirt sonrası Merzifon İltegin tarafından Bizans’tan fethedildi","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","bizans","danismendli"],"yer_id":"Merzifon","gun":"1071 (463 h.; yıl — gün kaynaktan alınmadı)","d":"Malazgirt Muharebesi’nin ardından Merzifon, Dânişmed emîrlerinden İltegin Gazi tarafından Bizans’tan alındı. Bu olayda ilgili yerleşimler: Merzifon.","kaynak":"TDV merzifon: 'Roma ve Bizans hâkimiyeti devirlerinde Amasya’ya bağlı olan … şehir, Malazgirt Muharebesi (463/1071) sonrasında Dânişmed emîrlerinden İltegin Gazi tarafından fethedildi.'","sinif":"D"},{"t":"1097-01-01","devlet":"harizmsah","taraflar":["buyuk-selcuklu","harizmsah"],"b":"Kutbüddin Muhammed hârizmşah unvanıyla Hârizm valisi oldu — Gürgenç Hârizmşahlar’ın idaresine girdi","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","buyuk-selcuklu","harizmsah"],"yer_id":"Köhne Ürgenç (Gürgenç)","gun":"XI. yüzyılın sonları (yıl 1097 yaklaşıklık BEYANLI — TDV yıl vermez)","d":"Büyük Selçuklu devlet adamlarından Kutbüddin Muhammed b. Anuş Tegin hârizmşah unvanıyla Hârizm’e vali tayin edildi; Gürgenç bu yeni Hârizmşahlar’ın idaresine girdi. Bu olayda ilgili yerleşimler: Köhne Ürgenç (Gürgenç).","kaynak":"TDV gurgenc: 'XI. yüzyılın sonlarında Büyük Selçuklu devlet adamlarından Kutbüddin Muhammed b. Anuş Tegin hârizmşah unvanıyla Hârizm’e vali tayin edilince Gürgenç bu yeni Hârizmşahlar’ın idaresine girdi.'","sinif":"D"},{"t":"1118-05-06","devlet":"irak-selcuklu","taraflar":["buyuk-selcuklu","irak-selcuklu"],"b":"Tebriz, Berkyaruk–Muhammed anlaşmasındaki payıyla Tapar soyunun hâkimiyetine geçti","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","buyuk-selcuklu","irak-selcuklu"],"yer_id":"Tebriz","gun":"6 Mayıs 1118 (Irak Selçuklu Devleti’nin kuruluş günü; Tebriz için gün beyanlı)","d":"Muhammed Tapar’ın ölümüyle (Mayıs 1118) oğlu Mahmud sultan ilân edildi ve Irak Selçuklu Devleti kuruldu; Berkyaruk–Muhammed anlaşmasıyla Muhammed’in payına düşen Tebriz bu kolun önde gelen şehri oldu (1118-1194). Bu olayda ilgili yerleşimler: Tebriz.","kaynak":"TDV tebriz: 'Sultan Berkyaruk ile Muhammed Tapar kardeşler arasındaki anlaşmaya göre Muhammed’e kalan Tebriz, özellikle Irak Selçukluları zamanında (1118-1194) dönemin en önemli yerleşim merkezlerinin başında geliyordu.' · TDV selcuklular: 'Muhammed Tapar’ın ölümü üzerine yerine geçen oğlu Mahmud, 13 Muharrem 512’de (6 Mayıs 1118) Abbâsî Halifesi Müstazhir-Billâh tarafından sultan'","sinif":"D"},{"t":"1127-01-09","devlet":"jin-hanedani","taraflar":["song","jin-hanedani"],"b":"Jurchenler (Jin) Kaifeng’i ele geçirip yağmaladı — Song başkenti Jin’e geçti","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","song","jin-hanedani"],"yer_id":"Kaifeng","gun":"9 Ocak 1127 (Jülyen; Jingkang 1, artık 11. ay, 丙辰)","d":"Juchen (Jin) kuvvetleri Kuzey Çin’i istilâ edip Kaifeng’i 1127’de ele geçirdi ve yağmaladı; şehir Song başkenti olmaktan çıkıp Jin yönetiminde Bianjing, sonra güney başkent oldu. Bu olayda ilgili yerleşimler: Kaifeng.","kaynak":"Tuotuo vd., Song shi, juan 23 «Qinzong ben ji» (zh.wikisource.org/wiki/宋史/卷023) — «丙辰，妖人郭京用六甲法…金兵登城，眾皆披靡。…京城陷。»","sinif":"D","kesinlik":"gun"},{"t":"1130-01-01","devlet":"karahitay","taraflar":["dogu-karahanli","karahitay"],"b":"Karahıtaylar Balasagun ve Kâşgar’ı Hoten ile birlikte zaptetti","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","dogu-karahanli","karahitay"],"yer_id":"Kaşgar","gun":"1130 (1128 + ‘iki yıl sonra’ — TÜRETİLMİŞ yıl; gün kaynaktan alınmadı) / 1130 (yıl — gün kaynaktan alınmadı)","d":"Karahıtaylar 1128’deki ilk saldırılarında Kâşgar’ı alamadılar; iki yıl sonra Balasagun ve Hoten ile birlikte burayı da zaptettiler. XII. yüzyılın ilk çeyreğinde Çu havzasına kadar geniş toprakları istilâ eden Karahıtaylar’ın Gürhanı 1130’da Balasagun’u ele geçirip merkez yaptı. Bu olayda ilgili yerleşimler: Balasagun, Kaşgar.","kaynak":"TDV kasgar: 'Karahıtaylar, 1128’deki ilk saldırılarında Kâşgar’ı alamadılarsa da iki yıl sonra Balasagun ve Hoten ile birlikte burayı da zaptettiler.' · TDV balasagun: 'Bu sırada Gürhan Balasagun’u ele geçirdi (1130) ve orayı merkez yaptı.'","sinif":"D"},{"t":"1141-09-09","devlet":"karahitay","taraflar":["bati-karahanli","karahitay"],"b":"Katvân Savaşı — Buhara Karahıtayların idaresine geçti","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","bati-karahanli","karahitay"],"yer_id":"Buhara","gun":"9 Eylül 1141 (5 Safer 536)","d":"Sultan Sencer’in Karahıtaylar’a yenildiği Katvân Savaşı’ndan sonra Buhara putperest Karahıtaylar’ın idaresine geçti. Bu olayda ilgili yerleşimler: Buhara.","kaynak":"TDV buhara: '5 Safer 536 (9 Eylül 1141) tarihinde meydana gelen Katvân savaşından sonra şehir putperest Karahıtaylar’ın idaresine geçti.'","sinif":"D"},{"t":"1144-01-01","devlet":"begteginli","taraflar":["zengi-musul","begteginli"],"b":"Erbil: Zengî (Musul) iktâsından Begteginliler (Erbil Atabegliği) dönemine","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","zengi-musul","begteginli"],"yer_id":"Erbil","gun":"1144 (yıl — TDV begteginliler başlık yılı)","d":"Zengî’nin 1132’de Ali Küçük b. Begtegin’e iktâ ettiği Erbil’de Begteginliler hânedanı dönemi 1144’ten sayılır; merkez Erbil’dir. Bu olayda ilgili yerleşimler: Erbil.","kaynak":"TDV begteginliler: 'BEGTEGİNLİLER 1144-1232 yılları arasında merkezi Erbil olmak üzere Şehrizor, Hakkâri, Tikrît, Sincar, Harran, Urfa ve civarında hüküm süren bir Türk beyliği.' · TDV erbil: 'Musul Atabeği İmâdüddin Zengî 1132 yılında Erbil’i ele geçirince burayı kumandanlarından Zeynüddin Ali Küçük b. Begtegin’e iktâ etti.'","sinif":"D"},{"t":"1175-01-01","devlet":"gurlu","taraflar":["gazneli","gurlu"],"b":"Gurlu Muizzüddin Muhammed Mültan’da kesin hâkimiyet kurdu","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","gazneli","gurlu"],"yer_id":"Multan","gun":"1175 (571 h. = 1175-76; yıl — gün kaynaktan alınmadı)","d":"Gurlular’dan Muizzüddin Muhammed b. Sâm, Gazneliler devrinin sonlarında Mültan bölgesinde kesin Sünnî hâkimiyetini tesis etti. Bu olayda ilgili yerleşimler: Multan.","kaynak":"TDV multan: 'Nihayet 571’de (1175-76) Gurlular’dan Muizzüddin Muhammed b. Sâm bölgede kesin Sünnî hâkimiyetini tesis etti.'","sinif":"D"},{"t":"1178-01-01","devlet":"selcuklu","taraflar":["danismendli","selcuklu"],"b":"Dânişmendli ilhakı tamamlandı: Merzifon çevresi II. Kılıcarslan’ın Anadolu yönetiminde","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","danismendli","selcuklu"],"yer_id":"Merzifon","gun":"1178 (574 h.; yıl — Merzifon’a özel cümle yok, Amasya ilhakından)","d":"II. Kılıcarslan Dânişmendli topraklarını Selçuklu Devleti’ne kattı; Amasya’ya bağlı Merzifon da Selçuklu hâkimiyetine girdi (Merzifon için yaklaşıklık beyanlı). Bu olayda ilgili yerleşimler: Merzifon.","kaynak":"TDV selcuklular: '574’te (1178) Dânişmendli topraklarının Selçuklu topraklarına katılmasıyla' · TDV amasya: 'Kılıcarslan (1155-1192) tarafından ilhakına kadar devam etti' · BEYAN: Merzifon Amasya’ya bağlı bir yerleşimdir (TDV merzifon: 'Roma ve Bizans hâkimiyeti devirlerinde Amasya’ya bağlı'); 1178 tarihi Amasya ilhakından alındı, Merzifon’a özel cümle yok — YAKLAŞIKLIK BEYANLI","sinif":"D"},{"t":"1187-01-01","devlet":"kirman-selcuklu","taraflar":["kirman-selcuklu"],"b":"Kirman Selçuklu hânedanı sona erdi — Oğuz Beyi Melik Dinar Kirman’ı ele geçirdi","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","kirman-selcuklu"],"yer_id":"Kirman","gun":"1187 (583 h.; yıl — gün kaynaktan alınmadı)","d":"Oğuz Beyi Melik Dinar Kirman Selçuklu Devleti’ne son verip bölgeyi ele geçirdi; Kirman şehri künyesi olmayan Oğuz yönetimine girdi. Bu olayda ilgili yerleşimler: Kirman.","kaynak":"TDV kirman: '583’te (1187) Kirman Selçuklu Devleti’ne son veren Oğuz Beyi Melik Dinar bölgeyi ele geçirdi; ardından Karahıtay asıllı Barak Hâcib 619’da (1222) buraya hâkim oldu'","sinif":"D"},{"t":"1206-01-01","devlet":"kabace","taraflar":["gurlu","kabace"],"b":"Mültan’da Nâsırüddin Kabâce’nin bağımsız idaresi başladı (Delhi Sultanlığı’nın başları)","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","gurlu","kabace"],"yer_id":"Multan","gun":"1206 (TÜRETİLMİŞ yıl: 22 yıllık idare, 1228’de biter)","d":"Delhi Sultanlığı’nın başlarında Mültan, bağımsız bir idare kuran ve yirmi iki yıl hüküm süren Nâsırüddin Kabâce’nin idaresinde kaldı. Bu olayda ilgili yerleşimler: Multan.","kaynak":"TDV multan: 'Delhi Sultanlığı döneminin başlarında Mültan bölgesi, zamanla bağımsız bir idare kuran ve yirmi iki yıl hüküm süren Nâsırüddin Kabâce’nin idaresinde kaldı'","sinif":"D"},{"t":"1207-01-01","devlet":"harizmsah","taraflar":["karahitay","harizmsah"],"b":"Buhara Karahıtaylardan Hârizmşah Muhammed b. Tekiş’in idaresine girdi","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","karahitay","harizmsah"],"yer_id":"Buhara","gun":"1207 (604 h.; yıl — gün kaynaktan alınmadı)","d":"1207’de Buhara’da Şiîler’in başlattığı halk ayaklanmasında Burhan ailesi Karahıtaylar’a sığındı; aynı yıl şehir Hârizmşah Muhammed b. Tekiş’in idaresi altına girdi. Bu olayda ilgili yerleşimler: Buhara.","kaynak":"TDV buhara: 'Burhan ailesi 604 (1207) yılında Şiîler’in başlattığı bir halk ayaklanması sırasında Karahıtaylar’a sığındı. Aynı yıl şehir Hârizmşah Muhammed b. Tekiş’in idaresi altına girdi.'","sinif":"D"},{"t":"1209-01-09","devlet":"salgurlu","taraflar":["salgurlu"],"b":"Salgurlu Atabeg Sa‘d Kirman’ın başşehri Berdesîr’de Kavurd’un tahtına oturdu","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","salgurlu"],"yer_id":"Kirman","gun":"9 Ocak 1209 (1 Receb 605)","d":"Fars Salgurlu atabegi Sa‘d, Kirman’ın başşehri Berdesîr’e gidip Kavurd’un tahtına oturdu; beş aya yakın Kirman’da kalıp bölgenin büyük kısmını itaat altına aldı. Bu olayda ilgili yerleşimler: Kirman.","kaynak":"TDV salgurlular: 'Sa‘d ardından Kirman’ın başşehri Berdesîr’e gidip Kavurd’un tahtına oturdu (1 Receb 605 / 9 Ocak 1209).'","sinif":"D"},{"t":"1211-01-01","devlet":"karahitay","taraflar":["karahitay"],"b":"Nayman Güçlüg Karahıtay Gürhanını devirdi — Balasagun ve Kâşgar künyesiz Güçlüg yönetiminde","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","karahitay"],"yer_id":"Kaşgar","gun":"1211 (Karahıtay künye sonu; Güçlüg darbesinin yılı TDV mogollar’da verilmiyor — yıl künyeden)","d":"Nayman Tayang Han’ın oğlu Güçlüg Karahıtay Gürhanını devirip ülkeye hâkim oldu; Kâşgar–Balasagun bölgesi Karahıtay yönetiminden çıktı. Nayman Tayang Han’ın oğlu Güçlüg Karahıtay Gürhanını devirip ülkeye hâkim oldu; Balasagun Karahıtay yönetiminden çıktı. Bu olayda ilgili yerleşimler: Balasagun, Kaşgar.","kaynak":"TDV mogollar (repo 1218 maddesi): 'Nayman Tayang Han’ın oğlu Güçlüg Karahıtay Gürhanını devirip ülkeye hâkim olmuştu.'","sinif":"D"},{"t":"1212-01-01","devlet":"harizmsah","taraflar":["bati-karahanli","harizmsah"],"b":"Hârizmşah Muhammed Semerkant’ı zaptetti — Batı Karahanlılar yıkıldı","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","bati-karahanli","harizmsah"],"yer_id":"Semerkant","gun":"1212 (yıl — gün kaynaktan alınmadı)","d":"Hârizmşah Muhammed b. Tekiş Semerkant’ı zaptedip damadı olan Semerkant hükümdarı Osman’ı öldürttü; Batı Karahanlılar yıkıldı ve Semerkant Hârizmşahlar’ın başşehri oldu. Bu olayda ilgili yerleşimler: Semerkant.","kaynak":"TDV muhammed-b-tekis: 'Semerkant’ı zaptedip damadı olan Semerkant Hükümdarı Osman’ı öldürtmek suretiyle Karahanlılar’ın (1212) … yıkılmasını sağladı.' · TDV karahanlilar: 'Osman’ın Semerkant’ta çıkan isyanda Hârizmliler’i kılıçtan geçirmesine öfkelenen Hârizmşah Muhammed Semerkant’ı ele geçirip katliam emrini verdi'","sinif":"D"},{"t":"1213-01-01","devlet":"harizmsah","taraflar":["salgurlu","harizmsah"],"b":"Kirman Salgurlulardan Hârizmşahlar’a geçti","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","salgurlu","harizmsah"],"yer_id":"Kirman","gun":"1213 (610 h.; yıl — gün kaynaktan alınmadı)","d":"Salgurlular’ın ihmal ettiği Kirman Hârizmşahlar’ın eline geçti. Bu olayda ilgili yerleşimler: Kirman.","kaynak":"TDV salgurlular: 'Ancak bölge daha sonra ihmal edilince Hârizmşahlar’ın eline geçti (610/1213).'","sinif":"D"},{"t":"1218-01-01","devlet":"mogol-imparatorlugu","taraflar":["karahitay","mogol-imparatorlugu"],"b":"Cebe Noyan Güçlüg’ün Karahıtay topraklarını aldı — Balasagun ve Kâşgar Moğollara geçti","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","karahitay","mogol-imparatorlugu"],"yer_id":"Kaşgar","gun":"1218 (gün/ay bilinmiyor)","d":"Cengiz Han’ın kumandanı Cebe Noyan 1218’de Güçlüg’ün elindeki Karahıtay topraklarını ele geçirdi; Kâşgar Moğol İmparatorluğu’na geçti. Cengiz Han’ın kumandanı Cebe, Balasagun’u kolayca zaptetti; Cengiz hânedanı ile akrabalık kuruldu (1218). Bu olayda ilgili yerleşimler: Balasagun, Kaşgar.","kaynak":"TDV kasgar: 'Cengiz Han’ın Cebe Noyan kumandasında gönderdiği kuvvetlerin şehri ele geçirmesiyle (1218) birlikte ibadetler serbest bırakıldı.' · TDV mogollar (repo maddesi): 'Cengiz Han’ın kumandanı Cebe Noyan 1218’de bu toprakları ele geçirdi' · TDV balasagun: 'Cengiz hânedanı ile akrabalık kurulmuş (1218), Almalığ Meliki Buzar Han burayı da birlikte yönetmiştir. Moğollar batıya giderken Cengiz’in kumandanı Cebe Balasagun’u kolayca zaptetmiş' · TDV mogollar (repo maddesi): 'Cebe Noyan 1218’de bu toprakları ele geçirdi'","sinif":"D"},{"t":"1220-02-10","devlet":"mogol-imparatorlugu","taraflar":["harizmsah","mogol-imparatorlugu"],"b":"Buhara Moğollara teslim oldu — Hârizmşah hâkimiyeti sona erdi","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","harizmsah","mogol-imparatorlugu"],"yer_id":"Buhara","gun":"10 Şubat 1220 (4 Zilhicce 616)","d":"Cengiz Han’ın orduları Buhara’yı işgal edip yağmaladı; şehir Hârizmşahlar’ın elinden Moğol İmparatorluğu’na geçti. Bu olayda ilgili yerleşimler: Buhara.","kaynak":"TDV buhara: 'Şehir 4 Zilhicce 616 (10 Şubat 1220) tarihinde Moğol orduları tarafından işgal edilip yağmalandı.' · TDV cengiz-han (repo maddesi 1220-02-10)","sinif":"D"},{"t":"1221-01-01","devlet":"mogol-imparatorlugu","taraflar":["harizmsah","mogol-imparatorlugu"],"b":"Gürgenç kuşatmayı birkaç ay savundu ve düştü; şehir yakılıp sular altında bırakıldı","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","harizmsah","mogol-imparatorlugu"],"yer_id":"Köhne Ürgenç (Gürgenç)","gun":"1221 (618 h.; Nisan 1221 — gün kaynaktan alınmadı)","d":"Moğollar kuşattıkları Hârizmşah başşehri Gürgenç’e girdiler, yakıp yıktılar ve Amuderya bentlerini açtılar; Gürgenç harabeye döndü. Bu olayda ilgili yerleşimler: Köhne Ürgenç (Gürgenç).","kaynak":"TDV gurgenc: 'Sonunda şehre giren Moğollar yakaladıklarını öldürdüler ve şehri yakıp yıktılar; Amuderya bentlerini açarak her tarafı sular altında bıraktılar. Gürgenç harabeye döndü; … (618/1221).'","sinif":"D"},{"t":"1222-01-01","devlet":"kutlughanli","taraflar":["harizmsah","kutlughanli"],"b":"Barak Hâcib Kirman’a hâkim oldu — Kutluğhanlılar kuruldu","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","harizmsah","kutlughanli"],"yer_id":"Kirman","gun":"1222 (619 h.; yıl — gün kaynaktan alınmadı)","d":"Karahıtay asıllı Barak Hâcib (Kutluğ Han) Kirman’a hâkim oldu ve Kutluğhanlılar hânedanını kurdu; Kirman Hârizmşah hâkimiyetinden çıktı. Bu olayda ilgili yerleşimler: Kirman.","kaynak":"TDV kutlughanlilar: 'Kutluğ Han unvanıyla meşhur olan Barak ertesi yıl Kirman’a hâkim oldu ve Kutluğhanlılar adıyla bilinen hânedanı kurdu.' · TDV kirman: 'Karahıtay asıllı Barak Hâcib 619’da (1222) buraya hâkim oldu'","sinif":"D"},{"t":"1225-01-01","devlet":"tran-hanedani","taraflar":["ly-hanedani","tran-hanedani"],"b":"Lý hanedanının yerini Trần hanedanı aldı — Thăng Long (Hanoi) Trần başkenti","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","ly-hanedani","tran-hanedani"],"yer_id":"Hanoi (Thăng Long)","gun":"1225 (yıl — Britannica; gün/ay verilmiyor)","d":"Lý hanedanı (1009-1225) iç karışıklıklardan sonra yerini 1225-1400 arası hüküm süren Trần hanedanına bıraktı; Trần başkenti Hanoi’ydi (1257’de Moğollarca yağmalandı). Bu olayda ilgili yerleşimler: Hanoi (Thăng Long).","kaynak":"Britannica, «Tran dynasty»: 'It was succeeded, after a period of civil strife, by a new dynasty called the Tran, which reigned from 1225 to 1400.' · 'The Tran dynastic capital at Hanoi was sacked in 1257'","sinif":"D"},{"t":"1227-01-01","devlet":"cagatay","taraflar":["mogol-imparatorlugu","cagatay"],"b":"Cengiz Han ülkesini oğulları arasında paylaştırdı — Yedisu (Balasagun) Çağatay Hanlığı’na düştü","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","mogol-imparatorlugu","cagatay"],"yer_id":"Balasagun (Ak-Beşim)","gun":"1227 (yıl — gün kaynaktan alınmadı)","d":"Cengiz Han’ın ölümünden sonra ülke oğulları arasında taksim edildi; Mâverâünnehir, Yedisu ve Doğu Türkistan’ı kapsayan Çağatay Hanlığı (1227-1370) kuruldu. Bu olayda ilgili yerleşimler: Balasagun (Ak-Beşim).","kaynak":"TDV cagatay-hanligi: 'ÇAĞATAY HANLIĞI 1227-1370 yılları arasında Mâverâünnehir, Yedisu ve Doğu Türkistan’da hüküm süren bir hânedan.' · TDV kasgar: 'Cengiz Han, Moğol törece ülkesini oğulları arasında taksim edince Kâşgar Çağatay Han’ın payına düştü (1227).'","sinif":"D"},{"t":"1228-01-01","devlet":"delhi-sultanligi","taraflar":["kabace","delhi-sultanligi"],"b":"İltutmış Mültan’ı Delhi Sultanlığı’nın eyalet merkezi yaptı — Kabâce dönemi sona erdi","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","kabace","delhi-sultanligi"],"yer_id":"Multan","gun":"1228 (626 h.; yıl — gün kaynaktan alınmadı)","d":"Sultan İltutmış 1228’de Mültan’ı eyalet merkezi yaptı; Nâsırüddin Kabâce’nin bağımsız idaresi sona erdi. Bu olayda ilgili yerleşimler: Multan.","kaynak":"TDV multan: '626 (1228) yılında Sultan İltutmış burayı eyalet merkezi yaptı.'","sinif":"D"},{"t":"1232-06-29","devlet":"abbasi","taraflar":["begteginli","abbasi"],"b":"Kökböri öldü — Erbil Abbâsî Halifesi Müstansır-Billâh’ın eline geçti","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","begteginli","abbasi"],"yer_id":"Erbil","gun":"29 Haziran 1232","d":"Erbil Atabeği Muzafferüddin Kökböri, halef olabilecek erkek evladı olmadan 29 Haziran 1232’de Erbil’de öldü; Erbil bölgesi vasiyet yoluyla Abbâsî Halifesi’ne geçti. Bu olayda ilgili yerleşimler: Erbil.","kaynak":"TDV begteginliler: 'Kendisine halef olabilecek bir erkek evladı olmayan Kökböri 29 Haziran 1232’de Erbil’de öldü.' · TDV erbil: 'Oğlu olmayan Kökböri’nin ölümü üzerine Erbil bölgesi vasiyet yoluyla Abbâsî Halifesi Müstansır-Billâh’ın eline geçti (1232).'","sinif":"D"},{"t":"1234-01-01","devlet":"mogol-imparatorlugu","taraflar":["jin-hanedani","mogol-imparatorlugu"],"b":"Kaifeng Moğol işgaline girdi — Jin hâkimiyeti sona erdi","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","jin-hanedani","mogol-imparatorlugu"],"yer_id":"Kaifeng","gun":"1234 (yıl — Britannica ‘Mogol işgali 1234’ten’; gün/ay verilmiyor)","d":"Jin sarayının çekildiği Kaifeng, Moğol işgaline girdi; Moğol işgali 1234’ten 1368’e kadar sürdü ve şehir Henan eyalet yönetiminin merkezi oldu. Bu olayda ilgili yerleşimler: Kaifeng.","kaynak":"Tuotuo vd., Jin shi, juan 18 «Aizong ben ji xia» (zh.wikisource.org/wiki/金史/卷18) — «戊辰，安平都尉、京城西面元帥崔立…舉兵為亂…遂送款大元軍前。»","sinif":"D"},{"t":"1242-01-01","devlet":"altinorda","taraflar":["mogol-imparatorlugu","altinorda"],"b":"Gürgenç/Hârizm Cuci ulusunda — Batu Han’ın Altın Orda’sı","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","mogol-imparatorlugu","altinorda"],"yer_id":"Köhne Ürgenç (Gürgenç)","gun":"1242 (yıl = Altın Orda künye başlangıcı; Hârizm’in Cuci’ye ‘yemlik’ verilişi TDV batu-han)","d":"Cengiz Han Hârizm’i Cuci Han’a yemlik olarak vermişti; Batu Han döneminde Ürgenç gibi Hârizm şehirleri Altın Orda hâkimiyetinde yeniden ticarî canlılık kazandı. Bu olayda ilgili yerleşimler: Köhne Ürgenç (Gürgenç).","kaynak":"TDV batu-han: 'Cengiz Han da, Batu’nun babası Cuci Han’a Doğu Deştikıpçak’ı yurt ve Hârizm’i de “yemlik” olarak vermişti.' · 'Hâkimiyeti altına giren Kırım, Bulgar, Kuzey Kafkasya, Hârizm ülkelerinin … Batu Han'","sinif":"D"},{"t":"1258-02-10","devlet":"ilhanli","taraflar":["abbasi","ilhanli"],"b":"Hülâgû’nun 1258 zaferinin ardından Erbil zaptedildi (İlhanlı)","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","abbasi","ilhanli"],"yer_id":"Erbil","gun":"1258 (ay düzeyi; gün komşudan: Bağdat 10 Şubat 1258 — Erbil zaptı bu günden sonra, gün kaynaktan alınmadı)","d":"Hülâgû 1258’de Bağdat’ı alınca Abbâsî elindeki Erbil de zaptedildi (1236’daki Moğol kuşatması başarısız kalmıştı). Bu olayda ilgili yerleşimler: Erbil.","kaynak":"TDV erbil: '1236 yılında Erbil’e saldıran Moğollar aşağı şehri işgal ederek binaları yıkıp kaleyi kuşattılarsa da sonuçta geri çekilmek zorunda kaldılar; ancak Bağdat’ın 1258’de Hülâgû’nun eline geçmesinden sonra burası da zaptedildi.'","sinif":"D"},{"t":"1260-01-01","devlet":"cagatay","taraflar":["mogol-imparatorlugu","cagatay"],"b":"Algu Çağatay hanı oldu — Buhara’nın da içinde olduğu Mâverâünnehir Çağatay Hanlığı’na bağlandı","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","mogol-imparatorlugu","cagatay"],"yer_id":"Buhara","gun":"1260 (aralık 1260-1266; yıl başı temsilî — ay/gün kaynakta yok)","d":"Büyük Kağan Mengü’nün 1259’da ölümünden sonra Kubilay ile Arık-Buka arasındaki taht mücadelesinde Algu, Mâverâünnehir hâkimi Mesud Yalvaç’ı görevinde bırakıp Çağatay hanı oldu (1260-1266); Mâverâünnehir Moğol İmparatorluğu’ndan Çağatay Hanlığı’na geçti. Bu olayda ilgili yerleşimler: Buhara.","kaynak":"TDV cagatay-hanligi: 'Algu … Mâverâünnehir hâkimi Mesud Yalvaç’ı da eski görevine iade etmek suretiyle meseleyi çözdü ve Çağatay hanı oldu (1260-1266).'","sinif":"D"},{"t":"1260-01-01","devlet":"yuan-hanedani","taraflar":["mogol-imparatorlugu","yuan-hanedani"],"b":"Mengü’nün ölümünden sonra Moğol İmparatorluğu bölündü — Kubilay Kağan (1260-1294) Çin’i ele geçirdi (Kaifeng)","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","mogol-imparatorlugu","yuan-hanedani"],"yer_id":"Kaifeng","gun":"1260 (yıl; Moğol İmparatorluğu künye sonu — ay/gün kaynakta yok)","d":"Büyük Kağan Mengü’nün 1259’daki ölümünden sonra Kubilay ile Arık-Buka taht mücadelesi sürerken bölünmüş Moğol İmparatorluğu’nun Çin kolunda Kubilay Kağan (1260-1294) bütün Çin’i ele geçirdi; Kaifeng’in bağlı olduğu Moğol İmparatorluğu dönemi 1260’ta kapanır, Yuan künyesi 1271’de başlar. Bu olayda ilgili yerleşimler: Kaifeng.","kaynak":"TDV mogollar: 'Kubilay Kağan (1260-1294) çetin savaşların ardından nihayet bütün Çin’i ele geçirdi.' · TDV cagatay-hanligi: '1259’da Büyük Kağan Mengü’nün ölümünden sonra kardeşleri Kubilay ile Arık-Buka taht mücadelesini sürdürürken'","sinif":"D"},{"t":"1276-02-04","devlet":"yuan-hanedani","taraflar":["song","yuan-hanedani"],"b":"Güney Song başkenti Hangzhou (Lin’an) Kubilay’ın Moğol güçlerince alındı","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","song","yuan-hanedani"],"yer_id":"Hangzhou","gun":"4 Şubat 1276 (Jülyen; Deyou 2, 1. ay, 甲申 — Song sarayı devlet mührünü teslim etti)","d":"Güney Song’un 1132’den beri başkenti olan Hangzhou, 1276’da Kubilay Han tarafından alınıp yağmalandı; Song hâkimiyeti sona erdi, şehir Yuan hâkimiyetine geçti. Bu olayda ilgili yerleşimler: Hangzhou.","kaynak":"Tuotuo vd., Song shi, juan 47 «Gong di ji» (zh.wikisource.org/wiki/宋史/卷047) — «甲申，大元兵至皋亭山，遣監察御史楊應奎上傳國璽降»","sinif":"D","kesinlik":"gun"},{"t":"1306-01-01","devlet":"ilhanli","taraflar":["kutlughanli","ilhanli"],"b":"II. Kutbüddin Olcaytu Han tarafından görevden alındı — Kirman İlhanlı valisine bağlandı, Kutluğhanlı hânedanı sona erdi","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","kutlughanli","ilhanli"],"yer_id":"Kirman","gun":"1306 (706 h.; TDV 706/1306-1307 — gün kaynaktan alınmadı)","d":"İlhanlı hazinesine vergi göndermeyen II. Kutbüddin b. Soyurgatmış Olcaytu Han tarafından görevinden alındı, Nâsırüddin Muhammed b. Burhân vali tayin edildi; Barak Hâcib soyundan gelenler bir daha Kirman tahtına geçemedi, ülke İlhanlı valilerince yönetildi. Bu olayda ilgili yerleşimler: Kirman.","kaynak":"TDV kutlughanlilar: II. Kutbüddin b. Soyurgatmış, İlhanlı hazinesine vergi göndermediği için Olcaytu Han tarafından görevinden alındı ve Nâsırüddin Muhammed b. Burhân vali tayin edildi (706/1306-1307). · TDV kirman: Kutluğhanlılar’ın Kirman hâkimiyeti İlhanlı tâbiiyetinde 706 (1306-1307) yılına kadar sürdü.","sinif":"D"},{"t":"1291-07-14","devlet":"memluk","taraflar":["kudus-kralligi","memluk"],"b":"Sûr (Tyre) Memlüklere teslim oldu — Haçlıların Suriye kıyısındaki son şehirlerinden biri","tur":"toprak-kazanc","onem":3,"dunya":3,"kapsam":"dis","etiket":["sinir","konu-siyasi","konu-askeri","kudus-kralligi","memluk"],"yer_id":"Sûr (Tyre) — Lübnan","gun":"14 Temmuz 1291 (TDV sur--lubnan; gün kesin)","d":"Akkâ’nın 18 Mayıs 1291’de düşmesinin ardından Memlük Sultanı el-Eşref Halîl 14 Temmuz 1291’de Sûr’u ele geçirdi; halkın bir kısmı öldürüldü, kalanlar esir alındı, şehir tamamen tahrip edildi. Bu olayda ilgili yerleşimler: Sûr (Tyre) — Lübnan.","kaynak":"TDV sur--lubnan: Memlük Sultanı Halîl b. Kalavun 18 Mayıs 1291’de Akkâ’ya hâkim olduktan sonra 14 Temmuz 1291’de Sûr’u da ele geçirdi.","sinif":"D"},{"t":"1250-04-05","devlet":"merini","taraflar":["muvahhidler","merini"],"b":"Merînîler Fas şehrini Muvahhidler’den aldı — Fas Merînî idaresine geçti","tur":"toprak-kazanc","onem":3,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-askeri","muvahhidler","merini"],"yer_id":"Fas (Fez)","gun":"648 (1250) — TDV fas--fas; gün yok (648 H = 1250-04-05..1251-03-25 Jülyen ∩ 1250)","d":"TDV fas--fas şehir maddesine göre 648’den (1250) itibaren Merînîler’in idaresine geçen Fas tekrar başşehir olarak seçildi. Bu olayda ilgili yerleşimler: Fas (Fez).","kaynak":"TDV fas--fas: 648’den (1250) itibaren Merînîler’in idaresine geçen Fas tekrar başşehir olarak seçildi.","sinif":"D"},{"t":"1340-06-27","devlet":"muzafferi","taraflar":["ilhanli","muzafferi"],"b":"Muzafferî Mübârizüddin Muhammed Kirman'ı ele geçirdi — şehir İlhanlı valilerinden Muzafferîlere geçti","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","muzafferi","ilhanli"],"yer_id":"Kirman","yer":"Kirman","gun":"741 H. (1340-41) — hicrî yılın ilk günü (Jülyen 1340-06-27); gün kaynaktan alınmadı","d":"Kutluğhanlı tahtından indirilen II. Kutbüddin'in kızıyla evlenen Muzafferî hânedanının gerçek kurucusu Mübârizüddin Muhammed 741'de (1340-41) Kirman'ı ele geçirdi; 1306'dan beri şehri İlhanlı tayinli valiler yönetiyordu. Bu olayda ilgili yerleşimler: Kirman.","kaynak":"TDV kirman: 'Kirman 741’de (1340-41) Muzafferîler hânedanının kurucusu Muzafferüddin tarafından ele geçirildi.' · TDV kutlughanlilar: 'Muzafferîler’in gerçek kurucusu olan Mübârizüddin Muhammed ile evlenmiş ve 741’de (1340-41) Kirman’ı ele geçirmiştir.'","sinif":"D"},{"t":"1353-01-01","devlet":"gilan-kiya","taraflar":["ilhanli","gilan-kiya"],"b":"Gîlân'da (Lâhîcan, Bender Enzeli, Reşt) harita sahibi Kârkiyâ'dır — yerel hânedan 1353'ten itibaren (yaklaşıklık)","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","ilhanli","gilan-kiya","yaklasik"],"yer_id":"Lâhîcan","yer":"Lâhîcan · Bender Enzeli · Reşt (Gîlân)","gun":"1353 (yıl; TDV ilhanlilar 1256-1353)","d":"İlhanlı Devleti 1353'te son buldu (son ilhan Nûşirevân 1344-1353); Ebû Said'in 1335'teki ölümünden beri bölgede 'mahallî hânedanlar' İlhanlı'nın yerini almıştı. Gîlân'da (Lâhîcan, Bender Enzeli, Reşt) 1353'ten Safevî fethine (1592) dek harita sahibi Kârkiyâ hânedanıdır; hanedanın iktidarı kesin olarak 1370'lerde (künye f 1371) kaynaklıdır, ondan önceki yıllar BEYANLI YAKLAŞIKLIKtır.","kaynak":"TDV ilhanlilar: 'İran’da kurulan bir Moğol devleti (1256-1353)'; 'Ebû Said’in vâris bırakmadan ölümü İlhanlı Devleti’nin parçalanmasına ve yerini mahallî hânedanların almasına yol açtı'. · TDV gilan: Olcaytu 706'da (1306) Gîlân'ı kattıysa da 'burada tutunamadı ve ertesi yıl bölgeden uzaklaştı. Bölgeye Kârkiyâ hânedanı hâkim oldu.' · Encyclopaedia Iranica 'KIĀ (KĀR KIĀ)': dynasty 'came to power in the 770s/1370s'.","sinif":"D"},{"t":"1353-01-01","devlet":"mazenderan-marasi","taraflar":["ilhanli","mazenderan-marasi"],"b":"Mâzenderan'da (Sârî, Âmül, Bârfurûş, Eşref) 1353'ten sonra Mar'aşî seyyidleri sahip sayıldı (yaklaşıklık)","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","ilhanli","mazenderan-marasi","yaklasik"],"yer_id":"Sârî","yer":"Sârî · Âmül · Bârfurûş · Eşref (Mâzenderan)","gun":"1353 (yıl; TDV ilhanlilar 1256-1353)","d":"İlhanlı Devleti 1353'te son buldu; Ebû Said'in 1335'teki ölümünden beri Mâzenderan'ı yerel hâkimler (Kiyâ Efrâsiyâb) yönetiyordu. Seyyid Kıvâmüddin Kiyâ Efrâsiyâb'ı yenip Âmül'e girince (760/1359) Mar'aşî hâkimiyeti kesinleşti; 1353-1359 arası BEYANLI YAKLAŞIKLIKla Mar'aşîlere bağlandı.","kaynak":"TDV ilhanlilar: 'İran’da kurulan bir Moğol devleti (1256-1353)'; 'yerini mahallî hânedanların almasına yol açtı'. · TDV marasiler: 'bölgenin mahallî hâkimi Kiyâ Efrâsiyâb … Dâbû yakınlarında … yenilerek öldürüldü (760/1359). Zaferin ardından Seyyid Kıvâmüddin Âmül’e girdi ve burada siyasî hâkimiyetini tesis etti.'","sinif":"D"},{"t":"1353-01-01","devlet":"eretna","taraflar":["ilhanli","eretna"],"b":"Erzurum, Pasinler ve Aşkale yöresi 1353'ten itibaren Eretna nüfuzunda sayıldı (yaklaşıklık)","tur":"toprak-kazanc","onem":2,"dunya":2,"kapsam":"dis","etiket":["sinir","sinif-d","konu-siyasi","ilhanli","eretna","yaklasik"],"yer_id":"Erzurum","yer":"Erzurum · Pasinler (Hasankale) · Aşkale","gun":"1353 (yıl; TDV ilhanlilar 1256-1353)","d":"İlhanlı Devleti 1353'te son buldu; TDV'ye göre Erzurum 1335'ten sonra yerel beylerin (Hacı Togay 1336, Şeyh Hasan 1340) mücadele sahası oldu ve 1360'ta Eretnaoğulları'nın ve Erzincan valisi Mutahharten'in nüfuzu altına girdi. 1353-1360 arası kaynakta adlı sahip yoktur; Eretna'ya BEYANLI YAKLAŞIKLIK.","kaynak":"TDV ilhanlilar: 'İran’da kurulan bir Moğol devleti (1256-1353)'. · TDV erzurum: 'Anadolu Selçuklu Devleti’nin yıkılmasından (1308) sonra İlhanlılar’a bağlandıysa da bu devletin parçalanmasının (1335) ardından en karışık dönemini yaşadı … Hacı Togay’ın eline geçti (1336). … Şeyh Hasan 1340’ta Erzurum’a gelerek … Erzurum 1360’ta Eretnaoğulları’nın ve onların Erzincan valisi olan Mutahharten’in nüfuzu altına girdi.'","sinif":"D"}];

