window.KRONOLOJI_SINIR_AMERIKA_AFRIKA3 = [{"t":"0682-04-23","gun":"23 Nisan 682 (Coedès)","kesinlik":"gun","devlet":"srivijaya","taraflar":["srivijaya"],"devletler":["srivijaya"],"b":"Kedukan Bukit yazıtı: Srivicaya kralı Palembang'dan deniz-kara seferine (siddhayatra) çıktı","tur":"sefer","onem":3,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Palembang"],"etiket":["srivijaya","konu-siyasi"],"d":"Palembang'daki en eski yazıt, bir kralın 23 Nisan 682'de tekneyle siddhayatra seferine başladığını, 19 Mayıs'ta bir nehir ağzından kara ve deniz ordusuyla ayrıldığını kaydeder; sefer Srivicaya'ya yeni güç ve itibar kazandırdı.","kaynak":"G. Coedès, The Indianized States of Southeast Asia, ed. Walter F. Vella, çev. Susan Brown Cowing, Honolulu: East-West Center Press, 1968 (archive.org/details/theindianizedstatesofsoutheastasia; tam metin bu oturumda okundu), «Srivijaya» bölümü (Kedukan Bukit yazıtı, I-ching'in Shih-li-fo-shih'i ile eşleşme)"},{"t":"0686-02-28","gun":"28 Şubat 686 (Coedès)","kesinlik":"gun","devlet":"srivijaya","taraflar":["srivijaya"],"devletler":["srivijaya"],"b":"Srivicaya yazıtı (28 Şubat 686): Batang Hari ve Bangka halkına itaat ve lanet tehdidi","tur":"siyaset","onem":2,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Palembang","Jambi"],"etiket":["srivijaya","konu-siyasi"],"d":"Üç yazıttan biri 28 Şubat 686 tarihlidir; metinler Malayu havzası (Cambi, yukarı Batang Hari) ve Bangka adası sakinlerini krala ve eyalet görevlilerine itaatsizliğe karşı tehdit eder; Kedukan Bukit'in fetih siyasetinin devamı olarak okunur.","kaynak":"G. Coedès, The Indianized States of Southeast Asia, ed. Walter F. Vella, çev. Susan Brown Cowing, Honolulu: East-West Center Press, 1968 (archive.org/details/theindianizedstatesofsoutheastasia; tam metin bu oturumda okundu), «Srivijaya» bölümü (686 yazıtları, Bangka yazıtı)"},{"t":"0942-01-01","gun":"942 (Coedès)","kesinlik":"yil","devlet":"srivijaya","taraflar":["srivijaya","medang"],"devletler":["srivijaya","medang"],"b":"Srivicaya batı Cava'da Sunda'dan bir prensi yeniden tahta çıkardı (942)","tur":"siyaset","onem":2,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Palembang"],"etiket":["srivijaya","konu-siyasi"],"d":"Sindok'un başkenti doğuya taşımasının sonucu olarak Sumatra krallığı Cava'nın batısına yeniden müdahale etti ve 942'de bir Sunda prensini tahta oturttu.","kaynak":"G. Coedès, The Indianized States of Southeast Asia, ed. Walter F. Vella, çev. Susan Brown Cowing, Honolulu: East-West Center Press, 1968 (archive.org/details/theindianizedstatesofsoutheastasia; tam metin bu oturumda okundu), «The Javanese Kingdom of Mataram» bölümü (Sindok)"},{"t":"0960-01-01","gun":"960 (Coedès, Sung Tarihi)","kesinlik":"yil","devlet":"srivijaya","taraflar":["srivijaya"],"devletler":["srivijaya"],"b":"Sung Tarihi 960'ta Srivicaya kralı Sri Udayadityavarman'dan söz eder; 971-983 arası elçilikler","tur":"siyaset","onem":2,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Palembang"],"etiket":["srivijaya","konu-siyasi"],"d":"Çin kaynağı (Sung Tarihi) 960'ta Si-li Hu-ta-hsia-li-tan ve 962'de Shih-li Wu-yeh adlı kralları anar; Coedès iki adı Sri Udayadityavarman olarak okur. 971, 972, 974, 975 elçilikleri kral adı vermez; 980 ve 983 elçilikleri 'Haji' unvanlı kraldan gelir.","kaynak":"G. Coedès, The Indianized States of Southeast Asia, ed. Walter F. Vella, çev. Susan Brown Cowing, Honolulu: East-West Center Press, 1968 (archive.org/details/theindianizedstatesofsoutheastasia; tam metin bu oturumda okundu), «San-fo-ch'i, or the Sumatran Kingdom of Srivijaya» bölümü"},{"t":"0992-01-01","gun":"992 (Coedès)","kesinlik":"yil","devlet":"srivijaya","taraflar":["srivijaya","medang"],"devletler":["srivijaya","medang"],"b":"Cava ve Srivicaya elçileri Çin sarayına Cava'nın San-fo-ch'i'yi işgal ettiğini bildirdi (992)","tur":"savas","onem":3,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Palembang"],"etiket":["srivijaya","konu-siyasi"],"d":"992'de Çin sarayına gelen elçiler Cava'nın (She-p'o) Srivicaya'ya (San-fo-ch'i) saldırısını ve iki ülke arasındaki sürekli düşmanlığı anlattı; Coedès bu Cava saldırısını 990 civarına koyar ve 1016 felaketinin intikamı olarak yorumlar.","kaynak":"G. Coedès, The Indianized States of Southeast Asia, ed. Walter F. Vella, çev. Susan Brown Cowing, Honolulu: East-West Center Press, 1968 (archive.org/details/theindianizedstatesofsoutheastasia; tam metin bu oturumda okundu), «The Javanese Kingdom of Mataram» ve «Srivijaya and Its Relations with the Cholas» bölümleri"},{"t":"0778-01-01","gun":"778 (Coedès, Kalasan yazıtı)","kesinlik":"yil","devlet":"medang","taraflar":["medang"],"devletler":["medang"],"b":"Kalasan yazıtı: Panangkaran Tara tapınağını yaptırdı; Mataram Sailendra egemenliği altında (778)","tur":"siyaset","onem":2,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Yogyakarta"],"etiket":["medang","konu-siyasi"],"d":"Kalasan yazıtına göre Sanjaya hanedanının ikinci kralı Panangkaran 778'de Sailendra hâkimiyeti altında hüküm sürüyor, Tara tapınağını (Candi Kalasan) kuruyordu; Kedu ovası anıtlarının tarihlenmesi bu yazıta dayanır.","kaynak":"G. Coedès, The Indianized States of Southeast Asia, ed. Walter F. Vella, çev. Susan Brown Cowing, Honolulu: East-West Center Press, 1968 (archive.org/details/theindianizedstatesofsoutheastasia; tam metin bu oturumda okundu), «Java: Sanjaya (732) and the Buddhist Sailendras» bölümü"},{"t":"0824-01-01","gun":"824 (Coedès)","kesinlik":"yil","devlet":"medang","taraflar":["medang","srivijaya"],"devletler":["medang","srivijaya"],"b":"Sailendra kralı Samaratunga Cava'da hüküm sürüyor (824); oğlu Balaputra Sumatra'yı yönetiyor","tur":"siyaset","onem":2,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Yogyakarta"],"etiket":["medang","konu-siyasi"],"d":"Coedès, Nalanda Fermanı'ndaki Samaragravira'yı 824'te Cava'da hüküm süren Samaratunga ile özdeşleştirir; oğlu Balaputra (Nalanda fermanı 9. yy ikinci yarısı için geçerli) Sumatra'yı ve Malay yarımadasındaki toprakları babasının otoritesi adına yönetiyordu.","kaynak":"G. Coedès, The Indianized States of Southeast Asia, ed. Walter F. Vella, çev. Susan Brown Cowing, Honolulu: East-West Center Press, 1968 (archive.org/details/theindianizedstatesofsoutheastasia; tam metin bu oturumda okundu), «The Beginnings of the Kingdom of Srivijaya» ve «The Sailendras in Java and Sumatra» bölümleri"},{"t":"0907-01-01","gun":"907 (Coedès, yazıt)","kesinlik":"yil","devlet":"medang","taraflar":["medang"],"devletler":["medang"],"b":"907 tarihli yazıt Sanjaya'yı Mataram prensi ve hanedanın ilk kralı olarak gösterir","tur":"siyaset","onem":2,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Yogyakarta"],"etiket":["medang","konu-siyasi"],"d":"907 tarihli yazıt Sanjaya'yı güney-orta Cava'daki Mataram'ın prensi ve bir kral soyunun ilki olarak gösterir; Kalasan yazıtına göre soyun ikincisi Panangkaran 778'dedir.","kaynak":"G. Coedès, The Indianized States of Southeast Asia, ed. Walter F. Vella, çev. Susan Brown Cowing, Honolulu: East-West Center Press, 1968 (archive.org/details/theindianizedstatesofsoutheastasia; tam metin bu oturumda okundu), «Java: Sanjaya (732) and the Buddhist Sailendras» bölümü"},{"t":"1019-01-01","gun":"1019 (Coedès)","kesinlik":"yil","devlet":"kediri","taraflar":["kediri","medang"],"devletler":["kediri","medang"],"b":"Airlangga resmen Doğu Cava kralı olarak taç giydi (1019)","tur":"taht","onem":3,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Daha (Kediri)"],"etiket":["kediri","konu-siyasi"],"d":"1016 felaketinin (pralaya) ardından dağlarda sığınmış olan Airlangga, soylu ve Brahmanların ısrarıyla 1019'da Sri Maharaja Rakai Halu Sri Lokeswara Dharmawamsa Airlangga Anantawikramottunggadewa unvanıyla resmen taç giydi; yetkisi başlangıçta Surabaya-Pasuruan arasındaki kuzey kıyı şeridini aşmıyordu.","kaynak":"G. Coedès, The Indianized States of Southeast Asia, ed. Walter F. Vella, çev. Susan Brown Cowing, Honolulu: East-West Center Press, 1968 (archive.org/details/theindianizedstatesofsoutheastasia; tam metin bu oturumda okundu), «Java: Airlanga (1016-49)» bölümü"},{"t":"1037-01-01","gun":"1037 (Coedès)","kesinlik":"yil","devlet":"kediri","taraflar":["kediri"],"devletler":["kediri"],"b":"Airlangga düşmanlarını yenip Doğu Cava'nın tahtına tam otoriteyle oturdu (1037)","tur":"taht","onem":2,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Daha (Kediri)"],"etiket":["kediri","konu-siyasi"],"d":"Airlangga 1031'de Adhamapanuda'yı yenip başkentini yaktı; Wengker prensi Vijaya 1035'te öldü; 1037'de Airlangga 'ayaklarını düşmanlarının başına koyarak mücevherli aslan tahtına oturdu'. Wurawari prensiyle çatışma sonrasında da sürmüş olabilir.","kaynak":"G. Coedès, The Indianized States of Southeast Asia, ed. Walter F. Vella, çev. Susan Brown Cowing, Honolulu: East-West Center Press, 1968 (archive.org/details/theindianizedstatesofsoutheastasia; tam metin bu oturumda okundu), «Java: Airlanga (1016-49)» bölümü"},{"t":"1271-01-01","gun":"1271 (Coedès)","kesinlik":"yil","devlet":"singhasari","taraflar":["singhasari","kediri"],"devletler":["singhasari","kediri"],"b":"Jayakatwang Kadiri valisi oldu (1271); 1270'te Bhayaraja, 1280'de Mahisha Rangkah isyanları","tur":"siyaset","onem":2,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Daha (Kediri)"],"etiket":["singhasari","konu-siyasi"],"d":"Kertanagara'nın saltanatında Bhayaraja (1270) ve Mahisha Rangkah (1280) isyan etti; Kadiri valisi Jayakatwang 1271'den beri eski krallardan geliyor olabilecek biri olarak yüksek iktidarın hayalini kuruyordu.","kaynak":"G. Coedès, The Indianized States of Southeast Asia, ed. Walter F. Vella, çev. Susan Brown Cowing, Honolulu: East-West Center Press, 1968 (archive.org/details/theindianizedstatesofsoutheastasia; tam metin bu oturumda okundu), «Java: The End of the Kingdom of Singhasari (1269-92)…» bölümü"},{"t":"1164-01-01","gun":"1164 (Coedès)","kesinlik":"yil","devlet":"pagan","taraflar":["pagan"],"devletler":["pagan"],"b":"Singalalar (muhtemelen) Pagan topraklarını işgal etti (1164)","tur":"siyaset","onem":2,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Pagan"],"etiket":["pagan","konu-siyasi"],"d":"Coedès, Narathu'nun 1165'te yabancılar, muhtemelen bir yıl önce ülkeyi işgal etmiş Singalalar tarafından öldürüldüğünü yazar; işgal yılı 1164'tür.","kaynak":"G. Coedès, The Indianized States of Southeast Asia, ed. Walter F. Vella, çev. Susan Brown Cowing, Honolulu: East-West Center Press, 1968 (archive.org/details/theindianizedstatesofsoutheastasia; tam metin bu oturumda okundu), «Pagan Dynasty of Burma» bölümü (Alaungsithu-Narathu, 1165)"},{"t":"1165-01-01","gun":"1165 (Coedès)","kesinlik":"yil","devlet":"pagan","taraflar":["pagan"],"devletler":["pagan"],"b":"Pagan kralı Narathu yabancılar tarafından öldürüldü (1165); 1165-1173 arası kral bilinmiyor","tur":"taht","onem":3,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Pagan"],"etiket":["pagan","konu-siyasi"],"d":"Alaungsithu'nun ardılı Narathu 1165'te öldürüldü; Coedès Kronik'teki Naratheinkha'nın var olmadığını, 1165-1173 arasında Pagan krallarının bilinmediğini söyler. Narapatisithu 1173'te tahta çıktı (1173-1210).","kaynak":"G. Coedès, The Indianized States of Southeast Asia, ed. Walter F. Vella, çev. Susan Brown Cowing, Honolulu: East-West Center Press, 1968 (archive.org/details/theindianizedstatesofsoutheastasia; tam metin bu oturumda okundu), «Pagan Dynasty of Burma» bölümü (Narathu, 1165; Narapatisithu, 1173)"},{"t":"1173-01-01","gun":"1173 (Coedès)","kesinlik":"yil","devlet":"pagan","taraflar":["pagan"],"devletler":["pagan"],"b":"Narapatisithu Pagan tahtına çıktı (1173-1210); Singala Budizmi'nin girişi","tur":"taht","onem":2,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Pagan"],"etiket":["pagan","konu-siyasi"],"d":"Narapatisithu (Narapatijayasura, Jayasura II) 1173'te tahta çıktı ve 1210'a dek hüküm sürdü; saltanatı Singala (Theravada) Budizmi'nin Burma'ya girişiyle anılır.","kaynak":"G. Coedès, The Indianized States of Southeast Asia, ed. Walter F. Vella, çev. Susan Brown Cowing, Honolulu: East-West Center Press, 1968 (archive.org/details/theindianizedstatesofsoutheastasia; tam metin bu oturumda okundu), «Burma: Narapatisithu (1173-1210) and the Introduction of Singhalese Buddhism» bölümü"},{"t":"1273-03-03","gun":"3 Mart 1273 (Coedès)","kesinlik":"gun","devlet":"pagan","taraflar":["pagan"],"devletler":["pagan"],"b":"Kubilay'ın elçisi Pekin'den Pagan'a hareket etti (3 Mart 1273)","tur":"diplomasi","onem":2,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Pagan"],"etiket":["pagan","konu-siyasi"],"d":"Kubilay Han'ın Pagan'dan prens ve vezirlerden oluşan bir heyet isteyen mektubunu taşıyan elçilik 3 Mart 1273'te Pekin'den çıkıp Pagan'a ulaştı. Narathihapate'nin elçileri öldürttüğü genel kanıdır, ancak Yunnan'da öldürülmüş olmaları da mümkündür.","kaynak":"G. Coedès, The Indianized States of Southeast Asia, ed. Walter F. Vella, çev. Susan Brown Cowing, Honolulu: East-West Center Press, 1968 (archive.org/details/theindianizedstatesofsoutheastasia; tam metin bu oturumda okundu), «Burma: From 1271 to the Seizure of Pagan by the Mongols (1287)» bölümü"},{"t":"1277-01-01","gun":"1277 (Coedès)","kesinlik":"yil","devlet":"pagan","taraflar":["pagan"],"devletler":["pagan"],"b":"Burma ordusu Kubilay'a bağlanan Altın Dişler Devleti'ne (Bhamo yukarısı) saldırdı (1277)","tur":"savas","onem":3,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Bhamo"],"etiket":["pagan","konu-siyasi"],"d":"Narathihapate'nin Burmalıları 1277'de Taping nehri yukarısında Bhamo yakınındaki Altın Dişler Devleti'ne saldırdı; Marco Polo'ya göre Büyük Han'ın bir daha ordu göndermemesi için büyük güçle. Yerel reis Kubilay'dan koruma istedi; Moğol garnizonları harekete geçti.","kaynak":"G. Coedès, The Indianized States of Southeast Asia, ed. Walter F. Vella, çev. Susan Brown Cowing, Honolulu: East-West Center Press, 1968 (archive.org/details/theindianizedstatesofsoutheastasia; tam metin bu oturumda okundu), «Burma: From 1271 to the Seizure of Pagan by the Mongols (1287)» bölümü"},{"t":"1287-01-01","gun":"1287 (Coedès)","kesinlik":"yil","devlet":"pagan","taraflar":["pagan"],"devletler":["pagan"],"b":"Pagan Çin-Moğol birlikleri tarafından alındı (1287); Burma krallığı geçici olarak dağıldı","tur":"fetih","onem":3,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Pagan"],"etiket":["pagan","konu-siyasi"],"d":"1287'de Pagan'ın Moğollarca alınması Burma krallığının geçici olarak ortadan kalkmasına ve ülkenin Tay şeflerince yönetilen prensliklere bölünmesine yol açtı. Coedès bunu aynı yıl Tay şeflerinin ittifakıyla ilişkilendirir.","kaynak":"G. Coedès, The Indianized States of Southeast Asia, ed. Walter F. Vella, çev. Susan Brown Cowing, Honolulu: East-West Center Press, 1968 (archive.org/details/theindianizedstatesofsoutheastasia; tam metin bu oturumda okundu), «The Repercussions of the Mongol Conquests» bölümü (giriş özeti) ve «The Liberation of the Thai of the Menam»"},{"t":"0770-01-01","gun":"770 (Coedès)","kesinlik":"yil","devlet":"chenla","taraflar":["chenla"],"devletler":["chenla"],"b":"Su Chenla'dan Sambor (Sambhupura) yazıtları: kral Jayavarman'ın 770 ve 781 tarihli yazıtları","tur":"siyaset","onem":2,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Sambor (Kratie)"],"etiket":["chenla","konu-siyasi"],"d":"Su Chenla'nın Sambhupura (Sambor) bölgesinden iki yazıt, 770 ve 781 tarihli, Jayavarman adlı bir krala aittir; 791 tarihli Siem Reap yazıtı Kamboçya'da Mahayana Budizmi'nin en eski kanıtıdır.","kaynak":"G. Coedès, The Indianized States of Southeast Asia, ed. Walter F. Vella, çev. Susan Brown Cowing, Honolulu: East-West Center Press, 1968 (archive.org/details/theindianizedstatesofsoutheastasia; tam metin bu oturumda okundu), «Cambodia: The Two Chenlas (Second Half of the Eighth Century)» bölümü"},{"t":"0803-01-01","gun":"803 (Coedès)","kesinlik":"yil","devlet":"chenla","taraflar":["chenla"],"devletler":["chenla"],"b":"Kraliçe Jyeshtharya Sambor'da vakıf yaptı (803), Jayavarman II'nin iktidarından bir yıl sonra","tur":"siyaset","onem":2,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Ishanapura (Sambor Prei Kuk)"],"etiket":["chenla","konu-siyasi"],"d":"Nripendradevi'nin torunu, Indraloka'nın torunu 'kıdemli' kraliçe Jyeshtharya 803'te Sambor'da bir vakıf yaptı; Coedès bunu Jayavarman II'nin 802'deki tahta çıkışının bir yıl sonrası olarak anar ve karışık dönemde Khmer sanatının kesilmediğini vurgular.","kaynak":"G. Coedès, The Indianized States of Southeast Asia, ed. Walter F. Vella, çev. Susan Brown Cowing, Honolulu: East-West Center Press, 1968 (archive.org/details/theindianizedstatesofsoutheastasia; tam metin bu oturumda okundu), «The Beginnings of the Kingdom of Angkor: Jayavarman II (802-50)» bölümü"},{"t":"1250-01-01","gun":"1250 (UNESCO GHA IV)","kesinlik":"yil","devlet":"mali-imparatorlugu","taraflar":["mali-imparatorlugu"],"devletler":["mali-imparatorlugu"],"b":"Mansa Yerelenku (Walin/Ulin) Mali tahtını aldı (1250-c.1270)","tur":"siyaset","onem":2,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Niani"],"etiket":["mali-imparatorlugu","konu-siyasi"],"d":"Sundiata Keita'nın en büyük oğlu Yerelenku (Walin, Ulin) iktidarı devralıp 1250'den yaklaşık 1270'e kadar hüküm sürdü; Mekke'ye hacca gitmesi Arap dünyasının Mali'ye ilgisini çekti. Ölümünden sonra saray entrikalarıyla imparatorluk dağılma noktasına geldi, general Sakura toparladı.","kaynak":"UNESCO, História Geral da África IV: África do século XII ao XVI (ed. D. T. Niane), UNESCO/MEC/UFSCar 2010, cap. 6 «O Mali e a segunda expansão manden» (D. T. Niane), unesdoc.unesco.org/ark:/48223/pf0000190252 (PDF okundu), PDF s. 187 (basılı s. 165-166)"},{"t":"1307-01-01","gun":"1307 (UNESCO GHA IV)","kesinlik":"yil","devlet":"mali-imparatorlugu","taraflar":["mali-imparatorlugu"],"devletler":["mali-imparatorlugu"],"b":"Mansa Musa I (Kanku Musa) Mali tahtına çıktı (1307-c.1332)","tur":"taht","onem":3,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Niani"],"etiket":["mali-imparatorlugu","konu-siyasi"],"d":"Sundiata Keita'nın yeğeni Kanku Musa, mansa Musa I unvanıyla 1307'de tahta çıkıp yaklaşık 1332'ye dek hüküm sürdü; Mali'nin en tanınmış imparatoru oldu.","kaynak":"UNESCO, História Geral da África IV: África do século XII ao XVI (ed. D. T. Niane), UNESCO/MEC/UFSCar 2010, cap. 6 «O Mali e a segunda expansão manden» (D. T. Niane), unesdoc.unesco.org/ark:/48223/pf0000190252 (PDF okundu), PDF s. 187 ve 189 (basılı s. 165, 167)"},{"t":"1325-01-01","gun":"1325 (UNESCO GHA IV)","kesinlik":"yil","devlet":"mali-imparatorlugu","taraflar":["mali-imparatorlugu"],"devletler":["mali-imparatorlugu"],"b":"Mansa Musa Mekke'ye hacca gitti (1325); Kahire'de dağıttığı altın fiyatını düşürdü","tur":"diplomasi","onem":3,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Niani","Mekke"],"etiket":["mali-imparatorlugu","konu-siyasi"],"d":"Mansa Musa I'in 1325'teki Mekke haccı ve Kahire'deki konaklaması, dağıttığı altın yüzünden değerli madenin fiyatını uzun süre düşürmesiyle ünlüdür; Niani'den 60 bin yük taşıyıcılı kervanla ayrıldı, dönüşte Tombuktu'da büyük cami (Djinguereber) ve saray yaptırdı. 1375 haritalarında Sudan, altın külçe tutan Musa resmiyle gösterilir.","kaynak":"UNESCO, História Geral da África IV: África do século XII ao XVI (ed. D. T. Niane), UNESCO/MEC/UFSCar 2010, cap. 6 «O Mali e a segunda expansão manden» (D. T. Niane), unesdoc.unesco.org/ark:/48223/pf0000190252 (PDF okundu), PDF s. 189-190 (basılı s. 167-168)"},{"t":"1336-01-01","gun":"yaklaşık 1336 (UNESCO GHA IV)","kesinlik":"yil","devlet":"mali-imparatorlugu","taraflar":["mali-imparatorlugu"],"devletler":["mali-imparatorlugu"],"b":"Mansa Maghan I Mansa Süleyman tarafından tahttan indirildi (yaklaşık 1336)","tur":"taht","onem":2,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Niani"],"etiket":["mali-imparatorlugu","konu-siyasi"],"d":"Musa I'in oğlu ve ardılı Maghan I (Soma Burema Maghan Kegni), Musa'nın kardeşi mansa Süleyman tarafından yaklaşık 1336'da devrildi.","kaynak":"UNESCO, História Geral da África IV: África do século XII ao XVI (ed. D. T. Niane), UNESCO/MEC/UFSCar 2010, cap. 6 «O Mali e a segunda expansão manden» (D. T. Niane), unesdoc.unesco.org/ark:/48223/pf0000190252 (PDF okundu), PDF s. 187 (basılı s. 165)"},{"t":"1353-01-01","gun":"1353 (UNESCO GHA IV)","kesinlik":"yil","devlet":"mali-imparatorlugu","taraflar":["mali-imparatorlugu"],"devletler":["mali-imparatorlugu"],"b":"Ibn Battuta Mali başkenti Niani'yi ('Malli') ziyaret etti (1353)","tur":"kesif","onem":2,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Niani"],"etiket":["mali-imparatorlugu","konu-siyasi"],"d":"Ibn Battuta Niani'yi 1353'te ziyaret edip 'Malli' diye anar; Niani Sankarani kıyısında, Keita'ların Kirina zaferinden sonra imparatorluk başkenti yaptığı, kuzeye giden Manden yolu ve kuzeydoğuya kervan yoluyla bağlantılı bir şehirdir.","kaynak":"UNESCO, História Geral da África IV: África do século XII ao XVI (ed. D. T. Niane), UNESCO/MEC/UFSCar 2010, cap. 6 «O Mali e a segunda expansão manden» (D. T. Niane), unesdoc.unesco.org/ark:/48223/pf0000190252 (PDF okundu), PDF s. 176 (basılı s. 154) «Niani, capital do Mali»"},{"t":"1359-01-01","gun":"1359 (UNESCO GHA IV)","kesinlik":"yil","devlet":"mali-imparatorlugu","taraflar":["mali-imparatorlugu"],"devletler":["mali-imparatorlugu"],"b":"Fomba (Kassa), mansa Süleyman'ın oğlu, tahtta yalnız bir yıl kaldı (1359)","tur":"taht","onem":2,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Niani"],"etiket":["mali-imparatorlugu","konu-siyasi"],"d":"Süleyman'ın oğlu Fomba (Kassa) tahtı 1359'da yalnız bir yıl elinde tutabildi; ardından Mari Diata II dönemi (hastalık nedeniyle uzaklaştırıldı).","kaynak":"UNESCO, História Geral da África IV: África do século XII ao XVI (ed. D. T. Niane), UNESCO/MEC/UFSCar 2010, cap. 6 «O Mali e a segunda expansão manden» (D. T. Niane), unesdoc.unesco.org/ark:/48223/pf0000190252 (PDF okundu), PDF s. 187 (basılı s. 165)"},{"t":"1374-01-01","gun":"1374 (UNESCO GHA IV)","kesinlik":"yil","devlet":"mali-imparatorlugu","taraflar":["mali-imparatorlugu"],"devletler":["mali-imparatorlugu"],"b":"Mansa Musa II tahta çıktı (1374-1387); fiilî yönetici başkasıydı","tur":"taht","onem":2,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Niani"],"etiket":["mali-imparatorlugu","konu-siyasi"],"d":"Mari Diata II (uyku hastalığı) iktidardan uzaklaşınca oğlu Musa II 1374-1387 arasında tahtta oturdu; GHA IV, fiilen yönetenin başka biri olduğunu Ibn Haldun'a dayanarak yazar.","kaynak":"UNESCO, História Geral da África IV: África do século XII ao XVI (ed. D. T. Niane), UNESCO/MEC/UFSCar 2010, cap. 6 «O Mali e a segunda expansão manden» (D. T. Niane), unesdoc.unesco.org/ark:/48223/pf0000190252 (PDF okundu), PDF s. 187 (basılı s. 165)"},{"t":"1390-01-01","gun":"1390 (UNESCO GHA IV)","kesinlik":"yil","devlet":"mali-imparatorlugu","taraflar":["mali-imparatorlugu"],"devletler":["mali-imparatorlugu"],"b":"Maghan III'ün tahta çıkışı (1390), Ibn Haldun tarafından anılır","tur":"taht","onem":2,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Niani"],"etiket":["mali-imparatorlugu","konu-siyasi"],"d":"Maghan III'ün 1390'daki saltanat başlangıcı Ibn Haldun'un Berberiler Tarihi'ne konu olur; bu tarih Susu kralı Sumaoro'nun saltanatının (1200-1235 göreli kronoloji) ad quem sınırını verir.","kaynak":"UNESCO, História Geral da África IV: África do século XII ao XVI (ed. D. T. Niane), UNESCO/MEC/UFSCar 2010, cap. 6 «O Mali e a segunda expansão manden» (D. T. Niane), unesdoc.unesco.org/ark:/48223/pf0000190252 (PDF okundu), PDF s. 164 (basılı s. 142) ve s. 187"},{"t":"0570-01-01","gun":"570 (UNESCO GHA III)","kesinlik":"yil","devlet":"aksum","taraflar":["aksum"],"devletler":["aksum"],"b":"Sasani İranı Güney Arabistan'ı fethetti (570); Pers egemenliği 628'e dek sürdü","tur":"kayip","onem":3,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Sana"],"etiket":["aksum","konu-siyasi"],"d":"Madagaskar-Hint Okyanusu ticaretini anlatan bölüm, Aksum ve Bizans'ın Sasani Pers'e karşı etkisizliğini Güney Arabistan'ın 570'te Perslerce fethiyle ilişkilendirir; Pers egemenliği son vali İslam'a geçene (628) kadar sürdü.","kaynak":"UNESCO, História Geral da África III: África do século VII ao XI (ed. M. El Fasi), UNESCO/MEC/UFSCar 2010, unesdoc.unesco.org/ark:/48223/pf0000190251 (PDF okundu), PDF s. 834 (bölüm: Afrika diasporası / Hint Okyanusu)"},{"t":"0628-01-01","gun":"628 (UNESCO GHA III)","kesinlik":"yil","devlet":"aksum","taraflar":["aksum"],"devletler":["aksum"],"b":"Güney Arabistan'ın son Pers valisi İslam'a girdi (628); Pers egemenliği sona erdi","tur":"siyaset","onem":2,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Sana"],"etiket":["aksum","konu-siyasi"],"d":"Güney Arabistan'ı 570'ten itibaren elinde tutan Sasani Pers'in son valisi 628'de İslam'a geçti ve Pers egemenliği sona erdi.","kaynak":"UNESCO, História Geral da África III: África do século VII ao XI (ed. M. El Fasi), UNESCO/MEC/UFSCar 2010, unesdoc.unesco.org/ark:/48223/pf0000190251 (PDF okundu), PDF s. 834"},{"t":"0990-01-01","gun":"380 H. / 990 (UNESCO GHA III)","kesinlik":"yil","devlet":"wagadu-gane-erken","taraflar":["wagadu-gane-erken"],"devletler":["wagadu-gane-erken"],"b":"Gana, 990'dan sonra Awdaghust'ı ekonomik olarak ve ardından siyasi olarak egemenliği altına aldı","tur":"siyaset","onem":2,"dunya":1,"kapsam":"dis","yer_id":"","odak_yer":["Awdaghust (Aoudaghost)"],"etiket":["wagadu-gane-erken","konu-siyasi"],"d":"UNESCO GHA III: Gana imparatorluğu 380/990'dan sonra Zanata tüccarlarının faaliyetleri sayesinde Awdaghust'a ekonomik, dolayısıyla siyasi hegemonya kurabildi; bir yüzyıl sonra aynı Gana Murabıtların baskısı altında üstünlüğünü yitirdi. GHA III, Murabıtların 469/1076'da Gana'yı fethettiği görüşünün Conrad, Fisher, Sanneh ve Hiskett'in çalışmalarıyla ciddi biçimde sorgulandığını, fethin hiç gerçekleşmemiş olabileceğini de kaydeder.","kaynak":"UNESCO, História Geral da África III: África do século VII ao XI (ed. M. El Fasi), UNESCO/MEC/UFSCar 2010, unesdoc.unesco.org/ark:/48223/pf0000190251 (PDF okundu), PDF s. 185 (Awdaghust/Gana) ve s. 119 (Murabıt fethi tartışması)"}];

